// ============================================================
// CODE-001 – Build Context
// ============================================================
// Purpose:
// Build one unified context for the assignment engine.
//
// Sources:
//   GS-003 – Read EngineerMaster
//   GS-004 – Read WeeklyRoster
//   GS-005 – Read SupportCalendar
//
// This node DOES NOT:
//   - create engineers
//   - modify WeeklyRoster
//   - modify EngineerMaster
//   - modify SupportCalendar
//   - assign tickets
//
// It only combines the required data into one context object.
// ============================================================


// ============================================================
// 1. READ ENGINEER MASTER
// ============================================================

let engineerMasterItems = [];

try {
  engineerMasterItems =
    $("GS-003 – Read EngineerMaster").all();
} catch (error) {
  engineerMasterItems = [];
}

if (!engineerMasterItems.length) {
  throw new Error(
    "CODE-001: GS-003 – Read EngineerMaster returned no data."
  );
}


// ============================================================
// 2. READ WEEKLY ROSTER
// ============================================================

let weeklyRosterItems = [];

try {
  weeklyRosterItems =
    $("GS-004 – Read WeeklyRoster").all();
} catch (error) {
  weeklyRosterItems = [];
}

if (!weeklyRosterItems.length) {
  throw new Error(
    "CODE-001: GS-004 – Read WeeklyRoster returned no data."
  );
}


// ============================================================
// 3. READ SUPPORT CALENDAR
// ============================================================

let supportCalendarItems = [];

try {
  supportCalendarItems =
    $("GS-005 Read SupportCalendar").all();
} catch (error) {
  supportCalendarItems = [];
}

if (!supportCalendarItems.length) {
  throw new Error(
    "CODE-001: GS-005 – Read SupportCalendar returned no data."
  );
}


// ============================================================
// 4. NORMALIZE ENGINEER MASTER
// ============================================================

const engineerMaster =
  engineerMasterItems.map(item => {

    const row = item.json || {};

    return {
      ...row
    };

  });


// ============================================================
// 5. NORMALIZE WEEKLY ROSTER
// ============================================================

const weeklyRoster =
  weeklyRosterItems.map(item => {

    const row = item.json || {};

    return {
      Effective_From:
        String(row.Effective_From ?? "").trim(),

      Effective_To:
        String(row.Effective_To ?? "").trim(),

      Day:
        String(row.Day ?? "").trim(),

      Shift_ID:
        String(row.Shift_ID ?? "").trim(),

      Engineer_Name:
        String(row.Engineer_Name ?? "").trim(),

      Member_ID:
        String(row.Member_ID ?? "").trim(),

      Assignment_Level:
        String(row.Assignment_Level ?? "").trim(),

      Available:
        String(row.Available ?? "Yes").trim()
    };

  });


// ============================================================
// 6. NORMALIZE SUPPORT CALENDAR
// ============================================================

const supportCalendar =
  supportCalendarItems.map(item => {

    const row = item.json || {};

    return {

      Day:
        String(row.Day ?? "").trim(),

      Business_Start:
        String(row.Business_Start ?? "").trim(),

      Business_End:
        String(row.Business_End ?? "").trim(),

      Active_Shifts:
        String(row.Active_Shifts ?? "").trim(),

      Allowed_Levels:
        String(row.Allowed_Levels ?? "").trim(),

      Max_L1:
        Number(row.Max_L1 ?? 0),

      Max_L2:
        Number(row.Max_L2 ?? 0),

      Max_L3:
        Number(row.Max_L3 ?? 0),

      Assignment_Mode:
        String(row.Assignment_Mode ?? "").trim(),

      Timezone:
        String(row.Timezone ?? "Asia/Kolkata").trim(),

      Active:
        String(row.Active ?? "No").trim()
    };

  });


// ============================================================
// 7. CURRENT DATE / TIME
// ============================================================
//
// Use Asia/Kolkata because this is the configured timezone
// for your SupportCalendar.
// ============================================================

const now = new Date();

const currentDate =
  new Intl.DateTimeFormat(
    "en-CA",
    {
      timeZone: "Asia/Kolkata",
      year: "numeric",
      month: "2-digit",
      day: "2-digit"
    }
  ).format(now);

const currentTime =
  new Intl.DateTimeFormat(
    "en-GB",
    {
      timeZone: "Asia/Kolkata",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }
  ).format(now);

const currentDay =
  new Intl.DateTimeFormat(
    "en-US",
    {
      timeZone: "Asia/Kolkata",
      weekday: "long"
    }
  ).format(now);


// ============================================================
// 8. FIND TODAY'S SUPPORT CALENDAR RULE
// ============================================================

const todayCalendarRule =
  supportCalendar.find(
    row =>
      row.Day.toLowerCase() ===
      currentDay.toLowerCase()
  ) || null;


// ============================================================
// 9. DETERMINE WHETHER TODAY IS ACTIVE
// ============================================================

const todayActive =
  todayCalendarRule
    ? String(todayCalendarRule.Active)
        .trim()
        .toLowerCase() === "yes"
    : false;


// ============================================================
// 10. FIND CURRENT ROSTER PERIOD
// ============================================================
//
// A roster record is considered part of the current period
// when CurrentDate falls between Effective_From and
// Effective_To.
// ============================================================

const currentPeriodRoster =
  weeklyRoster.filter(row => {

    if (
      !row.Effective_From ||
      !row.Effective_To
    ) {
      return false;
    }

    return (
      currentDate >= row.Effective_From &&
      currentDate <= row.Effective_To
    );

  });


// ============================================================
// 11. FIND TODAY'S ROSTER
// ============================================================

const todayRoster =
  currentPeriodRoster.filter(row => {

    return (
      row.Day.toLowerCase() ===
      currentDay.toLowerCase()
    );

  });


// ============================================================
// 12. RETURN UNIFIED CONTEXT
// ============================================================

return [
  {
    json: {

      // ------------------------------------------------------
      // Workflow Context
      // ------------------------------------------------------

      WorkflowContext: {

        Timestamp:
          now.toISOString(),

        Timezone:
          "Asia/Kolkata",

        CurrentDate:
          currentDate,

        CurrentDay:
          currentDay,

        CurrentTime:
          currentTime,

        TodayActive:
          todayActive

      },


      // ------------------------------------------------------
      // Engineer Master
      // ------------------------------------------------------

      EngineerMaster:
        engineerMaster,

      EngineerMasterCount:
        engineerMaster.length,


      // ------------------------------------------------------
      // Weekly Roster
      // ------------------------------------------------------

      WeeklyRoster:
        weeklyRoster,

      WeeklyRosterCount:
        weeklyRoster.length,


      // ------------------------------------------------------
      // Current Roster Period
      // ------------------------------------------------------

      CurrentPeriodRoster:
        currentPeriodRoster,

      CurrentPeriodRosterCount:
        currentPeriodRoster.length,


      // ------------------------------------------------------
      // Today's Roster
      // ------------------------------------------------------

      TodayRoster:
        todayRoster,

      TodayRosterCount:
        todayRoster.length,


      // ------------------------------------------------------
      // Support Calendar
      // ------------------------------------------------------

      SupportCalendar:
        supportCalendar,

      SupportCalendarCount:
        supportCalendar.length,


      // ------------------------------------------------------
      // Today's Calendar Rule
      // ------------------------------------------------------

      TodayCalendarRule:
        todayCalendarRule,


      // ------------------------------------------------------
      // Status
      // ------------------------------------------------------

      Status:
        "CODE-001 OK"

    }
  }
];

// ============================================================
// CW-000A – Save Tickets
// ============================================================
// Purpose:
// Preserve each incoming ConnectWise ticket as an individual
// n8n item.
//
// IMPORTANT:
// Do NOT wrap all tickets into a single Tickets array.
// Each ticket must remain a separate item so downstream
// assignment and scheduling nodes process tickets independently.
// ============================================================

const tickets = $input.all();

return tickets.map(item => ({
  json: item.json
}));

// ============================================================
// CODE-000B – Save & Apply Exclusions
// ============================================================
// PURPOSE:
//   1. Read ALL tickets from CODE-000A
//   2. Read ALL exclusion rules from GS-001
//   3. Evaluate each ticket against enabled exclusion rules
//   4. Remove excluded tickets from the normal Tickets list
//   5. Preserve excluded tickets separately for audit/debugging
//
// IMPORTANT:
//   - Matching is CASE-INSENSITIVE
//   - Match_Type = Contains is supported
//   - Enabled = Yes is required
//   - Ticket subject/summary is checked
//
// RESULT:
//
//   Tickets          = tickets allowed to continue
//   ExcludedTickets  = tickets blocked from assignment
//   Exclusions       = original exclusion rules
//
// EXCLUDED TICKETS MUST NOT CONTINUE TO ASSIGNMENT ENGINE.
// ============================================================


// ============================================================
// 1. GET TICKETS
// ============================================================

const ticketItems = $('CODE-000A - Save Tickets').all();

const tickets = ticketItems.map(item => item.json || {});


// ============================================================
// 2. GET EXCLUSION RULES
// ============================================================

const exclusionItems = $input.all();

const exclusions = exclusionItems
  .map(item => item.json || {});


// ============================================================
// 3. HELPER FUNCTIONS
// ============================================================

function clean(value) {

  if (
    value === undefined ||
    value === null
  ) {
    return '';
  }

  return String(value).trim();
}


function normalize(value) {

  return clean(value)
    .toLowerCase()
    .replace(/\s+/g, ' ');
}


// ============================================================
// 4. GET TICKET SUBJECT / SUMMARY
// ============================================================
//
// ConnectWise data can arrive with different field names.
// We check the common possibilities.
//
// ============================================================

function getTicketSummary(ticket) {

  const candidates = [

    ticket.TicketSummary,
    ticket.TicketSubject,

    ticket.summary,
    ticket.Summary,

    ticket.subject,
    ticket.Subject,

    ticket.Title,
    ticket.title,

    ticket.Description,
    ticket.description

  ];

  for (const value of candidates) {

    const text = clean(value);

    if (text) {
      return text;
    }

  }

  return '';
}


// ============================================================
// 5. DETERMINE IF EXCLUSION RULE IS ENABLED
// ============================================================

function isEnabled(rule) {

  const value = normalize(
    rule.Enabled
  );

  return (
    value === 'yes' ||
    value === 'true' ||
    value === '1'
  );
}


// ============================================================
// 6. GET MATCH TYPE
// ============================================================

function getMatchType(rule) {

  return normalize(
    rule.Match_Type ??
    rule.MatchType ??
    rule.match_type ??
    rule.matchType ??
    'Contains'
  );
}


// ============================================================
// 7. GET EXCLUSION TEXT
// ============================================================

function getExclusionText(rule) {

  return clean(

    rule.Summary_Contains ??
    rule.SummaryContains ??
    rule.summary_contains ??
    rule.summaryContains ??

    ''
  );
}


// ============================================================
// 8. EVALUATE ONE TICKET
// ============================================================

function evaluateTicket(ticket) {

  const summary =
    getTicketSummary(ticket);

  const normalizedSummary =
    normalize(summary);


  // ----------------------------------------------------------
  // No subject/summary
  // ----------------------------------------------------------

  if (!normalizedSummary) {

    return {

      excluded: false,

      matchedRule: null,

      summary: summary

    };

  }


  // ----------------------------------------------------------
  // CHECK EVERY EXCLUSION RULE
  // ----------------------------------------------------------

  for (const rule of exclusions) {

    // Disabled rule → ignore

    if (!isEnabled(rule)) {
      continue;
    }


    const exclusionText =
      getExclusionText(rule);


    // Empty exclusion → ignore

    if (!exclusionText) {
      continue;
    }


    const normalizedExclusion =
      normalize(exclusionText);


    const matchType =
      getMatchType(rule);


    // --------------------------------------------------------
    // CONTAINS
    // --------------------------------------------------------

    if (
      matchType === 'contains'
    ) {

      if (
        normalizedSummary.includes(
          normalizedExclusion
        )
      ) {

        return {

          excluded: true,

          matchedRule: rule,

          summary: summary

        };

      }

    }


    // --------------------------------------------------------
    // EXACT MATCH
    // --------------------------------------------------------

    else if (
      matchType === 'exact' ||
      matchType === 'equals' ||
      matchType === 'equal'
    ) {

      if (
        normalizedSummary ===
        normalizedExclusion
      ) {

        return {

          excluded: true,

          matchedRule: rule,

          summary: summary

        };

      }

    }

  }


  // ----------------------------------------------------------
  // NO MATCH
  // ----------------------------------------------------------

  return {

    excluded: false,

    matchedRule: null,

    summary: summary

  };

}


// ============================================================
// 9. PROCESS ALL TICKETS
// ============================================================

const allowedTickets = [];
const excludedTickets = [];


// Statistics

let matchedCount = 0;
let noMatchCount = 0;
let noSummaryCount = 0;


for (
  let i = 0;
  i < tickets.length;
  i++
) {

  const ticket =
    tickets[i];


  const evaluation =
    evaluateTicket(ticket);


  // ----------------------------------------------------------
  // EXCLUDED
  // ----------------------------------------------------------

  if (
    evaluation.excluded
  ) {

    matchedCount++;


    const rule =
      evaluation.matchedRule;


    excludedTickets.push({

      ...ticket,


      // ------------------------------------------------------
      // EXCLUSION INFORMATION
      // ------------------------------------------------------

      ExclusionApplied:
        true,

      ExclusionReason:
        getExclusionText(rule),

      ExclusionMatchType:
        getMatchType(rule),

      ExclusionRule:
        rule,

      ExclusionSubject:
        evaluation.summary

    });


    continue;

  }


  // ----------------------------------------------------------
  // NOT EXCLUDED
  // ----------------------------------------------------------

  noMatchCount++;


  if (
    !evaluation.summary
  ) {

    noSummaryCount++;

  }


  allowedTickets.push(ticket);

}


// ============================================================
// 10. BUILD OUTPUT
// ============================================================

return [

  {

    json: {

      Status:
        'MODULE-000B OK',


      // ------------------------------------------------------
      // ORIGINAL COUNTS
      // ------------------------------------------------------

      OriginalTicketCount:
        tickets.length,

      ExclusionRuleCount:
        exclusions.length,


      // ------------------------------------------------------
      // RESULTS
      // ------------------------------------------------------

      IncludedTicketCount:
        allowedTickets.length,

      ExcludedTicketCount:
        excludedTickets.length,


      // ------------------------------------------------------
      // DIAGNOSTICS
      // ------------------------------------------------------

      ExclusionMatchedCount:
        matchedCount,

      NoExclusionMatchCount:
        noMatchCount,

      TicketsWithoutSummary:
        noSummaryCount,


      // ------------------------------------------------------
      // NORMAL PROCESSING TICKETS
      //
      // ONLY THESE TICKETS SHOULD CONTINUE
      // TO THE ASSIGNMENT ENGINE.
      // ------------------------------------------------------

      Tickets:
        allowedTickets,


      // ------------------------------------------------------
      // EXCLUDED TICKETS
      //
      // These are intentionally separated and MUST NOT
      // continue to assignment.
      // ------------------------------------------------------

      ExcludedTickets:
        excludedTickets,


      // ------------------------------------------------------
      // ORIGINAL EXCLUSION RULES
      // ------------------------------------------------------

      Exclusions:
        exclusions,


      // ------------------------------------------------------
      // DEBUG
      // ------------------------------------------------------

      Debug: {

        ProcessingRule:
          'Enabled exclusion + case-insensitive subject Contains match',

        ExcludedTicketsRemovedFromTickets:
          true,

        ExcludedTicketsRemainInExcludedTickets:
          true,

        AssignmentAllowedForExcludedTickets:
          false

      }

    }

  }

];

const ctx = $('CODE-000B - Save Exclusions').first().json;

return [
{
  json: {
    Tickets: ctx.Tickets,
    Exclusions: ctx.Exclusions,
    Shifts: $input.all()
  }
}
];

const ctx = $('CODE-000C - Save Shifts').first().json;

return [
{
  json: {
    ...ctx,
    Engineers: $input.all()
  }
}
];

// ============================================================
// CODE-000E – Save SupportCalendar
// ============================================================
// Purpose:
// Package WeeklyRoster + SupportCalendar for the next stage.
//
// EngineerMaster is NOT read here.
// EngineerMaster is handled separately by CODE-000D.
//
// IMPORTANT:
// - Does NOT create engineers.
// - Does NOT modify OriginalRoster.
// - Does NOT modify WeeklyRoster.
// - Removes duplicate WeeklyRoster records.
// - Keeps Saturday / Sunday rules explicitly available.
//
// SATURDAY RULE:
// - Saturday has ONLY S2 active.
// - Saturday allows ONLY Level1.
// - Level2 escalation is NOT allowed.
// - Level3 escalation is NOT allowed.
// - Max_L1 = 10 tickets per eligible Level1 engineer.
// - Multiple Saturday tickets can therefore be assigned.
// ============================================================


// ============================================================
// 1. READ SUPPORT CALENDAR
// ============================================================

const supportCalendar = $input.all();

if (!supportCalendar.length) {
  throw new Error(
    "CODE-000E: SupportCalendar input is empty."
  );
}


// ============================================================
// 2. READ WEEKLY ROSTER
// ============================================================

let rosterItems = [];

try {
  rosterItems = $("GS-004 – Read WeeklyRoster").all();
} catch (error) {
  rosterItems = [];
}

if (!rosterItems.length) {
  throw new Error(
    "CODE-000E: GS-004 – Read WeeklyRoster returned no data."
  );
}


// ============================================================
// 3. DEDUPLICATE WEEKLY ROSTER
// ============================================================
//
// Unique record is identified by:
//
// Effective_From
// Effective_To
// Day
// Shift_ID
// Member_ID
//
// This prevents the same engineer/day/shift from being
// passed multiple times to the Assignment Engine.
// ============================================================

const uniqueRoster = [];
const seenRosterKeys = new Set();

for (const item of rosterItems) {

  const row = item.json || {};

  const effectiveFrom =
    String(row.Effective_From ?? "").trim();

  const effectiveTo =
    String(row.Effective_To ?? "").trim();

  const day =
    String(row.Day ?? "").trim();

  const shiftId =
    String(row.Shift_ID ?? "").trim();

  const memberId =
    String(row.Member_ID ?? "").trim();

  const engineerName =
    String(row.Engineer_Name ?? "").trim();

  const assignmentLevel =
    String(row.Assignment_Level ?? "").trim();

  const available =
    String(row.Available ?? "Yes").trim();


  // ----------------------------------------------------------
  // Validate minimum required roster fields
  // ----------------------------------------------------------

  if (
    !effectiveFrom ||
    !effectiveTo ||
    !day ||
    !shiftId ||
    !memberId
  ) {
    throw new Error(
      `CODE-000E: Invalid WeeklyRoster record. ` +
      `Missing required field for engineer "${engineerName}".`
    );
  }


  // ----------------------------------------------------------
  // Create unique key
  // ----------------------------------------------------------

  const rosterKey = [
    effectiveFrom,
    effectiveTo,
    day.toLowerCase(),
    shiftId.toUpperCase(),
    memberId.toLowerCase()
  ].join("|");


  // ----------------------------------------------------------
  // Skip duplicate
  // ----------------------------------------------------------

  if (seenRosterKeys.has(rosterKey)) {
    continue;
  }

  seenRosterKeys.add(rosterKey);


  // ----------------------------------------------------------
  // Store unique roster record
  // ----------------------------------------------------------

  uniqueRoster.push({
    Effective_From: effectiveFrom,
    Effective_To: effectiveTo,
    Day: day,
    Shift_ID: shiftId,
    Engineer_Name: engineerName,
    Member_ID: memberId,
    Assignment_Level: assignmentLevel,
    Available: available
  });
}


// ============================================================
// 4. VALIDATE UNIQUE ROSTER
// ============================================================

if (uniqueRoster.length === 0) {
  throw new Error(
    "CODE-000E: No valid unique WeeklyRoster records were generated."
  );
}


// ============================================================
// 5. NORMALIZE SUPPORT CALENDAR
// ============================================================

const calendar = supportCalendar.map(item => {

  const row = item.json || {};

  return {

    Day:
      String(row.Day ?? "").trim(),

    Business_Start:
      String(row.Business_Start ?? "").trim(),

    Business_End:
      String(row.Business_End ?? "").trim(),

    Active_Shifts:
      String(row.Active_Shifts ?? "").trim(),

    Allowed_Levels:
      String(row.Allowed_Levels ?? "").trim(),

    Max_L1:
      Number(row.Max_L1 ?? 0),

    Max_L2:
      Number(row.Max_L2 ?? 0),

    Max_L3:
      Number(row.Max_L3 ?? 0),

    Assignment_Mode:
      String(row.Assignment_Mode ?? "").trim(),

    Timezone:
      String(row.Timezone ?? "Asia/Kolkata").trim(),

    Active:
      String(row.Active ?? "No").trim()
  };
});


// ============================================================
// 6. VALIDATE SUPPORT CALENDAR
// ============================================================

if (calendar.length === 0) {
  throw new Error(
    "CODE-000E: SupportCalendar contains no records."
  );
}


// ============================================================
// 7. FIND SATURDAY RULE
// ============================================================

const saturdayRule =
  calendar.find(
    row =>
      String(row.Day).trim().toLowerCase() === "saturday"
  );


// ============================================================
// 8. FIND SUNDAY RULE
// ============================================================

const sundayRule =
  calendar.find(
    row =>
      String(row.Day).trim().toLowerCase() === "sunday"
  );


// ============================================================
// 9. VALIDATE SATURDAY RULE
// ============================================================
//
// Saturday business rule:
//
//   Active Shift   = S2 only
//   Allowed Level  = Level1 only
//   Max L1         = 10
//   Max L2         = 0
//   Max L3         = 0
//
// IMPORTANT:
// Max_L1 = 10 means EACH eligible Level1 engineer can
// carry up to 10 active tickets.
//
// It does NOT mean Saturday can process only 10 tickets.
//
// Example:
//
//   L1 Engineer A = 10 tickets
//   L1 Engineer B = 10 tickets
//   L1 Engineer C = 10 tickets
//
// Total possible workload = 30 tickets.
//
// RoundRobin + workload logic decides distribution.
// ============================================================

if (!saturdayRule) {

  throw new Error(
    "CODE-000E: Saturday SupportCalendar rule was not found."
  );
}


// ------------------------------------------------------------
// Saturday active shifts
// ------------------------------------------------------------

const saturdayShifts =
  String(saturdayRule.Active_Shifts || "")
    .split(",")
    .map(x => x.trim())
    .filter(Boolean);


// ------------------------------------------------------------
// Saturday allowed levels
// ------------------------------------------------------------

const saturdayLevels =
  String(saturdayRule.Allowed_Levels || "")
    .split(",")
    .map(x => x.trim())
    .filter(Boolean);


// ------------------------------------------------------------
// Validate Saturday shift
// ------------------------------------------------------------

if (
  saturdayShifts.length !== 1 ||
  saturdayShifts[0].toUpperCase() !== "S2"
) {

  throw new Error(
    `CODE-000E: Invalid Saturday shift rule. ` +
    `Expected S2 only, found "${saturdayRule.Active_Shifts}".`
  );
}


// ------------------------------------------------------------
// Validate Saturday assignment level
// ------------------------------------------------------------

if (
  saturdayLevels.length !== 1 ||
  saturdayLevels[0].toLowerCase() !== "level1"
) {

  throw new Error(
    `CODE-000E: Invalid Saturday level rule. ` +
    `Expected Level1 only, found "${saturdayRule.Allowed_Levels}".`
  );
}


// ------------------------------------------------------------
// Validate Saturday Max_L1
// ------------------------------------------------------------
//
// Saturday now supports up to 10 active tickets
// per eligible Level1 engineer.
// ------------------------------------------------------------

if (Number(saturdayRule.Max_L1) !== 10) {

  throw new Error(
    `CODE-000E: Invalid Saturday Max_L1. ` +
    `Expected 10, found ${saturdayRule.Max_L1}.`
  );
}


// ------------------------------------------------------------
// Validate Saturday Max_L2
// ------------------------------------------------------------
//
// Saturday MUST NOT allow Level2 escalation.
// ------------------------------------------------------------

if (Number(saturdayRule.Max_L2) !== 0) {

  throw new Error(
    `CODE-000E: Invalid Saturday Max_L2. ` +
    `Expected 0, found ${saturdayRule.Max_L2}.`
  );
}


// ------------------------------------------------------------
// Validate Saturday Max_L3
// ------------------------------------------------------------
//
// Saturday MUST NOT allow Level3 escalation.
// ------------------------------------------------------------

if (Number(saturdayRule.Max_L3) !== 0) {

  throw new Error(
    `CODE-000E: Invalid Saturday Max_L3. ` +
    `Expected 0, found ${saturdayRule.Max_L3}.`
  );
}


// ============================================================
// 10. VALIDATE SUNDAY RULE
// ============================================================

if (!sundayRule) {

  throw new Error(
    "CODE-000E: Sunday SupportCalendar rule was not found."
  );
}


const sundayActive =
  String(sundayRule.Active)
    .trim()
    .toLowerCase();


if (sundayActive === "yes") {

  throw new Error(
    "CODE-000E: Sunday must be disabled according to SupportCalendar."
  );
}


// ============================================================
// 11. CALCULATE COUNTS
// ============================================================

const originalRosterCount =
  rosterItems.length;

const uniqueRosterCount =
  uniqueRoster.length;

const duplicateRosterCount =
  originalRosterCount - uniqueRosterCount;

const activeSupportDays =
  calendar.filter(
    row =>
      String(row.Active)
        .trim()
        .toLowerCase() === "yes"
  ).length;


// ============================================================
// 12. RETURN FINAL CONTEXT
// ============================================================

return [
  {
    json: {

      // ------------------------------------------------------
      // Status
      // ------------------------------------------------------

      Status:
        "CODE-000E OK",

      GeneratedAtUTC:
        new Date().toISOString(),


      // ------------------------------------------------------
      // WeeklyRoster
      // ------------------------------------------------------

      WeeklyRoster:
        uniqueRoster,

      WeeklyRosterCount:
        uniqueRosterCount,

      OriginalWeeklyRosterCount:
        originalRosterCount,

      DuplicateWeeklyRosterCount:
        duplicateRosterCount,


      // ------------------------------------------------------
      // SupportCalendar
      // ------------------------------------------------------

      SupportCalendar:
        calendar,

      SupportCalendarCount:
        calendar.length,

      ActiveSupportDays:
        activeSupportDays,


      // ------------------------------------------------------
      // Saturday rule
      // ------------------------------------------------------

      SaturdayRule: {

        Active: true,

        Active_Shifts:
          ["S2"],

        Allowed_Levels:
          ["Level1"],

        // Maximum active tickets PER Level1 engineer
        Max_L1:
          10,

        // No Level2 escalation on Saturday
        Max_L2:
          0,

        // No Level3 escalation on Saturday
        Max_L3:
          0,

        // Explicitly document Saturday behavior
        EscalationAllowed:
          false,

        AssignmentMode:
          saturdayRule.Assignment_Mode || "RoundRobin"
      },


      // ------------------------------------------------------
      // Sunday rule
      // ------------------------------------------------------

      SundayRule: {

        Active: false,

        AssignmentAllowed:
          false
      }

    }
  }
];

// ============================================================
// CODE-003 – Live Availability
// MODULE 03 - CONNECTWISE LIVE AVAILABILITY
//
// Purpose:
//   Normalize ConnectWise In/Out Board data and determine
//   whether each engineer is CURRENTLY OUT.
//
// BUSINESS RULE – DateBack:
//
//   DateBack > CurrentDate
//       → OUT
//
//   DateBack = CurrentDate
//       → AVAILABLE / IN
//
//   DateBack < CurrentDate
//       → AVAILABLE / IN
//
//   No DateBack
//       → AVAILABLE / IN
//
// IMPORTANT:
//
//   CODE-003 ONLY evaluates ConnectWise live availability.
//
//   It does NOT:
//     - check WeeklyRoster
//     - check SupportCalendar
//     - check current shift
//     - assign engineers
//     - perform escalation
//     - update ConnectWise tickets
//
// DATE/TIME:
//
//   No hardcoded test date is used.
//
//   Current date/time is calculated dynamically using the
//   configured workflow timezone.
//
//   Default timezone is Asia/Kolkata if configuration is
//   unavailable.
//
// ============================================================


// ------------------------------------------------------------
// 1. GET INPUT FROM CW-003
// ------------------------------------------------------------

const inputItems = $input.all();

if (!inputItems.length) {
    throw new Error(
        "CODE-003: CW-003 – Get InOut Board returned no data."
    );
}


// ------------------------------------------------------------
// 2. GET WORKFLOW TIMEZONE DYNAMICALLY
//
// Preferred source:
//   CFG-001 - Workflow Config
//
// Expected field:
//   TimeZone
//
// Fallback:
//   Asia/Kolkata
//
// This fallback is only for protection. The date itself is
// NEVER hardcoded.
// ------------------------------------------------------------

let timezone = "Asia/Kolkata";

try {

    const configItems =
        $("CFG-001 - Workflow Config").all();

    if (configItems.length) {

        const config =
            configItems[0].json || {};

        if (
            config.TimeZone &&
            String(config.TimeZone).trim()
        ) {

            timezone =
                String(config.TimeZone).trim();

        }

    }

} catch (error) {

    // Keep the safe timezone fallback.
    // Do not stop the workflow if configuration
    // cannot be read.

}


// ------------------------------------------------------------
// 3. DETERMINE CURRENT DATE/TIME DYNAMICALLY
//
// $now is the n8n Luxon DateTime object.
//
// We explicitly convert it to the configured timezone.
// ------------------------------------------------------------

const now =
    $now.setZone(timezone);

const currentDate =
    now.toFormat("yyyy-MM-dd");

const currentDay =
    now.toFormat("cccc");

const currentTime =
    now.toFormat("HH:mm");


// ------------------------------------------------------------
// 4. FLATTEN CONNECTWISE RECORDS
//
// Supports:
//
// A) Multiple n8n items containing individual records
//
// B) One n8n item containing an array of records
// ------------------------------------------------------------

const rawRecords = [];

for (const item of inputItems) {

    const data =
        item.json;

    // Case A:
    // Item contains an array
    if (Array.isArray(data)) {

        for (const record of data) {

            if (
                record &&
                typeof record === "object"
            ) {

                rawRecords.push(record);

            }

        }

    }

    // Case B:
    // Item contains one object
    else if (
        data &&
        typeof data === "object"
    ) {

        rawRecords.push(data);

    }

}


// ------------------------------------------------------------
// 5. VALIDATE RECORDS
// ------------------------------------------------------------

if (!rawRecords.length) {

    throw new Error(
        "CODE-003: CW-003 returned data, but no In/Out records were found."
    );

}


// ------------------------------------------------------------
// 6. KEEP LATEST IN/OUT RECORD PER MEMBER
//
// Member key:
//   member.identifier
//
// If duplicate records exist for the same member,
// retain the record with the newest _info.lastUpdated.
// ------------------------------------------------------------

const latestByMember =
    new Map();

for (const record of rawRecords) {

    const member =
        record.member || {};

    const memberID =
        String(
            member.identifier || ""
        ).trim();

    if (!memberID) {
        continue;
    }

    const key =
        memberID.toLowerCase();


    // Current record timestamp
    const currentUpdated =
        record?._info?.lastUpdated
            ? new Date(
                record._info.lastUpdated
            ).getTime()
            : 0;


    // Existing record timestamp
    const existing =
        latestByMember.get(key);

    const existingUpdated =
        existing?._info?.lastUpdated
            ? new Date(
                existing._info.lastUpdated
            ).getTime()
            : 0;


    // Keep newest record
    if (
        !existing ||
        currentUpdated >= existingUpdated
    ) {

        latestByMember.set(
            key,
            record
        );

    }

}


// ------------------------------------------------------------
// 7. DETERMINE CURRENTLY OUT
//
// BUSINESS RULE:
//
// Future DateBack → OUT
// Same DateBack   → AVAILABLE
// Past DateBack   → AVAILABLE
// No DateBack     → AVAILABLE
//
// Calendar dates are compared in the configured timezone.
// ------------------------------------------------------------

function isCurrentlyOut(
    dateBack,
    currentDate,
    timezone
) {

    // No DateBack
    if (!dateBack) {

        return false;

    }


    // Parse DateBack
    const parsedDate =
        new Date(dateBack);

    // Invalid DateBack
    if (
        Number.isNaN(
            parsedDate.getTime()
        )
    ) {

        return false;

    }


    // Convert DateBack into configured timezone
    const dateBackDate =
        $now
            .setZone(timezone)
            .set({
                year: parsedDate.getUTCFullYear(),
                month: parsedDate.getUTCMonth() + 1,
                day: parsedDate.getUTCDate()
            });


    const dateBackOnly =
        dateBackDate.toFormat(
            "yyyy-MM-dd"
        );


    const currentDateOnly =
        String(currentDate)
            .substring(0, 10);


    // FUTURE = OUT
    //
    // TODAY = AVAILABLE
    // PAST  = AVAILABLE

    return (
        dateBackOnly >
        currentDateOnly
    );

}


// ------------------------------------------------------------
// 8. BUILD NORMALIZED LIVE AVAILABILITY
// ------------------------------------------------------------

const liveAvailability = [];

for (
    const record of
    latestByMember.values()
) {

    const member =
        record.member || {};


    const memberID =
        String(
            member.identifier || ""
        ).trim();


    if (!memberID) {
        continue;
    }


    const dateBack =
        record.dateBack ||
        null;


    const currentlyOut =
        isCurrentlyOut(
            dateBack,
            currentDate,
            timezone
        );


    liveAvailability.push({

        // ----------------------------------------------------
        // ConnectWise member identifier
        // ----------------------------------------------------

        MemberID:
            memberID,


        // ----------------------------------------------------
        // ConnectWise numeric member ID
        // ----------------------------------------------------

        ConnectWiseMemberID:
            member.id ||
            null,


        // ----------------------------------------------------
        // Engineer display name
        // ----------------------------------------------------

        EngineerName:
            member.name ||
            null,


        // ----------------------------------------------------
        // Current availability
        // ----------------------------------------------------

        CurrentlyOut:
            currentlyOut,


        LiveAvailability:
            currentlyOut
                ? "OUT"
                : "AVAILABLE",


        // ----------------------------------------------------
        // ConnectWise In/Out information
        // ----------------------------------------------------

        InOutTypeID:
            record.inOutType?.id ||
            null,


        InOutType:
            record.inOutType?.name ||
            null,


        // ----------------------------------------------------
        // Return date/time
        // ----------------------------------------------------

        DateBack:
            dateBack,


        // ----------------------------------------------------
        // Additional information
        // ----------------------------------------------------

        AdditionalInfo:
            record.additionalInfo ||
            null,


        // ----------------------------------------------------
        // Audit information
        // ----------------------------------------------------

        LastUpdated:
            record._info?.lastUpdated ||
            null,


        UpdatedBy:
            record._info?.updatedBy ||
            null,


        // ----------------------------------------------------
        // ConnectWise In/Out record ID
        // ----------------------------------------------------

        InOutRecordID:
            record.id ||
            null

    });

}


// ------------------------------------------------------------
// 9. SUMMARY COUNTS
// ------------------------------------------------------------

const currentlyOutCount =
    liveAvailability.filter(
        engineer =>
            engineer.CurrentlyOut === true
    ).length;


const currentlyInCount =
    liveAvailability.filter(
        engineer =>
            engineer.CurrentlyOut === false
    ).length;


// ------------------------------------------------------------
// 10. RETURN MODULE-03 RESULT
// ------------------------------------------------------------

return [

    {

        json: {

            Status:
                "MODULE-03 OK",


            TestMode:
                false,


            EvaluatedAtUTC:
                new Date().toISOString(),


            CurrentDate:
                currentDate,


            CurrentDay:
                currentDay,


            CurrentTime:
                currentTime,


            Timezone:
                timezone,


            TotalRawRecords:
                rawRecords.length,


            UniqueMemberCount:
                latestByMember.size,


            TotalInOutRecords:
                liveAvailability.length,


            CurrentlyOutCount:
                currentlyOutCount,


            CurrentlyInCount:
                currentlyInCount,


            LiveAvailability:
                liveAvailability

        }

    }

];

// ============================================================
// CODE-004 – Build Live Eligibility
// MODULE 04
//
// PURPOSE:
//   Combine:
//     MODULE-03 = Live ConnectWise In/Out availability
//     MODULE-02 = Planned roster / calendar
//
// IMPORTANT BUSINESS RULES:
//
//   SUNDAY:
//     - NO TICKET ASSIGNMENT
//     - ALL TICKETS REMAIN "New"
//     - NO L1 / L2 / L3 assignment
//     - NO ESCALATION
//     - NO ROUND ROBIN
//     - NO WORKLOAD-BASED ASSIGNMENT
//
//   SATURDAY:
//     - Level1 ONLY
//     - If L1 capacity exhausted -> no assignment
//     - NO escalation to L2/L3
//
//   MONDAY-FRIDAY:
//     - Normal hierarchy:
//         Level1 -> Level2 -> Level3
//     - Workload engine decides capacity
//
//   SHIFT RULE:
//     - Engineer must belong to an ACTIVE SHIFT.
//     - Active shift is determined using BOTH:
//         1. Calendar / roster active shift
//         2. Actual current time against Shift Start/End
//
//   IMPORTANT FIX:
//     At 17:37:
//       S1 = 08:00-17:30 -> INACTIVE
//       S2 = 11:00-20:30 -> ACTIVE
//       S3 = 12:30-22:00 -> ACTIVE
//       S4 = 14:30-00:00 -> ACTIVE
//       S5 = 17:30-03:00 -> ACTIVE
//
//   Therefore an S1 engineer CANNOT receive a ticket at 17:37.
//
//   FRIDAY S5 OVERNIGHT:
//     - Friday S5 continues after midnight into Saturday.
//     - Saturday 00:00-03:00 is still treated as Friday S5.
//     - OperationalDate remains Friday.
// ============================================================


// ============================================================
// 1. READ INPUT
// ============================================================

const inputItems = $input.all();

if (!inputItems || inputItems.length === 0) {

  throw new Error(
    'CODE-004 received no input from MERGE-001.'
  );

}


// ============================================================
// 2. HELPER FUNCTIONS
// ============================================================

function isObject(value) {

  return (
    value !== null &&
    typeof value === 'object'
  );

}


function firstDefined(...values) {

  for (const value of values) {

    if (
      value !== undefined &&
      value !== null &&
      value !== ''
    ) {

      return value;

    }

  }

  return undefined;

}


function clean(value) {

  if (
    value === undefined ||
    value === null
  ) {

    return '';

  }

  return String(value).trim();

}


function parsePossibleJSON(value) {

  if (typeof value !== 'string') {

    return value;

  }

  const trimmed =
    value.trim();

  if (!trimmed) {

    return value;

  }

  if (
    !trimmed.startsWith('{') &&
    !trimmed.startsWith('[')
  ) {

    return value;

  }

  try {

    return JSON.parse(trimmed);

  } catch {

    return value;

  }

}


// ============================================================
// 3. TIME FUNCTIONS
// ============================================================

function timeToMinutes(timeString) {

  if (
    timeString === undefined ||
    timeString === null ||
    timeString === ''
  ) {

    return null;

  }


  const text =
    String(timeString)
      .trim()
      .toLowerCase();


  // ----------------------------------------------------------
  // Handle formats such as:
  // 08:00
  // 17:30
  // 5:30 PM
  // 5:30PM
  // ----------------------------------------------------------

  let match =
    text.match(
      /^(\d{1,2}):(\d{2})\s*(am|pm)?$/
    );


  if (!match) {

    // Also support HH:MM:SS

    match =
      text.match(
        /^(\d{1,2}):(\d{2}):(\d{2})\s*(am|pm)?$/
      );

  }


  if (!match) {

    return null;

  }


  let hour =
    Number(match[1]);

  const minute =
    Number(match[2]);

  const ampm =
    match[4] || null;


  if (
    Number.isNaN(hour) ||
    Number.isNaN(minute) ||
    minute < 0 ||
    minute > 59
  ) {

    return null;

  }


  if (ampm === 'pm' && hour < 12) {

    hour += 12;

  }


  if (ampm === 'am' && hour === 12) {

    hour = 0;

  }


  if (
    hour < 0 ||
    hour > 23
  ) {

    return null;

  }


  return (
    hour * 60
  ) + minute;

}


// ------------------------------------------------------------
// CHECK WHETHER A SHIFT IS ACTIVE NOW
// ------------------------------------------------------------
//
// Handles:
//
// Normal shift:
//   08:00 -> 17:30
//
// Overnight shift:
//   17:30 -> 03:00
//
// Important:
//   start is inclusive
//   end is exclusive
//
// Therefore:
//
// S1 17:30 = INACTIVE
// S2 20:30 = INACTIVE
// S5 17:30 = ACTIVE
// S5 03:00 = INACTIVE
// ------------------------------------------------------------

function isShiftTimeActive(
  currentMinutes,
  startTime,
  endTime
) {

  if (
    currentMinutes === null
  ) {

    return false;

  }


  const startMinutes =
    timeToMinutes(startTime);


  const endMinutes =
    timeToMinutes(endTime);


  if (
    startMinutes === null ||
    endMinutes === null
  ) {

    return false;

  }


  // ----------------------------------------------------------
  // Same-day shift
  // ----------------------------------------------------------

  if (
    startMinutes < endMinutes
  ) {

    return (
      currentMinutes >= startMinutes &&
      currentMinutes < endMinutes
    );

  }


  // ----------------------------------------------------------
  // Overnight shift
  //
  // Example:
  // S5 = 17:30 -> 03:00
  //
  // Active:
  // 17:30-23:59
  // 00:00-02:59
  // ----------------------------------------------------------

  if (
    startMinutes > endMinutes
  ) {

    return (
      currentMinutes >= startMinutes ||
      currentMinutes < endMinutes
    );

  }


  // ----------------------------------------------------------
  // start == end
  //
  // Treat as inactive.
  // ----------------------------------------------------------

  return false;

}


// ============================================================
// 4. FIND MODULE-03 AND MODULE-02
// ============================================================

let module03 = null;
let module02 = null;


for (
  const item of inputItems
) {

  let data =
    item?.json || {};


  data =
    parsePossibleJSON(data);


  if (!isObject(data)) {

    continue;

  }


  // ----------------------------------------------------------
  // MODULE-03
  // ----------------------------------------------------------

  if (
    data.Status === 'MODULE-03 OK'
  ) {

    module03 = data;

  }


  // ----------------------------------------------------------
  // MODULE-02
  // ----------------------------------------------------------

  if (
    data.Status === 'MODULE-02 OK'
  ) {

    module02 = data;

  }

}


// ============================================================
// 5. FALLBACK MODULE-03 DETECTION
// ============================================================

if (!module03) {

  for (
    const item of inputItems
  ) {

    let data =
      item?.json || {};


    data =
      parsePossibleJSON(data);


    if (!isObject(data)) {

      continue;

    }


    if (
      Array.isArray(
        data.LiveAvailability
      ) &&
      (
        data.TotalInOutRecords !== undefined ||
        data.CurrentlyOutCount !== undefined ||
        data.CurrentlyInCount !== undefined
      )
    ) {

      module03 =
        data;

      break;

    }

  }

}


// ============================================================
// 6. GET CURRENT DATE / TIME
// ============================================================

const preliminaryModule =
  module03 ||
  inputItems
    .map(
      item =>
        item?.json || {}
    )
    .find(
      data =>
        data &&
        (
          data.CurrentDay !== undefined ||
          data.CurrentDate !== undefined
        )
    ) ||
  {};


const currentDate =
  firstDefined(
    preliminaryModule.CurrentDate,
    new Date()
      .toISOString()
      .slice(0, 10)
  );


const currentDay =
  clean(
    firstDefined(
      preliminaryModule.CurrentDay,
      ''
    )
  ).toLowerCase();


const currentTime =
  firstDefined(
    preliminaryModule.CurrentTime,
    '00:00'
  );


const timezone =
  firstDefined(
    preliminaryModule.Timezone,
    'Asia/Kolkata'
  );


const currentMinutes =
  timeToMinutes(
    currentTime
  );


// ============================================================
// 7. SUNDAY HARD STOP
// ============================================================
//
// Sunday is ALWAYS no-assignment.
//
// We intentionally stop here.
//
// No need to:
//   - read roster
//   - read shifts
//   - evaluate engineers
//   - evaluate workload
//   - escalate
//
// ============================================================

if (
  currentDay === 'sunday'
) {

  return [

    {

      json: {

        Status:
          'MODULE-04 OK',

        TestMode:
          preliminaryModule.TestMode ??
          false,

        CurrentDate:
          currentDate,

        CurrentDay:
          'Sunday',

        CurrentTime:
          currentTime,

        Timezone:
          timezone,


        OperationalDate:
          currentDate,

        OperationalDay:
          'Sunday',

        FridayS5Overnight:
          false,

        IsSaturday:
          false,

        IsSunday:
          true,


        // ----------------------------------------------------
        // SUNDAY BUSINESS RULE
        // ----------------------------------------------------

        AssignmentAllowed:
          false,

        AssignmentReady:
          false,

        EscalationAllowed:
          false,

        EscalationRequired:
          false,

        AssignmentMode:
          'NONE',

        RequiredLevels:
          [],

        SelectedLevel:
          null,

        SelectedEngineer:
          null,


        // ----------------------------------------------------
        // DECISION
        // ----------------------------------------------------

        FinalDecision:
          'SUNDAY_NO_ASSIGNMENT',

        CoverageDecision:
          'SUNDAY_NO_ASSIGNMENT',


        // ----------------------------------------------------
        // ELIGIBILITY
        // ----------------------------------------------------

        PlannedEngineerCount:
          0,

        LiveRecordMatchedCount:
          0,

        NoLiveRecordCount:
          0,

        EligibleEngineerCount:
          0,

        UnavailableEngineerCount:
          0,

        EligibleLevel1Count:
          0,

        EligibleLevel2Count:
          0,

        EligibleLevel3Count:
          0,

        EligibleEngineers:
          [],

        UnavailableEngineers:
          [],


        // ----------------------------------------------------
        // CALENDAR
        // ----------------------------------------------------

        Calendar: {

          Active:
            false,

          ActiveShiftIDs:
            [],

          AllowedLevels:
            [],

          AssignmentMode:
            'NONE',

          Max_L1:
            0,

          Max_L2:
            0,

          Max_L3:
            0

        },


        // ----------------------------------------------------
        // TICKET HANDLING
        // ----------------------------------------------------

        TicketAction:
          'LEAVE_IN_NEW',

        TicketStatusAction:
          'NO_CHANGE',


        // ----------------------------------------------------
        // DEBUG
        // ----------------------------------------------------

        Debug: {

          SundayRuleApplied:
            true,

          Module03Found:
            !!module03,

          Module02Found:
            !!module02,

          Reason:
            'Sunday is a no-assignment day. ' +
            'Ticket must remain in New status.'

        }

      }

    }

  ];

}


// ============================================================
// 8. NON-SUNDAY VALIDATION
// ============================================================

if (!module03) {

  throw new Error(
    'MODULE-03 output was not found in MERGE-001 input.'
  );

}


if (!module02) {

  throw new Error(
    'MODULE-02 output was not found in MERGE-001 input.'
  );

}


// ============================================================
// 9. CALENDAR
// ============================================================

const calendar =
  module02.Calendar || {};


const calendarActive =
  calendar.Active === true;


const calendarActiveShiftIDs =
  Array.isArray(
    calendar.ActiveShiftIDs
  )
    ? calendar.ActiveShiftIDs
        .map(
          x =>
            String(x).trim()
        )
        .filter(Boolean)
    : [];


// ============================================================
// 10. REQUIRED LEVELS
// ============================================================

let RequiredLevels =
  Array.isArray(
    calendar.AllowedLevels
  )
    ? calendar.AllowedLevels
        .map(
          x =>
            String(x).trim()
        )
        .filter(Boolean)
    : [];


if (
  RequiredLevels.length === 0
) {

  RequiredLevels = [];


  if (
    Number(calendar.Max_L1 || 0) > 0
  ) {

    RequiredLevels.push(
      'Level1'
    );

  }


  if (
    Number(calendar.Max_L2 || 0) > 0
  ) {

    RequiredLevels.push(
      'Level2'
    );

  }


  if (
    Number(calendar.Max_L3 || 0) > 0
  ) {

    RequiredLevels.push(
      'Level3'
    );

  }

}


// ============================================================
// 11. ASSIGNMENT MODE
// ============================================================

const AssignmentMode =
  calendar.AssignmentMode ||
  'RoundRobin';


// ============================================================
// 12. OPERATIONAL DATE
// ============================================================

function previousDate(
  dateString
) {

  const d =
    new Date(
      `${dateString}T00:00:00`
    );


  d.setDate(
    d.getDate() - 1
  );


  return d
    .toISOString()
    .slice(0, 10);

}


// ------------------------------------------------------------
// Friday S5 overnight
// ------------------------------------------------------------
//
// Saturday 00:00-02:59:
//
// If S5 is actually active and the current time is before 03:00,
// treat the operational date as Friday.
//
// IMPORTANT:
// We do NOT blindly use calendar ActiveShiftIDs.
// We validate that S5 itself is active.
// ------------------------------------------------------------

const fridayS5Overnight =
  currentDay === 'saturday' &&
  calendarActiveShiftIDs
    .map(x => String(x).toUpperCase())
    .includes('S5') &&
  currentMinutes !== null &&
  currentMinutes < 180;


let OperationalDate =
  currentDate;


let OperationalDay =
  currentDay;


if (
  fridayS5Overnight
) {

  OperationalDate =
    previousDate(
      currentDate
    );


  const d =
    new Date(
      `${OperationalDate}T00:00:00`
    );


  OperationalDay =
    d.toLocaleDateString(
      'en-US',
      {
        weekday: 'long',
        timeZone: 'UTC'
      }
    ).toLowerCase();

}


const IsSaturday =
  currentDay === 'saturday';


const IsSunday =
  currentDay === 'sunday';


// ============================================================
// 13. SATURDAY OVERRIDE
// ============================================================
//
// Saturday assignment is Level1 ONLY.
//
// This is enforced here regardless of what Calendar says.
//
// ============================================================

if (
  IsSaturday &&
  !fridayS5Overnight
) {

  RequiredLevels =
    ['Level1'];

}


// ============================================================
// 14. LIVE AVAILABILITY
// ============================================================

const liveAvailability =
  Array.isArray(
    module03.LiveAvailability
  )
    ? module03.LiveAvailability
    : [];


const liveByMemberID =
  new Map();


const liveByName =
  new Map();


for (
  const record of liveAvailability
) {

  if (!record) {

    continue;

  }


  const memberID =
    String(
      record.MemberID || ''
    )
      .trim()
      .toLowerCase();


  const engineerName =
    String(
      record.EngineerName || ''
    )
      .trim()
      .toLowerCase();


  if (memberID) {

    liveByMemberID.set(
      memberID,
      record
    );

  }


  if (engineerName) {

    liveByName.set(
      engineerName,
      record
    );

  }

}


// ============================================================
// 15. PLANNED ENGINEERS
// ============================================================

const plannedEngineers =
  Array.isArray(
    module02.PlannedEngineers
  )
    ? module02.PlannedEngineers
    : [];


// ============================================================
// 16. SHIFT MASTER EXTRACTION
// ============================================================
//
// We try several possible locations because the exact MODULE-02
// structure can vary.
//
// Supported:
//
// module02.ActiveShifts
// module02.Shifts
// module02.ShiftMaster
// module02.ShiftMasterData
// module02.Calendar.ActiveShifts
// module02.Calendar.Shifts
//
// If no shift master is present, we also use the known company
// shift definitions as a SAFETY FALLBACK.
//
// ============================================================

let shiftMaster = [];


const possibleShiftSources = [

  module02.ActiveShifts,

  module02.Shifts,

  module02.ShiftMaster,

  module02.ShiftMasterData,

  module02.Calendar?.ActiveShifts,

  module02.Calendar?.Shifts

];


for (
  const source of possibleShiftSources
) {

  if (
    Array.isArray(source) &&
    source.length > 0
  ) {

    shiftMaster =
      source;

    break;

  }

}


// ============================================================
// 17. SAFETY FALLBACK SHIFT MASTER
// ============================================================
//
// This matches the shift roster you provided:
//
// S1 = 08:00 - 17:30
// S2 = 11:00 - 20:30
// S3 = 12:30 - 22:00
// S4 = 14:30 - 00:00
// S5 = 17:30 - 03:00
//
// The fallback is used ONLY when MODULE-02 does not provide
// shift timing information.
//
// ============================================================

if (
  shiftMaster.length === 0
) {

  shiftMaster = [

    {
      Shift_ID: 'S1',
      Shift_Name: 'Shift-1',
      Start_Time: '08:00',
      End_Time: '17:30',
      Active: 'Yes'
    },

    {
      Shift_ID: 'S2',
      Shift_Name: 'Shift-2',
      Start_Time: '11:00',
      End_Time: '20:30',
      Active: 'Yes'
    },

    {
      Shift_ID: 'S3',
      Shift_Name: 'Shift-3',
      Start_Time: '12:30',
      End_Time: '22:00',
      Active: 'Yes'
    },

    {
      Shift_ID: 'S4',
      Shift_Name: 'Shift-4',
      Start_Time: '14:30',
      End_Time: '00:00',
      Active: 'Yes'
    },

    {
      Shift_ID: 'S5',
      Shift_Name: 'Shift-5',
      Start_Time: '17:30',
      End_Time: '03:00',
      Active: 'Yes'
    }

  ];

}


// ============================================================
// 18. NORMALIZE SHIFT MASTER
// ============================================================

function normalizeShift(
  shift
) {

  if (!isObject(shift)) {

    return null;

  }


  const shiftID =
    clean(
      firstDefined(
        shift.Shift_ID,
        shift.ShiftID,
        shift.shift_id,
        shift.shiftID,
        shift.ID,
        shift.Id
      )
    );


  const shiftName =
    clean(
      firstDefined(
        shift.Shift_Name,
        shift.ShiftName,
        shift.shift_name,
        shift.shiftName,
        shift.Name,
        shift.name
      )
    );


  const startTime =
    clean(
      firstDefined(
        shift.Start_Time,
        shift.StartTime,
        shift.start_time,
        shift.startTime,
        shift.Start,
        shift.start
      )
    );


  const endTime =
    clean(
      firstDefined(
        shift.End_Time,
        shift.EndTime,
        shift.end_time,
        shift.endTime,
        shift.End,
        shift.end
      )
    );


  const activeValue =
    firstDefined(
      shift.Active,
      shift.active,
      shift.Enabled,
      shift.enabled,
      true
    );


  const active =
    activeValue === true ||
    String(activeValue)
      .trim()
      .toLowerCase() === 'yes' ||
    String(activeValue)
      .trim()
      .toLowerCase() === 'true' ||
    String(activeValue)
      .trim() === '1';


  return {

    ShiftID:
      shiftID,

    ShiftName:
      shiftName,

    StartTime:
      startTime,

    EndTime:
      endTime,

    Active:
      active

  };

}


const normalizedShifts =
  shiftMaster
    .map(
      normalizeShift
    )
    .filter(
      shift =>
        shift &&
        shift.ShiftID
    );


// ============================================================
// 19. BUILD SHIFT LOOKUP
// ============================================================

const shiftByID =
  new Map();


for (
  const shift of normalizedShifts
) {

  shiftByID.set(
    shift.ShiftID
      .toUpperCase(),
    shift
  );

}


// ============================================================
// 20. DETERMINE ACTUAL ACTIVE SHIFTS
// ============================================================
//
// IMPORTANT:
//
// Calendar.ActiveShiftIDs alone is NOT enough.
//
// We calculate:
//
// ActualTimeActive
//
// based on:
//
// CurrentTime
// Shift Start
// Shift End
//
// Then combine it with calendar activation.
//
//
//
// Example at 17:37:
//
// S1:
//   08:00 -> 17:30
//   ActualTimeActive = false
//
// S2:
//   11:00 -> 20:30
//   ActualTimeActive = true
//
// Therefore S1 engineers cannot be selected.
// ============================================================

const activeShiftDetails = [];


for (
  const shift of normalizedShifts
) {

  const actualTimeActive =
    shift.Active &&
    isShiftTimeActive(
      currentMinutes,
      shift.StartTime,
      shift.EndTime
    );


  const calendarAllowsShift =
    calendarActiveShiftIDs.length === 0
      ? true
      : calendarActiveShiftIDs
          .map(
            x =>
              String(x).toUpperCase()
          )
          .includes(
            shift.ShiftID.toUpperCase()
          );


  const actuallyActive =
    actualTimeActive &&
    calendarAllowsShift;


  activeShiftDetails.push({

    ShiftID:
      shift.ShiftID,

    ShiftName:
      shift.ShiftName,

    StartTime:
      shift.StartTime,

    EndTime:
      shift.EndTime,

    MasterActive:
      shift.Active,

    CalendarAllows:
      calendarAllowsShift,

    ActualTimeActive:
      actualTimeActive,

    ActuallyActive:
      actuallyActive

  });

}


// ------------------------------------------------------------
// IDs of shifts actually active RIGHT NOW
// ------------------------------------------------------------

const actualActiveShiftIDs =
  activeShiftDetails
    .filter(
      shift =>
        shift.ActuallyActive
    )
    .map(
      shift =>
        shift.ShiftID
    );


// ============================================================
// 21. LIVE ELIGIBILITY ARRAYS
// ============================================================

const eligibleEngineers = [];

const unavailableEngineers = [];

let liveRecordMatchedCount = 0;

let noLiveRecordCount = 0;


// ============================================================
// 22. PROCESS PLANNED ENGINEERS
// ============================================================

for (
  const planned of plannedEngineers
) {

  if (!planned) {

    continue;

  }


  const engineerName =
    String(
      planned.EngineerName || ''
    ).trim();


  const memberID =
    String(
      planned.MemberID || ''
    ).trim();


  const assignmentLevel =
    String(
      planned.AssignmentLevel || ''
    ).trim();


  const shiftID =
    String(
      planned.ShiftID || ''
    ).trim();


  const shiftDay =
    String(
      planned.ShiftDay || ''
    ).trim();


  const shiftStart =
    firstDefined(
      planned.ShiftStart,
      ''
    );


  const shiftEnd =
    firstDefined(
      planned.ShiftEnd,
      ''
    );


  const rosterAvailable =
    planned.RosterAvailable !== false;


  // ----------------------------------------------------------
  // LIVE RECORD
  // ----------------------------------------------------------

  const memberKey =
    memberID
      .toLowerCase();


  const nameKey =
    engineerName
      .toLowerCase();


  const liveRecord =
    liveByMemberID.get(
      memberKey
    ) ||
    liveByName.get(
      nameKey
    ) ||
    null;


  const connectWiseRecordFound =
    !!liveRecord;


  if (
    connectWiseRecordFound
  ) {

    liveRecordMatchedCount++;

  } else {

    noLiveRecordCount++;

  }


  // ----------------------------------------------------------
  // LIVE STATUS
  // ----------------------------------------------------------

  const currentlyOut =
    liveRecord
      ? liveRecord.CurrentlyOut === true
      : false;


  const liveStatus =
    liveRecord
      ? (
          liveRecord.LiveAvailability ||
          (
            currentlyOut
              ? 'OUT'
              : 'AVAILABLE'
          )
        )
      : 'NO_RECORD';


  // ----------------------------------------------------------
  // LIVE DETAILS
  // ----------------------------------------------------------

  const inOutTypeID =
    liveRecord
      ? (
          liveRecord.InOutTypeID ??
          null
        )
      : null;


  const inOutType =
    liveRecord
      ? (
          liveRecord.InOutType ??
          null
        )
      : null;


  const dateBack =
    liveRecord
      ? (
          liveRecord.DateBack ??
          null
        )
      : null;


  const additionalInfo =
    liveRecord
      ? (
          liveRecord.AdditionalInfo ??
          null
        )
      : null;


  const lastUpdated =
    liveRecord
      ? (
          liveRecord.LastUpdated ??
          null
        )
      : null;


  const updatedBy =
    liveRecord
      ? (
          liveRecord.UpdatedBy ??
          null
        )
      : null;


  const inOutRecordID =
    liveRecord
      ? (
          liveRecord.InOutRecordID ??
          null
        )
      : null;


  // ==========================================================
  // SHIFT INFORMATION
  // ==========================================================

  const normalizedShiftID =
    shiftID
      .toUpperCase();


  const shiftMasterRecord =
    shiftByID.get(
      normalizedShiftID
    ) ||
    null;


  // ----------------------------------------------------------
  // Prefer actual shift-master times.
  // Fall back to planned row times.
  // ----------------------------------------------------------

  const effectiveShiftStart =
    clean(
      firstDefined(
        shiftMasterRecord?.StartTime,
        shiftStart
      )
    );


  const effectiveShiftEnd =
    clean(
      firstDefined(
        shiftMasterRecord?.EndTime,
        shiftEnd
      )
    );


  const shiftMasterActive =
    shiftMasterRecord
      ? shiftMasterRecord.Active
      : true;


  // ----------------------------------------------------------
  // ACTUAL TIME CHECK
  // ----------------------------------------------------------

  const shiftTimeActive =
    shiftMasterActive &&
    isShiftTimeActive(
      currentMinutes,
      effectiveShiftStart,
      effectiveShiftEnd
    );


  // ----------------------------------------------------------
  // CALENDAR SHIFT CHECK
  // ----------------------------------------------------------

  const calendarShiftAllowed =
    calendarActiveShiftIDs.length === 0
      ? true
      : calendarActiveShiftIDs
          .map(
            x =>
              String(x).toUpperCase()
          )
          .includes(
            normalizedShiftID
          );


  // ----------------------------------------------------------
  // FINAL SHIFT STATUS
  // ----------------------------------------------------------
  //
  // BOTH must be true:
  //
  // Calendar allows shift
  // AND
  // Current time is inside shift
  //
  // ----------------------------------------------------------

  let shiftCurrentlyActive =
    false;


  if (
    shiftID
  ) {

    shiftCurrentlyActive =
      calendarShiftAllowed &&
      shiftTimeActive;

  } else if (
    !shiftID &&
    rosterAvailable
  ) {

    // No shift ID means we cannot safely validate a shift.
    //
    // Preserve previous behavior for such roster rows.

    shiftCurrentlyActive =
      true;

  }


  // ----------------------------------------------------------
  // LEVEL ELIGIBILITY
  // ----------------------------------------------------------

  const levelAllowed =
    RequiredLevels.includes(
      assignmentLevel
    );


  // ==========================================================
  // ELIGIBILITY
  // ==========================================================

  let eligible =
    true;


  let unavailableReason =
    null;


  // ----------------------------------------------------------
  // CALENDAR
  // ----------------------------------------------------------

  if (
    !calendarActive
  ) {

    eligible =
      false;

    unavailableReason =
      'Calendar is not active';

  }


  // ----------------------------------------------------------
  // ROSTER
  // ----------------------------------------------------------

  else if (
    !rosterAvailable
  ) {

    eligible =
      false;

    unavailableReason =
      'Engineer not available on roster';

  }


  // ----------------------------------------------------------
  // LEVEL
  // ----------------------------------------------------------

  else if (
    !levelAllowed
  ) {

    eligible =
      false;

    unavailableReason =
      `Assignment level ${assignmentLevel} is not allowed`;

  }


  // ----------------------------------------------------------
  // SHIFT
  // ----------------------------------------------------------

  else if (
    shiftID &&
    !shiftCurrentlyActive
  ) {

    eligible =
      false;


    if (
      !calendarShiftAllowed
    ) {

      unavailableReason =
        `Shift ${shiftID} is not active in calendar`;

    } else if (
      !shiftTimeActive
    ) {

      unavailableReason =
        `Shift ${shiftID} is outside working hours ` +
        `(${effectiveShiftStart}-${effectiveShiftEnd}). ` +
        `Current time is ${currentTime}`;

    } else {

      unavailableReason =
        `Shift ${shiftID} is not currently active`;

    }

  }


  // ----------------------------------------------------------
  // LIVE OUT
  // ----------------------------------------------------------

  else if (
    currentlyOut
  ) {

    eligible =
      false;

    unavailableReason =
      'Engineer is currently out';

  }


  // ==========================================================
  // RESULT
  // ==========================================================

  const result = {

    EngineerName:
      engineerName,

    MemberID:
      memberID,

    AssignmentLevel:
      assignmentLevel,

    ShiftID:
      shiftID,

    ShiftName:
      planned.ShiftName ??
      shiftMasterRecord?.ShiftName ??
      null,

    ShiftDay:
      shiftDay,

    ShiftStart:
      effectiveShiftStart,

    ShiftEnd:
      effectiveShiftEnd,

    ShiftCurrentlyActive:
      shiftCurrentlyActive,

    ShiftTimeActive:
      shiftTimeActive,

    CalendarShiftAllowed:
      calendarShiftAllowed,

    ShiftMasterActive:
      shiftMasterActive,

    Planned:
      true,

    RosterAvailable:
      rosterAvailable,

    ConnectWiseRecordFound:
      connectWiseRecordFound,

    CurrentlyOut:
      currentlyOut,

    LiveAvailability:
      liveStatus,

    InOutTypeID:
      inOutTypeID,

    InOutType:
      inOutType,

    DateBack:
      dateBack,

    AdditionalInfo:
      additionalInfo,

    LastUpdated:
      lastUpdated,

    UpdatedBy:
      updatedBy,

    InOutRecordID:
      inOutRecordID,

    Eligible:
      eligible

  };


  if (
    eligible
  ) {

    eligibleEngineers.push(
      result
    );

  } else {

    result.UnavailableReason =
      unavailableReason;

    unavailableEngineers.push(
      result
    );

  }

}


// ============================================================
// 23. LEVEL COUNTS
// ============================================================

const eligibleLevel1 =
  eligibleEngineers.filter(
    e =>
      e.AssignmentLevel === 'Level1'
  );


const eligibleLevel2 =
  eligibleEngineers.filter(
    e =>
      e.AssignmentLevel === 'Level2'
  );


const eligibleLevel3 =
  eligibleEngineers.filter(
    e =>
      e.AssignmentLevel === 'Level3'
  );


// ============================================================
// 24. SUMMARY
// ============================================================

const PlannedEngineerCount =
  plannedEngineers.length;


const EligibleEngineerCount =
  eligibleEngineers.length;


const UnavailableEngineerCount =
  unavailableEngineers.length;


// ============================================================
// 25. ACTIVE SHIFTS
// ============================================================

const shiftMasterCount =
  normalizedShifts.length;


// ============================================================
// 26. ASSIGNMENT RULES
// ============================================================

let finalRequiredLevels =
  [...RequiredLevels];


let finalAssignmentMode =
  AssignmentMode;


let escalationAllowed =
  true;


// ------------------------------------------------------------
// Saturday
// ------------------------------------------------------------

if (
  IsSaturday &&
  !fridayS5Overnight
) {

  finalRequiredLevels =
    ['Level1'];

  finalAssignmentMode =
    'Level1Only';

  escalationAllowed =
    false;

}


// ============================================================
// 27. NORMAL OUTPUT
// ============================================================

return [

  {

    json: {

      Status:
        'MODULE-04 OK',

      TestMode:
        module03.TestMode ??
        false,

      CurrentDate:
        currentDate,

      CurrentDay:
        currentDay.charAt(0).toUpperCase() +
        currentDay.slice(1),

      CurrentTime:
        currentTime,

      CurrentMinutes:
        currentMinutes,

      Timezone:
        timezone,


      // ------------------------------------------------------
      // OPERATIONAL
      // ------------------------------------------------------

      OperationalDate:
        OperationalDate,

      OperationalDay:
        OperationalDay,

      FridayS5Overnight:
        fridayS5Overnight,

      IsSaturday:
        IsSaturday,

      IsSunday:
        IsSunday,


      // ------------------------------------------------------
      // ASSIGNMENT
      // ------------------------------------------------------

      AssignmentAllowed:
        true,

      AssignmentReady:
        false,

      EscalationAllowed:
        escalationAllowed,

      EscalationRequired:
        false,


      // ------------------------------------------------------
      // CALENDAR
      // ------------------------------------------------------

      Calendar: {

        Active:
          calendarActive,

        ActiveShiftIDs:
          calendarActiveShiftIDs,

        AllowedLevels:
          finalRequiredLevels,

        AssignmentMode:
          finalAssignmentMode,

        Max_L1:
          Number(
            calendar.Max_L1 || 0
          ),

        Max_L2:
          Number(
            calendar.Max_L2 || 0
          ),

        Max_L3:
          Number(
            calendar.Max_L3 || 0
          )

      },


      // ------------------------------------------------------
      // SHIFT
      // ------------------------------------------------------

      ShiftMasterCount:
        shiftMasterCount,

      ActiveShiftIDs:
        actualActiveShiftIDs,

      CalendarActiveShiftIDs:
        calendarActiveShiftIDs,

      ActiveShifts:
        activeShiftDetails,


      // ------------------------------------------------------
      // ASSIGNMENT
      // ------------------------------------------------------

      RequiredLevels:
        finalRequiredLevels,

      AssignmentMode:
        finalAssignmentMode,


      // ------------------------------------------------------
      // SUMMARY
      // ------------------------------------------------------

      PlannedEngineerCount:
        PlannedEngineerCount,

      LiveRecordMatchedCount:
        liveRecordMatchedCount,

      NoLiveRecordCount:
        noLiveRecordCount,

      EligibleEngineerCount:
        EligibleEngineerCount,

      UnavailableEngineerCount:
        UnavailableEngineerCount,

      EligibleLevel1Count:
        eligibleLevel1.length,

      EligibleLevel2Count:
        eligibleLevel2.length,

      EligibleLevel3Count:
        eligibleLevel3.length,


      // ------------------------------------------------------
      // ENGINEERS
      // ------------------------------------------------------

      EligibleEngineers:
        eligibleEngineers,

      UnavailableEngineers:
        unavailableEngineers,


      // ------------------------------------------------------
      // DECISION
      // ------------------------------------------------------

      FinalDecision:
        'ELIGIBILITY_READY',

      CoverageDecision:
        IsSaturday
          ? 'SATURDAY_L1_ONLY'
          : 'NORMAL_ELIGIBILITY',


      // ------------------------------------------------------
      // DEBUG
      // ------------------------------------------------------

      Debug: {

        SundayRuleApplied:
          false,

        Module03Found:
          true,

        Module02Found:
          true,

        CurrentTime:
          currentTime,

        CurrentMinutes:
          currentMinutes,

        CalendarActiveShiftIDs:
          calendarActiveShiftIDs,

        ActualActiveShiftIDs:
          actualActiveShiftIDs,

        RequiredLevels:
          finalRequiredLevels,

        OperationalDate:
          OperationalDate,

        OperationalDay:
          OperationalDay,

        ShiftValidation:
          'Calendar shift + actual current time are both validated',

        ImportantCheck:
          'An engineer is eligible only when the current time falls within the engineer shift start/end window.'

      }

    }

  }

];

// ============================================================
// CODE-005 – ESCALATION ENGINE
// ============================================================
//
// PURPOSE
// ------------------------------------------------------------
// CODE-005 is responsible for:
//
// 1. Determining the operational day/mode
// 2. Determining which LEVEL is allowed
// 3. Determining which engineers are eligible
// 4. Applying workload rules
// 5. Passing clean candidates to CODE-006
//
// BUSINESS RULES
// ------------------------------------------------------------
//
// MONDAY-FRIDAY
//   Level1 → Level2 → Level3
//   Normal workload limits apply
//
// FRIDAY S5 OVERNIGHT
//   Continue normal operational rules
//   Level1 → Level2 → Level3
//   Normal workload limits apply
//
// SATURDAY
//   Level1 ONLY
//   NO Level2
//   NO Level3
//   NO escalation
//   NO ticket-count limit
//   CurrentTicketCount is completely ignored
//   MaxTickets is completely ignored
//   L1 engineer can receive any number of tickets
//   Engineer must still be otherwise eligible/available
//
// SUNDAY
//   NO ASSIGNMENT
//
// IMPORTANT
// ------------------------------------------------------------
// Saturday workload bypass applies ONLY to Saturday.
// It must NEVER affect Monday-Friday.
//
// CODE-006 performs final engineer selection / RoundRobin.
//
// ============================================================


// ============================================================
// 1. INPUT
// ============================================================

const input = $input.first()?.json;

if (!input) {
  throw new Error('CODE-005: No input received.');
}


// ============================================================
// 2. BASIC VALUES
// ============================================================

const currentDate =
  String(input.CurrentDate ?? '').trim();

const currentDay =
  String(input.CurrentDay ?? '').trim().toLowerCase();

const currentTime =
  String(input.CurrentTime ?? '').trim();

const operationalDate =
  String(
    input.OperationalDate ??
    currentDate
  ).trim();

const operationalDay =
  String(
    input.OperationalDay ??
    currentDay
  ).trim().toLowerCase();

const fridayS5Overnight =
  input.FridayS5Overnight === true;

const testMode =
  input.TestMode === true;

const assignmentMode =
  String(
    input.AssignmentMode ??
    input.Calendar?.AssignmentMode ??
    'RoundRobin'
  ).trim();


// ============================================================
// 3. WORKFLOW CONFIGURATION
// ============================================================

const config =
  input.WorkflowConfig ?? {};


// ------------------------------------------------------------
// WEEKDAY WORKLOAD LIMITS
// ------------------------------------------------------------
//
// IMPORTANT:
// These limits are used ONLY for normal weekday operation.
//
// They are NOT used on Saturday.
//

const maxLevel1Tickets =
  Number(
    config.MaxLevel1Tickets ??
    input.Calendar?.Max_L1 ??
    10
  );

const maxLevel2Tickets =
  Number(
    config.MaxLevel2Tickets ??
    input.Calendar?.Max_L2 ??
    10
  );

const maxLevel3Tickets =
  Number(
    config.MaxLevel3Tickets ??
    input.Calendar?.Max_L3 ??
    5
  );

const enableLevel3 =
  config.EnableLevel3 !== false;


// ============================================================
// 4. ENGINEERS
// ============================================================

const eligibleEngineers =
  Array.isArray(input.EligibleEngineers)
    ? input.EligibleEngineers
    : [];


// ============================================================
// 5. WORKLOAD
// ============================================================

const workloadByEngineer =
  Array.isArray(input.WorkloadByEngineer)
    ? input.WorkloadByEngineer
    : [];


// ============================================================
// 6. PREVIOUS ASSIGNMENT STATE
// ============================================================

const previousAssignmentState =
  input.PreviousAssignmentState &&
  typeof input.PreviousAssignmentState === 'object'
    ? input.PreviousAssignmentState
    : {};


// ============================================================
// 7. DAY DETECTION
// ============================================================

const isSunday =
  currentDay === 'sunday';

const isSaturday =
  currentDay === 'saturday';


// ============================================================
// 8. OPERATING MODE
// ============================================================

let operatingMode = 'WEEKDAY';

if (fridayS5Overnight === true) {

  operatingMode = 'FRIDAY_S5';

}
else if (isSaturday) {

  operatingMode = 'SATURDAY';

}
else if (isSunday) {

  operatingMode = 'SUNDAY';

}


// ============================================================
// 9. HELPER FUNCTIONS
// ============================================================

function normalize(value) {

  return String(value ?? '')
    .trim()
    .toLowerCase();

}


function getLevelMaxTickets(level) {

  const normalized =
    normalize(level);

  if (normalized === 'level1') {

    return maxLevel1Tickets;

  }

  if (normalized === 'level2') {

    return maxLevel2Tickets;

  }

  if (normalized === 'level3') {

    return maxLevel3Tickets;

  }

  return 0;

}


// ============================================================
// 10. FIND WORKLOAD RECORD
// ============================================================

function findWorkload(engineer) {

  const memberId =
    normalize(
      engineer.MemberID
    );

  const engineerName =
    normalize(
      engineer.EngineerName
    );

  return workloadByEngineer.find(
    workload => {

      const workloadMemberId =
        normalize(
          workload.MemberID ??
          workload.memberId
        );

      const workloadEngineerName =
        normalize(
          workload.EngineerName
        );

      return (
        (
          memberId &&
          workloadMemberId === memberId
        )
        ||
        (
          engineerName &&
          workloadEngineerName === engineerName
        )
      );

    }
  ) || null;

}


// ============================================================
// 11. ENRICH ENGINEER
// ============================================================
//
// Normal weekday:
//
//   CurrentTicketCount < MaxTickets
//
// Saturday:
//
//   Workload limit is COMPLETELY IGNORED.
//
// This is the critical Saturday rule.
//

function enrichEngineer(engineer) {

  const workload =
    findWorkload(engineer);

  const level =
    engineer.AssignmentLevel ??
    'Level1';


  // ----------------------------------------------------------
  // CURRENT TICKET COUNT
  // ----------------------------------------------------------

  const currentTicketCount =
    Number(
      engineer.CurrentTicketCount ??
      engineer.ActiveTicketCount ??
      engineer.TicketCount ??
      workload?.TicketCount ??
      workload?.ActiveTicketCount ??
      0
    );


  // ----------------------------------------------------------
  // NORMAL MAX TICKETS
  // ----------------------------------------------------------

  const configuredMaxTickets =
    Number(
      engineer.MaxTickets ??
      engineer.MaxAllowedTickets ??
      workload?.MaxTickets ??
      getLevelMaxTickets(level)
    );


  // ----------------------------------------------------------
  // SATURDAY
  // ----------------------------------------------------------
  //
  // Saturday has NO workload cap.
  //
  // We deliberately expose:
  //
  //   WorkloadAvailable = true
  //   AtCapacity = false
  //   AtLimit = false
  //
  // regardless of CurrentTicketCount.
  //
  // This prevents CODE-006 from rejecting the engineer.
  //

  if (isSaturday) {

    return {

      ...engineer,

      CurrentTicketCount:
        currentTicketCount,

      ActiveTicketCount:
        currentTicketCount,

      // Keep the configured value for visibility only.
      MaxTickets:
        configuredMaxTickets,

      MaxAllowedTickets:
        configuredMaxTickets,

      // Saturday has unlimited assignment capacity.
      AvailableCapacity:
        null,

      RemainingCapacity:
        null,

      WorkloadAvailable:
        true,

      AtCapacity:
        false,

      AtLimit:
        false,

      SaturdayUnlimited:
        true

    };

  }


  // ==========================================================
  // NORMAL WEEKDAY WORKLOAD CALCULATION
  // ==========================================================

  const availableCapacity =
    Math.max(
      0,
      configuredMaxTickets -
      currentTicketCount
    );

  const workloadAvailable =
    availableCapacity > 0;

  const atCapacity =
    availableCapacity <= 0;

  const atLimit =
    availableCapacity <= 0;


  return {

    ...engineer,

    CurrentTicketCount:
      currentTicketCount,

    ActiveTicketCount:
      currentTicketCount,

    MaxTickets:
      configuredMaxTickets,

    MaxAllowedTickets:
      configuredMaxTickets,

    AvailableCapacity:
      availableCapacity,

    RemainingCapacity:
      availableCapacity,

    WorkloadAvailable:
      workloadAvailable,

    AtCapacity:
      atCapacity,

    AtLimit:
      atLimit,

    SaturdayUnlimited:
      false

  };

}


// ============================================================
// 12. ENRICH ALL ENGINEERS
// ============================================================

const evaluatedEngineers =
  eligibleEngineers.map(
    engineer =>
      enrichEngineer(
        engineer
      )
  );


// ============================================================
// 13. GET ALL ENGINEERS FOR A LEVEL
// ============================================================

function getAllLevelCandidates(level) {

  const normalizedLevel =
    normalize(level);

  return evaluatedEngineers.filter(
    engineer => {

      return (
        normalize(
          engineer.AssignmentLevel
        ) === normalizedLevel
      );

    }
  );

}


// ============================================================
// 14. GET ELIGIBLE ENGINEERS FOR LEVEL
// ============================================================
//
// Common eligibility:
//   Eligible !== false
//   CurrentlyOut !== true
//
// Workload:
//   Saturday → ignored
//   Weekday  → must have capacity
//
// Shift/roster availability should already have been
// established by the upstream modules and represented in
// Eligible / CurrentlyOut / related fields.
//
// ============================================================

function getLevelCandidates(level) {

  const normalizedLevel =
    normalize(level);

  return evaluatedEngineers.filter(
    engineer => {

      // ------------------------------------------------------
      // LEVEL
      // ------------------------------------------------------

      if (
        normalize(
          engineer.AssignmentLevel
        ) !== normalizedLevel
      ) {

        return false;

      }


      // ------------------------------------------------------
      // GENERAL ELIGIBILITY
      // ------------------------------------------------------

      if (
        engineer.Eligible === false
      ) {

        return false;

      }


      // ------------------------------------------------------
      // OUT OF OFFICE
      // ------------------------------------------------------

      if (
        engineer.CurrentlyOut === true
      ) {

        return false;

      }


      // ------------------------------------------------------
      // SATURDAY
      // ------------------------------------------------------
      //
      // NO WORKLOAD CHECK.
      //
      // This is intentional.
      //

      if (isSaturday) {

        return true;

      }


      // ------------------------------------------------------
      // WEEKDAY WORKLOAD CHECK
      // ------------------------------------------------------

      if (
        engineer.WorkloadAvailable !== true
      ) {

        return false;

      }

      if (
        engineer.AtCapacity === true
      ) {

        return false;

      }

      if (
        engineer.AtLimit === true
      ) {

        return false;

      }


      return true;

    }
  );

}


