// ============================================================
// 18. EVALUATE LEVELS
// ============================================================

let selectedEngineer =
  null;

let selectedLevel =
  null;

let escalationRequired =
  false;

const evaluationLog =
  [];


// ============================================================
// 19. LOOP THROUGH ESCALATION PATH
// ============================================================

for (
  let i = 0;
  i < escalationPath.length;
  i++
) {

  const level =
    escalationPath[i];


  const allLevelCandidates =
    getAllLevelCandidates(
      level
    );


  const availableCandidates =
    getLevelCandidates(
      level
    );


  // ----------------------------------------------------------
  // LOG
  // ----------------------------------------------------------

  evaluationLog.push({

    Level:
      level,

    Escalated:
      i > 0,

    EligibleCandidateCount:
      allLevelCandidates.length,

    WorkloadCheck:
      'ENFORCED',

    WorkloadRule:
      'CURRENT_TICKETS_LT_MAX_TICKETS',

    WorkloadAvailableCandidateCount:
      availableCandidates.length,

    WorkloadUnavailableCandidateCount:
      allLevelCandidates.length -
      availableCandidates.length

  });


  // ----------------------------------------------------------
  // AVAILABLE ENGINEER FOUND
  // ----------------------------------------------------------

  if (
    availableCandidates.length > 0
  ) {

    selectedLevel =
      level;

    selectedEngineer =
      availableCandidates[0];

    escalationRequired =
      i > 0;

    break;

  }

}


