// ---------------------------------------------------------------
// 3. DATE HELPERS
// ---------------------------------------------------------------

function pad2(value) {

  return String(value)
    .padStart(2, "0");

}


function toDateOnlyUTC(date) {

  return new Date(
    Date.UTC(
      date.getUTCFullYear(),
      date.getUTCMonth(),
      date.getUTCDate()
    )
  );

}


function formatDateUTC(date) {

  return (
    date.getUTCFullYear() +
    "-" +
    pad2(date.getUTCMonth() + 1) +
    "-" +
    pad2(date.getUTCDate())
  );

}


function parseDMY(text) {

  const match =
    String(text)
      .trim()
      .match(
        /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/
      );

  if (!match) {
    return null;
  }

  const day =
    Number(match[1]);

  const month =
    Number(match[2]);

  const year =
    Number(match[3]);

  return new Date(
    Date.UTC(
      year,
      month - 1,
      day
    )
  );

}


function parseMonthName(monthText) {

  const months = {

    jan: 0,
    january: 0,

    feb: 1,
    february: 1,

    mar: 2,
    march: 2,

    apr: 3,
    april: 3,

    may: 4,

    jun: 5,
    june: 5,

    jul: 6,
    july: 6,

    aug: 7,
    august: 7,

    sep: 8,
    sept: 8,
    september: 8,

    oct: 9,
    october: 9,

    nov: 10,
    november: 10,

    dec: 11,
    december: 11

  };

  const key =
    String(monthText)
      .trim()
      .toLowerCase();

  return Object.prototype.hasOwnProperty.call(
    months,
    key
  )
    ? months[key]
    : null;

}


// ---------------------------------------------------------------
// 4. PARSE ROSTER PERIOD
// ---------------------------------------------------------------

function parseRosterPeriod(label) {

  if (!label) {
    return null;
  }

  const text =
    String(label)
      .replace(/\u00a0/g, " ")
      .replace(/\s+/g, " ")
      .trim();

  const match =
    text.match(
      /^(\d{1,2})\s+([A-Za-z]+)\s*-\s*(\d{1,2})\s+([A-Za-z]+)$/
    );

  if (!match) {
    return null;
  }

  const startDay =
    Number(match[1]);

  const startMonth =
    parseMonthName(match[2]);

  const endDay =
    Number(match[3]);

  const endMonth =
    parseMonthName(match[4]);

  if (
    startMonth === null ||
    endMonth === null
  ) {
    return null;
  }

  const currentYear =
    new Date().getUTCFullYear();

  let startDate =
    new Date(
      Date.UTC(
        currentYear,
        startMonth,
        startDay
      )
    );

  let endDate =
    new Date(
      Date.UTC(
        currentYear,
        endMonth,
        endDay
      )
    );

  if (endDate < startDate) {

    endDate =
      new Date(
        Date.UTC(
          currentYear + 1,
          endMonth,
          endDay
        )
      );

  }

  return {

    label: text,

    startDate,

    endDate,

    startDateText:
      formatDateUTC(startDate),

    endDateText:
      formatDateUTC(endDate)

  };

}


// ---------------------------------------------------------------
// 5. FIND ALL ROSTER PERIODS
// ---------------------------------------------------------------

const detectedPeriods = [];

for (const row of originalRows) {

  for (const key of Object.keys(row)) {

    const value =
      row[key];

    if (
      typeof value !== "string" ||
      !value.trim()
    ) {
      continue;
    }

    const parsed =
      parseRosterPeriod(value);

    if (!parsed) {
      continue;
    }

    const alreadyExists =
      detectedPeriods.some(
        p =>
          p.label === parsed.label &&
          p.startDateText === parsed.startDateText &&
          p.endDateText === parsed.endDateText
      );

    if (!alreadyExists) {

      detectedPeriods.push(
        parsed
      );

    }

  }

}


if (!detectedPeriods.length) {

  throw new Error(
    "ROSTER-001: No roster period was detected in OriginalRoster."
  );

}


// ---------------------------------------------------------------
// 6. SELECT ACTIVE / NEXT ROSTER PERIOD
// ---------------------------------------------------------------

const now =
  new Date();

const currentDate =
  toDateOnlyUTC(now);

let selectedPeriod =
  detectedPeriods.find(
    period =>
      currentDate >= period.startDate &&
      currentDate <= period.endDate
  );


// If today is not inside a roster period,
// choose next upcoming period.

if (!selectedPeriod) {

  const futurePeriods =
    detectedPeriods
      .filter(
        period =>
          period.startDate > currentDate
      )
      .sort(
        (a, b) =>
          a.startDate - b.startDate
      );

  if (futurePeriods.length) {

    selectedPeriod =
      futurePeriods[0];

  }

}


// If still nothing, use most recent period.

if (!selectedPeriod) {

  selectedPeriod =
    [...detectedPeriods]
      .sort(
        (a, b) =>
          b.startDate - a.startDate
      )[0];

}


// ---------------------------------------------------------------
// 7. LOCATE PERIOD HEADER ROW
// ---------------------------------------------------------------

let periodHeaderIndex = -1;

for (
  let i = 0;
  i < originalRows.length;
  i++
) {

  const row =
    originalRows[i];

  const found =
    Object.values(row).some(
      value =>
        String(value ?? "").trim() ===
        selectedPeriod.label
    );

  if (found) {

    periodHeaderIndex =
      i;

    break;

  }

}


if (periodHeaderIndex === -1) {

  throw new Error(
    `ROSTER-001: Selected roster period "${selectedPeriod.label}" was found, but its header row could not be located.`
  );

}


// ---------------------------------------------------------------
// 8. FIND WEEKDAY HEADER ROW
// ---------------------------------------------------------------

let dayHeaderIndex = -1;

for (
  let i = periodHeaderIndex + 1;
  i < originalRows.length;
  i++
) {

  const row =
    originalRows[i];

  const values =
    Object.values(row)
      .map(
        v =>
          String(v ?? "").trim()
      );

  const dayCount =
    DAYS.filter(
      day =>
        values.includes(day)
    ).length;

  if (dayCount >= 5) {

    dayHeaderIndex =
      i;

    break;

  }

}


if (dayHeaderIndex === -1) {

  throw new Error(
    `ROSTER-001: Weekday header was not found for roster period "${selectedPeriod.label}".`
  );

}


// ---------------------------------------------------------------
// 9. GET ENGINEER MASTER
// ---------------------------------------------------------------

const ENGINEER_MASTER_NODE =
  "GS-003 – Read EngineerMaster";

let engineerMasterItems = [];

try {

  engineerMasterItems =
    $(ENGINEER_MASTER_NODE).all();

}
catch (error) {

  engineerMasterItems = [];

}


// ---------------------------------------------------------------
// 10. BUILD ENGINEER MASTER LOOKUP
// ---------------------------------------------------------------

const engineerMasterMap =
  new Map();


function normalizeName(value) {

  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");

}


function normalizeMemberId(value) {

  return String(value ?? "")
    .trim()
    .toLowerCase();

}


for (const item of engineerMasterItems) {

  const row =
    item.json || {};

  const engineerName =
    row.Engineer_Name ??
    row.EngineerName ??
    row["Engineer Name"] ??
    row.name ??
    "";

  const memberId =
    row.Member_ID ??
    row.MemberID ??
    row["Member ID"] ??
    "";

  const level =
    row.Assignment_Level ??
    row.AssignmentLevel ??
    row["Assignment Level"] ??
    "";

  const active =
    row.Active ??
    "Yes";

  if (!engineerName) {
    continue;
  }

  engineerMasterMap.set(
    normalizeName(engineerName),
    {

      EngineerName:
        String(engineerName).trim(),

      MemberID:
        String(memberId).trim(),

      AssignmentLevel:
        String(level).trim(),

      Active:
        String(active).trim()

    }
  );

}


// ---------------------------------------------------------------
// 11. SHIFT MASTER
// ---------------------------------------------------------------

const SHIFT_MASTER_NODE =
  "GS-002 – Read ShiftMaster";

let shiftMasterItems = [];

try {

  shiftMasterItems =
    $(SHIFT_MASTER_NODE).all();

}
catch (error) {

  shiftMasterItems = [];

}


// ---------------------------------------------------------------
// 12. BUILD SHIFT LOOKUP
// ---------------------------------------------------------------

const shiftMap =
  new Map();


function normalizeTime(value) {

  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");

}


for (const item of shiftMasterItems) {

  const row =
    item.json || {};

  const shiftId =
    row.Shift_ID ??
    row.ShiftID ??
    "";

  const start =
    row.Start_Time ??
    row.StartTime ??
    "";

  const end =
    row.End_Time ??
    row.EndTime ??
    "";

  if (!shiftId) {
    continue;
  }

  const key =
    normalizeTime(start) +
    "|" +
    normalizeTime(end);

  shiftMap.set(
    key,
    {

      Shift_ID:
        String(shiftId).trim(),

      Shift_Start:
        String(start).trim(),

      Shift_End:
        String(end).trim()

    }
  );

}


// ---------------------------------------------------------------
// 13. FALLBACK SHIFT MAP
// ---------------------------------------------------------------

const fallbackShifts = [

  {
    Shift_ID: "S1",
    Shift_Start: "8:00",
    Shift_End: "17:30"
  },

  {
    Shift_ID: "S2",
    Shift_Start: "11:00",
    Shift_End: "20:30"
  },

  {
    Shift_ID: "S3",
    Shift_Start: "12:30",
    Shift_End: "22:00"
  },

  {
    Shift_ID: "S4",
    Shift_Start: "14:30",
    Shift_End: "00:00"
  },

  {
    Shift_ID: "S5",
    Shift_Start: "17:30",
    Shift_End: "03:00"
  }

];


// ---------------------------------------------------------------
// 14. CONVERT TIMES TO MINUTES
// ---------------------------------------------------------------

function timeToMinutes(value) {

  if (!value) {
    return null;
  }

  let text =
    String(value)
      .trim()
      .toLowerCase();

  const ampmMatch =
    text.match(
      /^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$/
    );

  if (ampmMatch) {

    let hour =
      Number(ampmMatch[1]);

    const minute =
      Number(ampmMatch[2] || 0);

    const ampm =
      ampmMatch[3];

    if (
      ampm === "pm" &&
      hour !== 12
    ) {
      hour += 12;
    }

    if (
      ampm === "am" &&
      hour === 12
    ) {
      hour = 0;
    }

    return (
      hour * 60 +
      minute
    );

  }

  const twentyFour =
    text.match(
      /^(\d{1,2}):(\d{2})$/
    );

  if (twentyFour) {

    return (
      Number(twentyFour[1]) * 60 +
      Number(twentyFour[2])
    );

  }

  return null;

}


// ---------------------------------------------------------------
// 15. GET SHIFT ID
// ---------------------------------------------------------------

function getShiftId(
  start,
  end
) {

  const startMin =
    timeToMinutes(start);

  const endMin =
    timeToMinutes(end);


  // First try ShiftMaster.

  for (const shift of shiftMap.values()) {

    const smStart =
      timeToMinutes(
        shift.Shift_Start
      );

    const smEnd =
      timeToMinutes(
        shift.Shift_End
      );

    if (
      smStart === startMin &&
      smEnd === endMin
    ) {

      return shift.Shift_ID;

    }

  }


  // Then fallback.

  for (const shift of fallbackShifts) {

    const smStart =
      timeToMinutes(
        shift.Shift_Start
      );

    const smEnd =
      timeToMinutes(
        shift.Shift_End
      );

    if (
      smStart === startMin &&
      smEnd === endMin
    ) {

      return shift.Shift_ID;

    }

  }

  return null;

}


// ---------------------------------------------------------------
// 16. FIND ENGINEER MASTER MATCH
// ---------------------------------------------------------------

function findEngineer(name) {

  const normalized =
    normalizeName(name);

  if (!normalized) {
    return null;
  }


  // Exact match.

  if (
    engineerMasterMap.has(
      normalized
    )
  ) {

    return engineerMasterMap.get(
      normalized
    );

  }


  // Partial/first-name matching.

  const matches = [];

  for (
    const engineer
    of engineerMasterMap.values()
  ) {

    const masterName =
      normalizeName(
        engineer.EngineerName
      );

    const firstName =
      masterName.split(" ")[0];

    if (
      normalized === firstName ||
      masterName.startsWith(
        normalized + " "
      )
    ) {

      matches.push(
        engineer
      );

    }

  }

  if (matches.length === 1) {
    return matches[0];
  }

  return null;

}


// ---------------------------------------------------------------
// 17. DETECT ROSTER DATA RANGE
// ---------------------------------------------------------------

let dataEndIndex =
  originalRows.length;

for (
  let i = dayHeaderIndex + 1;
  i < originalRows.length;
  i++
) {

  const row =
    originalRows[i];

  const isAnotherPeriod =
    Object.values(row).some(
      value => {

        const parsed =
          parseRosterPeriod(
            String(value ?? "").trim()
          );

        return (
          parsed &&
          parsed.label !==
            selectedPeriod.label
        );

      }
    );

  if (isAnotherPeriod) {

    dataEndIndex =
      i;

    break;

  }

}


// ---------------------------------------------------------------
// 18. PROCESS SHIFT GROUPS
// ---------------------------------------------------------------

const weeklyRoster = [];
const validationErrors = [];

let currentShift = null;

for (
  let i = dayHeaderIndex + 1;
  i < dataEndIndex;
  i++
) {

  const row =
    originalRows[i];

  const shiftStart =
    String(
      row["Shift Start"] ?? ""
    ).trim();

  const shiftEnd =
    String(
      row["Shift End"] ?? ""
    ).trim();


  // New shift begins.

  if (
    shiftStart &&
    shiftEnd
  ) {

    const shiftId =
      getShiftId(
        shiftStart,
        shiftEnd
      );

    if (!shiftId) {

      validationErrors.push({

        Type:
          "SHIFT_MAPPING_ERROR",

        Row:
          row.row_number ?? null,

        ShiftStart:
          shiftStart,

        ShiftEnd:
          shiftEnd,

        Message:
          "Unable to map OriginalRoster timing to ShiftMaster."

      });

    }

    currentShift = {

      Shift_ID:
        shiftId,

      Shift_Start:
        shiftStart,

      Shift_End:
        shiftEnd

    };

  }


  // No shift established yet.

  if (!currentShift) {
    continue;
  }


  // Process each day.

  for (const day of DAYS) {

    const columns =
      DAY_COLUMN_MAP[day] || [];


    for (const column of columns) {

      const rawName =
        String(
          row[column] ?? ""
        ).trim();

      if (!rawName) {
        continue;
      }


      // Ignore accidental header values.

      if (
        DAYS.includes(rawName)
      ) {
        continue;
      }


      // EngineerMaster validation.

      const engineer =
        findEngineer(rawName);

      if (!engineer) {

        validationErrors.push({

          Type:
            "UNKNOWN_ENGINEER",

          Row:
            row.row_number ?? null,

          Day:
            day,

          Shift_ID:
            currentShift.Shift_ID,

          Engineer_Name:
            rawName,

          Message:
            "Engineer exists in OriginalRoster but could not be uniquely matched in EngineerMaster."

        });

        continue;

      }


      // Active validation.

      const activeValue =
        String(
          engineer.Active ?? "Yes"
        )
          .trim()
          .toLowerCase();

      if (
        activeValue === "no" ||
        activeValue === "false" ||
        activeValue === "inactive"
      ) {

        validationErrors.push({

          Type:
            "INACTIVE_ENGINEER",

          Row:
            row.row_number ?? null,

          Day:
            day,

          Shift_ID:
            currentShift.Shift_ID,

          Engineer_Name:
            engineer.EngineerName,

          Message:
            "Engineer is present in OriginalRoster but inactive in EngineerMaster."

        });

        continue;

      }


      // Create normalized WeeklyRoster record.

      weeklyRoster.push({

        Effective_From:
          selectedPeriod.startDateText,

        Effective_To:
          selectedPeriod.endDateText,

        Day:
          day,

        Shift_ID:
          currentShift.Shift_ID,

        Shift_Start:
          currentShift.Shift_Start,

        Shift_End:
          currentShift.Shift_End,

        Engineer_Name:
          engineer.EngineerName,

        Member_ID:
          engineer.MemberID,

        Assignment_Level:
          engineer.AssignmentLevel,

        Available:
          "Yes",

        Source:
          "OriginalRoster",

        RosterPeriod:
          selectedPeriod.label

      });

    }

  }

}


// ---------------------------------------------------------------
// 19. REMOVE DUPLICATES
// ---------------------------------------------------------------

const uniqueMap =
  new Map();

for (
  const record
  of weeklyRoster
) {

  const key =
    [

      record.Effective_From,

      record.Effective_To,

      record.Day,

      record.Shift_ID,

      normalizeMemberId(
        record.Member_ID
      )

    ].join("|");


  if (!uniqueMap.has(key)) {

    uniqueMap.set(
      key,
      record
    );

  }

}

let finalRoster =
  Array.from(
    uniqueMap.values()
  );


// ===============================================================
// 20. L1 ROTATION NORMALIZATION
// ===============================================================
//
// IMPORTANT
// ---------
// The L1 engineer is NOT hard-coded.
//
// The L1 engineer actually present on Saturday in
// OriginalRoster becomes the rotating L1.
//
// ROTATING L1 SCHEDULE:
//
// Monday     = OFF
// Tuesday    = S3
// Wednesday  = S3
// Thursday   = S3
// Friday     = S3
// Saturday   = S2
// Sunday     = OFF
//
// The other L1 remains:
//
// Monday     = S1
// Tuesday    = S1
// Wednesday  = S1
// Thursday   = S1
// Friday     = S1
// Saturday   = OFF
// Sunday     = OFF
//
// ONLY LEVEL1 records are affected.
//
// LEVEL2 AND LEVEL3 ARE NOT MODIFIED.
// ===============================================================


// ---------------------------------------------------------------
// 20A. Find L1 engineers present on Saturday.
// ---------------------------------------------------------------

const saturdayL1Records =
  finalRoster.filter(
    record =>

      record.Day === "Saturday" &&

      String(
        record.Assignment_Level ?? ""
      )
        .trim()
        .toLowerCase() === "level1"
  );


// ---------------------------------------------------------------
// 20B. Identify rotating L1.
// ---------------------------------------------------------------

let rotatingL1 = null;

if (
  saturdayL1Records.length === 1
) {

  rotatingL1 =
    saturdayL1Records[0];

}
else if (
  saturdayL1Records.length > 1
) {

  validationErrors.push({

    Type:
      "MULTIPLE_L1_SATURDAY",

    Count:
      saturdayL1Records.length,

    Engineers:
      saturdayL1Records.map(
        r => r.Engineer_Name
      ),

    Message:
      "More than one Level1 engineer is scheduled on Saturday."

  });

}
else {

  validationErrors.push({

    Type:
      "NO_L1_SATURDAY",

    Message:
      "No Level1 engineer is scheduled on Saturday for this roster cycle."

  });

}


// ---------------------------------------------------------------
// 20C. Normalize rotating L1.
// ---------------------------------------------------------------
//
// Tuesday-Friday:
//     S3 = 12:30 - 22:00
//
// Saturday:
//     S2 = 11:00 - 20:30
//
// Monday/Sunday:
//     No record is created or introduced.
//
// IMPORTANT:
// We only MODIFY existing records.
// We never create a new engineer record here.
// ---------------------------------------------------------------

if (rotatingL1) {

  const rotatingMemberId =
    normalizeMemberId(
      rotatingL1.Member_ID
    );


  for (
    const record
    of finalRoster
  ) {

    // Only modify the rotating L1.

    if (
      normalizeMemberId(
        record.Member_ID
      ) !== rotatingMemberId
    ) {
      continue;
    }


    // Only Level1.

    if (
      String(
        record.Assignment_Level ?? ""
      )
        .trim()
        .toLowerCase() !== "level1"
    ) {
      continue;
    }


    // ---------------------------------------------------------
    // Tuesday-Friday = S3
    // ---------------------------------------------------------

    if (
      [
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday"
      ].includes(
        record.Day
      )
    ) {

      record.Shift_ID =
        "S3";

      record.Shift_Start =
        "12:30";

      record.Shift_End =
        "22:00";

      record.L1RotationApplied =
        true;

      record.L1RotationType =
        "Rotating-L1-S3-Tuesday-Friday";

    }


    // ---------------------------------------------------------
    // Saturday = S2
    // ---------------------------------------------------------

    if (
      record.Day === "Saturday"
    ) {

      record.Shift_ID =
        "S2";

      record.Shift_Start =
        "11:00";

      record.Shift_End =
        "20:30";

      record.L1RotationApplied =
        true;

      record.L1RotationType =
        "Rotating-L1-S2-Saturday";

    }

  }

}


// ---------------------------------------------------------------
// 20D. Identify weekday S1 L1.
// ---------------------------------------------------------------

const weekdayS1L1Records =
  finalRoster.filter(
    record =>

      [
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday"
      ].includes(
        record.Day
      ) &&

      String(
        record.Assignment_Level ?? ""
      )
        .trim()
        .toLowerCase() === "level1" &&

      String(
        record.Shift_ID ?? ""
      )
        .trim()
        .toUpperCase() === "S1"
  );


// ---------------------------------------------------------------
// 20E. Identify S1 L1 engineer.
// ---------------------------------------------------------------

let l1S1Engineer =
  null;

if (
  weekdayS1L1Records.length
) {

  const uniqueS1 =
    new Map();

  for (
    const record
    of weekdayS1L1Records
  ) {

    uniqueS1.set(
      normalizeMemberId(
        record.Member_ID
      ),
      record
    );

  }

  const values =
    Array.from(
      uniqueS1.values()
    );

  if (values.length === 1) {

    l1S1Engineer =
      values[0];

  }

}


const l1S2Engineer =
  rotatingL1;


// ---------------------------------------------------------------
// 20F. L1 ROTATION VALIDATION OBJECT
// ---------------------------------------------------------------

const l1RotationValidation = {

  Status:
    "CHECKED",

  S1Engineer:
    l1S1Engineer
      ? l1S1Engineer.Engineer_Name
      : null,

  S2Engineer:
    l1S2Engineer
      ? l1S2Engineer.Engineer_Name
      : null,

  SaturdayS2Engineer:
    rotatingL1
      ? rotatingL1.Engineer_Name
      : null,

  TuesdayToFridayS3Engineer:
    rotatingL1
      ? rotatingL1.Engineer_Name
      : null,

  SundayEngineers:
    finalRoster
      .filter(
        record =>
          record.Day === "Sunday" &&
          String(
            record.Assignment_Level ?? ""
          )
            .trim()
            .toLowerCase() === "level1"
      )
      .map(
        record =>
          record.Engineer_Name
      ),

  Errors: []

};


// ---------------------------------------------------------------
// RULE 1
// ---------------------------------------------------------------
// Rotating L1 must work S3 Tuesday-Friday.

if (rotatingL1) {

  const rotatingMemberId =
    normalizeMemberId(
      rotatingL1.Member_ID
    );

  for (
    const day
    of [
      "Tuesday",
      "Wednesday",
      "Thursday",
      "Friday"
    ]
  ) {

    const matching =
      finalRoster.filter(
        record =>

          record.Day === day &&

          normalizeMemberId(
            record.Member_ID
          ) === rotatingMemberId &&

          String(
            record.Assignment_Level ?? ""
          )
            .trim()
            .toLowerCase() === "level1"
      );

    if (
      matching.length !== 1 ||
      matching[0].Shift_ID !== "S3"
    ) {

      l1RotationValidation.Errors.push({

        Rule:
          "L1_ROTATING_RESOURCE_MUST_WORK_S3_TUE_FRI",

        Engineer:
          rotatingL1.Engineer_Name,

        Day:
          day,

        Expected:
          "S3",

        Actual:
          matching.length
            ? matching[0].Shift_ID
            : null

      });

    }

  }

}


// ---------------------------------------------------------------
// RULE 2
// ---------------------------------------------------------------
// Rotating L1 must work Saturday S2.

if (rotatingL1) {

  const saturdayCorrect =
    finalRoster.some(
      record =>

        record.Day === "Saturday" &&

        normalizeMemberId(
          record.Member_ID
        ) ===
        normalizeMemberId(
          rotatingL1.Member_ID
        ) &&

        String(
          record.Shift_ID
        )
          .trim()
          .toUpperCase() === "S2" &&

        String(
          record.Assignment_Level ?? ""
        )
          .trim()
          .toLowerCase() === "level1"
    );

  if (!saturdayCorrect) {

    l1RotationValidation.Errors.push({

      Rule:
        "L1_ROTATING_RESOURCE_MUST_WORK_SATURDAY_S2",

      Engineer:
        rotatingL1.Engineer_Name,

      Expected:
        "Saturday S2"

    });

  }

}


// ---------------------------------------------------------------
// RULE 3
// ---------------------------------------------------------------
// S1 L1 must not work Saturday.

if (l1S1Engineer) {

  const s1Saturday =
    finalRoster.some(
      record =>

        record.Day === "Saturday" &&

        normalizeMemberId(
          record.Member_ID
        ) ===
        normalizeMemberId(
          l1S1Engineer.Member_ID
        ) &&

        String(
          record.Assignment_Level ?? ""
        )
          .trim()
          .toLowerCase() === "level1"
    );

  if (s1Saturday) {

    l1RotationValidation.Errors.push({

      Rule:
        "L1_S1_MUST_NOT_WORK_SATURDAY",

      Engineer:
        l1S1Engineer.Engineer_Name

    });

  }

}


// ---------------------------------------------------------------
// RULE 4
// ---------------------------------------------------------------
// Only one L1 should work Saturday.

const saturdayL1Count =
  finalRoster.filter(
    record =>

      record.Day === "Saturday" &&

      String(
        record.Assignment_Level ?? ""
      )
        .trim()
        .toLowerCase() === "level1"
  ).length;


if (
  saturdayL1Count !== 1
) {

  l1RotationValidation.Errors.push({

    Rule:
      "ONLY_ONE_L1_SATURDAY",

    ActualCount:
      saturdayL1Count

  });

}


// ---------------------------------------------------------------
// RULE 5
// ---------------------------------------------------------------
// Rotating L1 must not work Sunday.

if (rotatingL1) {

  const rotatingMemberId =
    normalizeMemberId(
      rotatingL1.Member_ID
    );

  const sundayRecord =
    finalRoster.some(
      record =>

        record.Day === "Sunday" &&

        normalizeMemberId(
          record.Member_ID
        ) === rotatingMemberId &&

        String(
          record.Assignment_Level ?? ""
        )
          .trim()
          .toLowerCase() === "level1"
    );

  if (sundayRecord) {

    l1RotationValidation.Errors.push({

      Rule:
        "L1_ROTATING_RESOURCE_MUST_HAVE_SUNDAY_OFF",

      Engineer:
        rotatingL1.Engineer_Name

    });

  }

}


// ---------------------------------------------------------------
// RULE 6
// ---------------------------------------------------------------
// Rotating L1 must NOT have a Monday record.
//
// IMPORTANT:
// We do NOT create a Monday OFF record.
// We simply validate that the rotating L1 is absent.
// ---------------------------------------------------------------

if (rotatingL1) {

  const rotatingMemberId =
    normalizeMemberId(
      rotatingL1.Member_ID
    );

  const mondayRecord =
    finalRoster.some(
      record =>

        record.Day === "Monday" &&

        normalizeMemberId(
          record.Member_ID
        ) === rotatingMemberId &&

        String(
          record.Assignment_Level ?? ""
        )
          .trim()
          .toLowerCase() === "level1"
    );

  if (mondayRecord) {

    l1RotationValidation.Errors.push({

      Rule:
        "L1_ROTATING_RESOURCE_MUST_HAVE_MONDAY_OFF",

      Engineer:
        rotatingL1.Engineer_Name

    });

  }

}


// ---------------------------------------------------------------
// FINAL L1 STATUS
// ---------------------------------------------------------------

if (
  l1RotationValidation.Errors.length === 0
) {

  l1RotationValidation.Status =
    "PASS";

}
else {

  l1RotationValidation.Status =
    "FAIL";

}


// ---------------------------------------------------------------
// 21. SORT OUTPUT
// ---------------------------------------------------------------

const dayOrder = {

  Monday: 1,
  Tuesday: 2,
  Wednesday: 3,
  Thursday: 4,
  Friday: 5,
  Saturday: 6,
  Sunday: 7

};


finalRoster.sort(
  (a, b) => {

    if (
      dayOrder[a.Day] !==
      dayOrder[b.Day]
    ) {

      return (
        dayOrder[a.Day] -
        dayOrder[b.Day]
      );

    }

    return String(
      a.Shift_ID
    ).localeCompare(
      String(b.Shift_ID)
    );

  }
);


// ---------------------------------------------------------------
// 22. RETURN RESULT
// ---------------------------------------------------------------

return [

  {

    json: {

      Status:
        "ROSTER-001 OK",

      GeneratedAtUTC:
        new Date().toISOString(),

      CurrentDate:
        formatDateUTC(currentDate),

      SelectedRosterPeriod:
        selectedPeriod.label,

      Effective_From:
        selectedPeriod.startDateText,

      Effective_To:
        selectedPeriod.endDateText,

      Source:
        "OriginalRoster",

      EngineerMasterValidated:
        engineerMasterMap.size > 0,

      TotalDetectedPeriods:
        detectedPeriods.length,

      DetectedPeriods:
        detectedPeriods.map(
          p => ({

            label:
              p.label,

            startDate:
              p.startDateText,

            endDate:
              p.endDateText

          })
        ),

      TotalNormalizedRecords:
        finalRoster.length,

      WeeklyRoster:
        finalRoster,

      ValidationErrorCount:
        validationErrors.length,

      ValidationErrors:
        validationErrors,

      L1RotationValidation:
        l1RotationValidation

    }

  }

];

// ============================================================
// CODE-007 – Prepare WeeklyRoster Rows
// ============================================================
// Purpose:
// Convert ROSTER-001.WeeklyRoster[] into individual n8n items
// ready for Google Sheets → WeeklyRoster.
//
// Source:
// ROSTER-001 – Build WeeklyRoster
//
// IMPORTANT:
// This node does NOT create engineers.
// It only writes engineers that ROSTER-001 generated.
// Therefore OriginalRoster remains the authoritative source.
// ============================================================

const inputItems = $input.all();

if (!inputItems.length) {
  throw new Error(
    "CODE-007: No input received from ROSTER-001."
  );
}

// ------------------------------------------------------------
// Get ROSTER-001 output
// ------------------------------------------------------------

const source = inputItems[0].json;

if (!Array.isArray(source.WeeklyRoster)) {
  throw new Error(
    "CODE-007: WeeklyRoster array was not found in ROSTER-001 output."
  );
}

const weeklyRoster = source.WeeklyRoster;

if (weeklyRoster.length === 0) {
  throw new Error(
    "CODE-007: ROSTER-001 returned an empty WeeklyRoster."
  );
}

// ------------------------------------------------------------
// Convert each roster record into one n8n item
// ------------------------------------------------------------

const output = [];

for (const row of weeklyRoster) {

  if (!row || typeof row !== "object") {
    continue;
  }

  const engineerName = String(
    row.Engineer_Name ?? ""
  ).trim();

  const memberId = String(
    row.Member_ID ?? ""
  ).trim();

  const assignmentLevel = String(
    row.Assignment_Level ?? ""
  ).trim();

  const day = String(
    row.Day ?? ""
  ).trim();

  const shiftId = String(
    row.Shift_ID ?? ""
  ).trim();

  const effectiveFrom = String(
    row.Effective_From ?? ""
  ).trim();

  const effectiveTo = String(
    row.Effective_To ?? ""
  ).trim();

  const available = String(
    row.Available ?? "Yes"
  ).trim();

  // ----------------------------------------------------------
  // Safety validation
  // ----------------------------------------------------------

  if (!engineerName) {
    throw new Error(
      `CODE-007: Engineer_Name is missing for ${day} / ${shiftId}.`
    );
  }

  if (!memberId) {
    throw new Error(
      `CODE-007: Member_ID is missing for engineer "${engineerName}".`
    );
  }

  if (!assignmentLevel) {
    throw new Error(
      `CODE-007: Assignment_Level is missing for engineer "${engineerName}".`
    );
  }

  if (!day) {
    throw new Error(
      `CODE-007: Day is missing for engineer "${engineerName}".`
    );
  }

  if (!shiftId) {
    throw new Error(
      `CODE-007: Shift_ID is missing for engineer "${engineerName}".`
    );
  }

  if (!effectiveFrom || !effectiveTo) {
    throw new Error(
      `CODE-007: Effective date range is missing for engineer "${engineerName}".`
    );
  }

  // ----------------------------------------------------------
  // Output exactly matching WeeklyRoster columns
  // ----------------------------------------------------------

  output.push({
    json: {
      Effective_From: effectiveFrom,
      Effective_To: effectiveTo,
      Day: day,
      Shift_ID: shiftId,
      Engineer_Name: engineerName,
      Member_ID: memberId,
      Assignment_Level: assignmentLevel,
      Available: available
    }
  });
}

// ------------------------------------------------------------
// Final validation
// ------------------------------------------------------------

if (output.length === 0) {
  throw new Error(
    "CODE-007: No valid WeeklyRoster records were generated."
  );
}

return output;

// ============================================================
// CODE-006 – ENGINEER SELECTION
// ============================================================
// PURPOSE
// ------------------------------------------------------------
// Select the final engineer from CODE-005 candidates.
//
// BUSINESS RULES
// ------------------------------------------------------------
//
// SATURDAY:
//   • LEVEL1 ONLY
//   • UNLIMITED TICKETS
//   • CurrentTicketCount DOES NOT matter
//   • MaxTickets DOES NOT matter
//   • WorkloadAvailable DOES NOT matter
//   • AtCapacity DOES NOT matter
//   • AtLimit DOES NOT matter
//   • NO escalation to Level2 / Level3
//   • Shift / roster / eligibility / CurrentlyOut still matter
//   • RoundRobin is used when multiple L1 engineers exist
//
// SUNDAY:
//   • NO ASSIGNMENT
//
// MONDAY-FRIDAY:
//   • CODE-005 controls assignment decision
//   • Workload limits apply
//   • L1 → L2 → L3 escalation applies
//   • RoundRobin uses GS-008 assignment state
//
// FRIDAY S5:
//   • Controlled by CODE-005
//   • Normal weekday workload rules remain applicable
//
// IMPORTANT:
// ------------------------------------------------------------
// Saturday workload is intentionally bypassed.
// This bypass MUST NOT affect Monday-Friday.
// ============================================================


// ============================================================
// 1. GET CODE-005 DECISION
// ============================================================

let decision = null;

try {

  decision =
    $('CODE-005 – Escalation Engine')
      .first()
      .json;

} catch (e) {

  decision = null;

}


if (!decision) {

  return [
    {
      json: {

        Status:
          "MODULE-06 ERROR",

        Error:
          "CODE-005 decision input was not found",

        AssignmentReady:
          false,

        FinalDecision:
          "NO_ASSIGNMENT",

        SelectedEngineer:
          null,

        CandidateCount:
          0,

        EligibleCandidateCount:
          0,

        SelectionReason:
          "NO_CODE_005_INPUT"

      }
    }
  ];

}


// ============================================================
// 2. GET GS-008 ASSIGNMENT STATE
// ============================================================

let stateRows = [];

try {

  stateRows =
    $('GS-008 – Read Assignment State')
      .all()
      .map(item => item.json);

} catch (e) {

  stateRows = [];

}


// ============================================================
// 3. HELPERS
// ============================================================

function normalize(value) {

  return String(value ?? "")
    .trim()
    .toLowerCase();

}


function isTrue(value) {

  return (
    value === true ||
    normalize(value) === "true" ||
    normalize(value) === "yes" ||
    value === 1
  );

}


function number(value, fallback = 0) {

  const n =
    Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;

}


// ============================================================
// 4. CURRENT CONTEXT
// ============================================================

const currentDate =
  decision.CurrentDate ?? null;

const currentDay =
  normalize(
    decision.CurrentDay
  );

const currentTime =
  decision.CurrentTime ?? null;

const operationalDay =
  normalize(
    decision.OperationalDay
  ) || currentDay;

const fridayS5Overnight =
  isTrue(
    decision.FridayS5Overnight
  );

const isSaturday =
  isTrue(
    decision.IsSaturday
  ) ||
  currentDay === "saturday";

const isSunday =
  isTrue(
    decision.IsSunday
  ) ||
  currentDay === "sunday";

const assignmentMode =
  decision.AssignmentMode ||
  "RoundRobin";


// ============================================================
// 5. WORKLOAD CONFIGURATION
// ============================================================

const workloadSummary =
  decision.WorkloadSummary || {};

const maxLevel1 =
  number(
    workloadSummary.MaxLevel1Tickets,
    10
  );

const maxLevel2 =
  number(
    workloadSummary.MaxLevel2Tickets,
    10
  );

const maxLevel3 =
  number(
    workloadSummary.MaxLevel3Tickets,
    5
  );


function getMaxTickets(level) {

  const normalizedLevel =
    normalize(level);

  if (
    normalizedLevel === "level1"
  ) {

    return maxLevel1;

  }

  if (
    normalizedLevel === "level2"
  ) {

    return maxLevel2;

  }

  if (
    normalizedLevel === "level3"
  ) {

    return maxLevel3;

  }

  return 0;

}


// ============================================================
// 6. SUNDAY – NO ASSIGNMENT
// ============================================================
//
// Sunday always wins.
//
// Even if CODE-005 accidentally returns candidates,
// CODE-006 must not assign.
//
// ============================================================

if (isSunday) {

  return [
    {
      json: {

        Status:
          "MODULE-06 OK",

        CurrentDate:
          currentDate,

        CurrentDay:
          currentDay,

        CurrentTime:
          currentTime,

        RequiredLevel:
          decision.RequiredLevel ||
          "Level1",

        SelectedLevel:
          null,

        EscalationRequired:
          false,

        ShiftCoverageStatus:
          decision.ShiftCoverageStatus ??
          null,

        ExpectedL1Count:
          decision.ExpectedL1Count ??
          0,

        ActiveL1Count:
          decision.ActiveL1Count ??
          0,

        InactiveL1Count:
          decision.InactiveL1Count ??
          0,

        L1FirstAssignmentCompletedToday:
          decision.L1FirstAssignmentCompletedToday ??
          false,

        CoverageFirstAssignment:
          false,

        CoverageEscalation:
          false,

        CoverageDecision:
          "SUNDAY_NO_ASSIGNMENT",

        LastL1AssignmentDate:
          decision.LastL1AssignmentDate ??
          null,

        AssignmentMode:
          assignmentMode,

        AssignmentReady:
          false,

        FinalDecision:
          "NO_ASSIGNMENT",

        SelectedEngineer:
          null,

        SelectionReason:
          "SUNDAY_NO_ASSIGNMENT",

        CandidateCount:
          0,

        EligibleCandidateCount:
          0,

        EligibleCandidates:
          [],

        UnavailableCandidateCount:
          0,

        UnavailableCandidates:
          [],

        RequiredLevelCandidateCount:
          0,

        SelectedLevelCandidateCount:
          0,

        EligibleLevel1Count:
          decision.EligibleLevel1Count ??
          0,

        EligibleLevel2Count:
          decision.EligibleLevel2Count ??
          0,

        EligibleLevel3Count:
          decision.EligibleLevel3Count ??
          0,

        PreviousAssignmentState:
          {},

        StateUpdatePending:
          null,

        ConnectWiseUpdate: {

          TicketID:
            decision.TicketID ??
            null,

          Resource:
            null,

          AssignmentLevel:
            null

        },

        WorkloadSummary: {

          MaxLevel1Tickets:
            maxLevel1,

          MaxLevel2Tickets:
            maxLevel2,

          MaxLevel3Tickets:
            maxLevel3

        }

      }
    }
  ];

}


// ============================================================
// 7. GET CODE-005 CANDIDATES
// ============================================================

let candidates =
  Array.isArray(
    decision.CandidateEngineers
  )
    ? decision.CandidateEngineers
    : [];


// ============================================================
// 8. SATURDAY
// ============================================================
//
// IMPORTANT BUSINESS RULE:
//
// Saturday is NOT a workload-limited day.
//
// Therefore:
//   CurrentTicketCount → ignored
//   MaxTickets         → ignored
//   AvailableCapacity  → ignored
//   RemainingCapacity  → ignored
//   WorkloadAvailable  → ignored
//   AtCapacity         → ignored
//   AtLimit            → ignored
//
// We only care about:
//
//   • Level1
//   • Eligible
//   • CurrentlyOut
//
// CODE-005 should normally already give us L1 candidates,
// but CODE-006 enforces the rule again.
//
// ============================================================

if (isSaturday) {


  // ==========================================================
  // 8.1 GET ALL L1 CANDIDATES
  // ==========================================================

  const saturdayCandidates =
    candidates.filter(
      engineer =>
        normalize(
          engineer.AssignmentLevel
        ) === "level1"
    );


  // ==========================================================
  // 8.2 SATURDAY ELIGIBILITY
  // ==========================================================
  //
  // DO NOT CHECK WORKLOAD HERE.
  //
  // ==========================================================

  const eligibleSaturdayCandidates =
    saturdayCandidates.filter(
      engineer => {

        // Engineer must be eligible
        if (
          engineer.Eligible === false
        ) {

          return false;

        }


        // Engineer must not be out
        if (
          engineer.CurrentlyOut === true
        ) {

          return false;

        }


        // IMPORTANT:
        // NO WORKLOAD CHECKS HERE.
        //
        // Do NOT check:
        //   WorkloadAvailable
        //   AtCapacity
        //   AtLimit
        //   CurrentTicketCount
        //   MaxTickets
        //


        return true;

      }
    );


  // ==========================================================
  // 8.3 NO L1 ENGINEER AVAILABLE
  // ==========================================================

  if (
    eligibleSaturdayCandidates.length === 0
  ) {

    return [
      {
        json: {

          Status:
            "MODULE-06 OK",

          CurrentDate:
            currentDate,

          CurrentDay:
            currentDay,

          CurrentTime:
            currentTime,

          RequiredLevel:
            "Level1",

          SelectedLevel:
            null,

          EscalationRequired:
            false,

          ShiftCoverageStatus:
            decision.ShiftCoverageStatus ??
            "FULL",

          ExpectedL1Count:
            decision.ExpectedL1Count ??
            0,

          ActiveL1Count:
            decision.ActiveL1Count ??
            0,

          InactiveL1Count:
            decision.InactiveL1Count ??
            0,

          L1FirstAssignmentCompletedToday:
            decision.L1FirstAssignmentCompletedToday ??
            false,

          CoverageFirstAssignment:
            false,

          CoverageEscalation:
            false,

          CoverageDecision:
            "SATURDAY_L1_ONLY_NO_ELIGIBLE_ENGINEER",

          LastL1AssignmentDate:
            decision.LastL1AssignmentDate ??
            null,

          AssignmentMode:
            assignmentMode,

          AssignmentReady:
            false,

          FinalDecision:
            "NO_ASSIGNMENT",

          SelectedEngineer:
            null,

          SelectionReason:
            "SATURDAY_NO_ELIGIBLE_L1_ENGINEER",

          CandidateCount:
            saturdayCandidates.length,

          EligibleCandidateCount:
            0,

          EligibleCandidates:
            [],

          UnavailableCandidateCount:
            saturdayCandidates.length,

          UnavailableCandidates:
            saturdayCandidates,

          RequiredLevelCandidateCount:
            saturdayCandidates.length,

          SelectedLevelCandidateCount:
            0,

          EligibleLevel1Count:
            0,

          EligibleLevel2Count:
            0,

          EligibleLevel3Count:
            0,

          PreviousAssignmentState:
            {},

          StateUpdatePending:
            null,

          ConnectWiseUpdate: {

            TicketID:
              decision.TicketID ??
              null,

            Resource:
              null,

            AssignmentLevel:
              null

          },

          WorkloadSummary: {

            MaxLevel1Tickets:
              maxLevel1,

            MaxLevel2Tickets:
              maxLevel2,

            MaxLevel3Tickets:
              maxLevel3

          },

          SaturdayRule: {

            Level1Only:
              true,

            UnlimitedTickets:
              true,

            WorkloadCheck:
              false,

            EscalationAllowed:
              false

          }

        }
      }
    ];

  }


  // ==========================================================
  // 8.4 GET PREVIOUS L1 ASSIGNMENT
  // ==========================================================

  const previousState =
    stateRows.find(
      row =>
        normalize(
          row.Assignment_Level
        ) === "level1"
    ) || null;


  // ==========================================================
  // 8.5 ROUND ROBIN
  // ==========================================================

  let selectedEngineer =
    null;


  if (
    normalize(
      assignmentMode
    ) === "roundrobin" &&
    eligibleSaturdayCandidates.length > 1 &&
    previousState
  ) {

    const previousMember =
      normalize(
        previousState.Last_Member_ID
      );


    selectedEngineer =
      eligibleSaturdayCandidates.find(
        engineer =>
          normalize(
            engineer.MemberID
          ) !== previousMember
      ) ||
      eligibleSaturdayCandidates[0];

  }
  else {

    selectedEngineer =
      eligibleSaturdayCandidates[0];

  }


  // ==========================================================
  // 8.6 SELECTION ORDER
  // ==========================================================

  const orderedSaturdayCandidates =
    eligibleSaturdayCandidates.map(
      (engineer, index) => ({

        SelectionOrder:
          index + 1,

        ...engineer

      })
    );


  const selectedWithOrder = {

    SelectionOrder:
      orderedSaturdayCandidates.find(
        engineer =>
          normalize(
            engineer.MemberID
          ) ===
          normalize(
            selectedEngineer.MemberID
          )
      )?.SelectionOrder || 1,

    ...selectedEngineer

  };


  // ==========================================================
  // 8.7 STATE UPDATE
  // ==========================================================

  const stateUpdate = {

    Assignment_Level:
      "Level1",

    Last_Member_ID:
      selectedEngineer.MemberID,

    Last_Engineer_Name:
      selectedEngineer.EngineerName,

    Last_Assigned_At:
      currentDate &&
      currentTime
        ? `${currentDate} ${currentTime}`
        : new Date().toISOString(),

    Active:
      "Yes"

  };


  // ==========================================================
  // 8.8 SATURDAY FINAL OUTPUT
  // ==========================================================

  return [
    {
      json: {

        Status:
          "MODULE-06 OK",

        CurrentDate:
          currentDate,

        CurrentDay:
          currentDay,

        CurrentTime:
          currentTime,

        RequiredLevel:
          "Level1",

        SelectedLevel:
          "Level1",

        EscalationRequired:
          false,

        ShiftCoverageStatus:
          decision.ShiftCoverageStatus ??
          "FULL",

        ExpectedL1Count:
          decision.ExpectedL1Count ??
          0,

        ActiveL1Count:
          decision.ActiveL1Count ??
          0,

        InactiveL1Count:
          decision.InactiveL1Count ??
          0,

        L1FirstAssignmentCompletedToday:
          decision.L1FirstAssignmentCompletedToday ??
          false,

        CoverageFirstAssignment:
          false,

        CoverageEscalation:
          false,

        CoverageDecision:
          "SATURDAY_L1_ONLY_UNLIMITED",

        LastL1AssignmentDate:
          decision.LastL1AssignmentDate ??
          null,

        AssignmentMode:
          assignmentMode,

        AssignmentReady:
          true,

        FinalDecision:
          "ASSIGN",

        SelectedEngineer: {

          ...selectedWithOrder,

          // ==================================================
          // SATURDAY WORKLOAD OVERRIDE
          // ==================================================
          //
          // We intentionally report unlimited capacity for
          // Saturday.
          //
          // These fields are informational only.
          //
          CurrentTicketCount:
            number(
              selectedEngineer.CurrentTicketCount ??
              selectedEngineer.ActiveTicketCount ??
              0
            ),

          ActiveTicketCount:
            number(
              selectedEngineer.ActiveTicketCount ??
              selectedEngineer.CurrentTicketCount ??
              0
            ),

          MaxTickets:
            null,

          MaxAllowedTickets:
            null,

          AvailableCapacity:
            null,

          RemainingCapacity:
            null,

          WorkloadAvailable:
            true,

          AtCapacity:
            false,

          AtLimit:
            false,

          SaturdayUnlimited:
            true

        },

        SelectionReason:
          normalize(
            assignmentMode
          ) === "roundrobin"
            ? "SELECTED_BY_ROUND_ROBIN_SATURDAY_L1_UNLIMITED"
            : "SELECTED_BY_ASSIGNMENT_MODE_SATURDAY_L1_UNLIMITED",

        CandidateCount:
          saturdayCandidates.length,

        EligibleCandidateCount:
          eligibleSaturdayCandidates.length,

        EligibleCandidates:
          orderedSaturdayCandidates.map(
            engineer => ({

              ...engineer,

              // Informational Saturday override
              MaxTickets:
                null,

              MaxAllowedTickets:
                null,

              AvailableCapacity:
                null,

              RemainingCapacity:
                null,

              WorkloadAvailable:
                true,

              AtCapacity:
                false,

              AtLimit:
                false,

              SaturdayUnlimited:
                true

            })
          ),

        UnavailableCandidateCount:
          saturdayCandidates.length -
          eligibleSaturdayCandidates.length,

        UnavailableCandidates:
          saturdayCandidates.filter(
            engineer =>
              !eligibleSaturdayCandidates.includes(
                engineer
              )
          ),

        RequiredLevelCandidateCount:
          saturdayCandidates.length,

        SelectedLevelCandidateCount:
          eligibleSaturdayCandidates.length,

        EligibleLevel1Count:
          eligibleSaturdayCandidates.length,

        EligibleLevel2Count:
          0,

        EligibleLevel3Count:
          0,

        PreviousAssignmentState:
          previousState || {},

        StateUpdatePending:
          stateUpdate,

        ConnectWiseUpdate: {

          TicketID:
            decision.TicketID ??
            null,

          Resource: {

            MemberID:
              selectedEngineer.MemberID,

            ConnectWiseMemberID:
              selectedEngineer.ConnectWiseMemberID ??
              null,

            EngineerName:
              selectedEngineer.EngineerName

          },

          AssignmentLevel:
            "Level1"

