        WorkloadSummary: {

          MaxLevel1Tickets:
            maxLevel1,

          MaxLevel2Tickets:
            maxLevel2,

          MaxLevel3Tickets:
            maxLevel3

        },

        SaturdayRule: {

          Level1Only:
            true,

          UnlimitedTickets:
            true,

          WorkloadCheck:
            false,

          EscalationAllowed:
            false,

          CurrentTicketCountIgnored:
            true,

          MaxTicketsIgnored:
            true,

          WorkloadAvailableIgnored:
