      }
    }
  ];

}


// ============================================================
// 9. MONDAY-FRIDAY / FRIDAY S5
// ============================================================
//
// IMPORTANT:
//
// Everything below this point remains workload-controlled.
//
// Saturday logic above has NO effect here.
//
// ============================================================


// ============================================================
// 9.1 HONOR CODE-005 FINAL DECISION
// ============================================================
//
// CODE-005 is authoritative on weekdays.
//
// ============================================================

if (
  decision.AssignmentReady !== true ||
  normalize(
    decision.FinalDecision
  ) !== "assign"
) {

  return [
    {
      json: {

        Status:
          "MODULE-06 OK",

        CurrentDate:
          currentDate,

        CurrentDay:
          currentDay,

        CurrentTime:
          currentTime,

        RequiredLevel:
          decision.RequiredLevel ||
          "Level1",

        SelectedLevel:
          null,

        EscalationRequired:
          decision.EscalationRequired ??
          false,

        ShiftCoverageStatus:
          decision.ShiftCoverageStatus ??
          null,

        ExpectedL1Count:
          decision.ExpectedL1Count ??
          0,

        ActiveL1Count:
          decision.ActiveL1Count ??
          0,

        InactiveL1Count:
          decision.InactiveL1Count ??
          0,

        L1FirstAssignmentCompletedToday:
          decision.L1FirstAssignmentCompletedToday ??
          false,

        CoverageFirstAssignment:
          decision.CoverageFirstAssignment ??
          false,

        CoverageEscalation:
          decision.CoverageEscalation ??
          false,

        CoverageDecision:
          decision.CoverageDecision ??
          null,

        LastL1AssignmentDate:
          decision.LastL1AssignmentDate ??
          null,

        AssignmentMode:
          assignmentMode,

        AssignmentReady:
          false,

        FinalDecision:
          decision.FinalDecision ||
          "NO_ASSIGNMENT",

        SelectedEngineer:
          null,

        SelectionReason:
          "CODE_005_NO_ASSIGNMENT",

        CandidateCount:
          candidates.length,

        EligibleCandidateCount:
          0,

        EligibleCandidates:
          [],

        UnavailableCandidateCount:
          candidates.length,

        UnavailableCandidates:
          candidates,

        RequiredLevelCandidateCount:
          0,

        SelectedLevelCandidateCount:
          0,

        EligibleLevel1Count:
          decision.EligibleLevel1Count ??
          0,

        EligibleLevel2Count:
          decision.EligibleLevel2Count ??
          0,

        EligibleLevel3Count:
          decision.EligibleLevel3Count ??
          0,

        PreviousAssignmentState:
          {},

        StateUpdatePending:
          null,

        ConnectWiseUpdate: {

          TicketID:
            decision.TicketID ??
            null,

          Resource:
            null,

          AssignmentLevel:
            null

        },

        WorkloadSummary: {

          MaxLevel1Tickets:
            maxLevel1,

          MaxLevel2Tickets:
            maxLevel2,

          MaxLevel3Tickets:
            maxLevel3

        }

      }
    }
  ];

}


// ============================================================
// 10. DETERMINE REQUIRED LEVEL
// ============================================================

const requiredLevel =
  decision.SelectedLevel ||
  decision.EffectiveRequiredLevel ||
  decision.RequiredLevel ||
  "Level1";


// ============================================================
// 11. FILTER SELECTED LEVEL
// ============================================================

const levelCandidates =
  candidates.filter(
    engineer =>
      normalize(
        engineer.AssignmentLevel
      ) ===
      normalize(
        requiredLevel
      )
  );


// ============================================================
// 12. WEEKDAY WORKLOAD FILTER
// ============================================================
//
// IMPORTANT:
// This section is ONLY for Monday-Friday.
//
// Workload limits DO apply here.
//
// ============================================================

const eligibleCandidates =
  levelCandidates.filter(
    engineer => {

      if (
        engineer.Eligible === false
      ) {

        return false;

      }


      if (
        engineer.CurrentlyOut === true
      ) {

        return false;

      }


      if (
        engineer.WorkloadAvailable === false
      ) {

        return false;

      }


      if (
        engineer.AtCapacity === true
      ) {

        return false;

      }


      if (
        engineer.AtLimit === true
      ) {

        return false;

      }


      return true;

    }
  );


// ============================================================
// 13. NO WEEKDAY ENGINEER AVAILABLE
// ============================================================

if (
  eligibleCandidates.length === 0
) {

  return [
    {
      json: {

        Status:
          "MODULE-06 OK",

        CurrentDate:
          currentDate,

        CurrentDay:
          currentDay,

        CurrentTime:
          currentTime,

        RequiredLevel:
          requiredLevel,

        SelectedLevel:
          null,

        EscalationRequired:
          decision.EscalationRequired ??
          false,

        ShiftCoverageStatus:
          decision.ShiftCoverageStatus ??
          null,

        ExpectedL1Count:
          decision.ExpectedL1Count ??
          0,

        ActiveL1Count:
          decision.ActiveL1Count ??
          0,

        InactiveL1Count:
          decision.InactiveL1Count ??
          0,

        L1FirstAssignmentCompletedToday:
          decision.L1FirstAssignmentCompletedToday ??
          false,

        CoverageFirstAssignment:
          decision.CoverageFirstAssignment ??
          false,

        CoverageEscalation:
          decision.CoverageEscalation ??
          false,

        CoverageDecision:
          decision.CoverageDecision ??
          null,

        LastL1AssignmentDate:
          decision.LastL1AssignmentDate ??
          null,

        AssignmentMode:
          assignmentMode,

        AssignmentReady:
          false,

        FinalDecision:
          "NO_ASSIGNMENT",

        SelectedEngineer:
          null,

        SelectionReason:
          "NO_WORKLOAD_AVAILABLE_ENGINEER",

        CandidateCount:
          levelCandidates.length,

        EligibleCandidateCount:
          0,

        EligibleCandidates:
          [],

        UnavailableCandidateCount:
          levelCandidates.length,

        UnavailableCandidates:
          levelCandidates,

        RequiredLevelCandidateCount:
          levelCandidates.length,

        SelectedLevelCandidateCount:
          0,

        EligibleLevel1Count:
          decision.EligibleLevel1Count ??
          0,

        EligibleLevel2Count:
          decision.EligibleLevel2Count ??
          0,

        EligibleLevel3Count:
          decision.EligibleLevel3Count ??
          0,

        PreviousAssignmentState:
          {},

        StateUpdatePending:
          null,

        ConnectWiseUpdate: {

          TicketID:
            decision.TicketID ??
            null,

          Resource:
            null,

          AssignmentLevel:
            null

        },

        WorkloadSummary: {

          MaxLevel1Tickets:
            maxLevel1,

          MaxLevel2Tickets:
            maxLevel2,

          MaxLevel3Tickets:
            maxLevel3

        }

      }
    }
  ];

}


// ============================================================
// 14. GET PREVIOUS ASSIGNMENT STATE
// ============================================================

const previousState =
  stateRows.find(
    row =>
      normalize(
        row.Assignment_Level
      ) ===
      normalize(
        requiredLevel
      )
  ) || null;


// ============================================================
// 15. ROUND ROBIN
// ============================================================

let selectedEngineer =
  null;


if (
  normalize(
    assignmentMode
  ) === "roundrobin" &&
  eligibleCandidates.length > 1 &&
  previousState
) {

  const previousMember =
    normalize(
      previousState.Last_Member_ID
    );


  selectedEngineer =
    eligibleCandidates.find(
      engineer =>
        normalize(
          engineer.MemberID
        ) !== previousMember
    ) ||
    eligibleCandidates[0];

}
else {

  selectedEngineer =
    eligibleCandidates[0];

}


// ============================================================
// 16. SELECTION ORDER
// ============================================================

const orderedCandidates =
  eligibleCandidates.map(
    (engineer, index) => ({

      SelectionOrder:
        index + 1,

      ...engineer

    })
  );


const selectedWithOrder = {

  SelectionOrder:
    orderedCandidates.find(
      engineer =>
        normalize(
          engineer.MemberID
        ) ===
        normalize(
          selectedEngineer.MemberID
        )
    )?.SelectionOrder || 1,

  ...selectedEngineer

};


// ============================================================
// 17. STATE UPDATE
// ============================================================

const stateUpdate = {

  Assignment_Level:
    selectedEngineer.AssignmentLevel ||
    requiredLevel,

  Last_Member_ID:
    selectedEngineer.MemberID,

  Last_Engineer_Name:
    selectedEngineer.EngineerName,

  Last_Assigned_At:
    currentDate &&
    currentTime
      ? `${currentDate} ${currentTime}`
      : new Date().toISOString(),

  Active:
    "Yes"

};


// ============================================================
// 18. FINAL WEEKDAY OUTPUT
// ============================================================

return [
  {
    json: {

      Status:
        "MODULE-06 OK",

      CurrentDate:
        currentDate,

      CurrentDay:
        currentDay,

      CurrentTime:
        currentTime,

      RequiredLevel:
        decision.RequiredLevel ||
        requiredLevel,

      SelectedLevel:
        selectedEngineer.AssignmentLevel ||
        requiredLevel,

      EscalationRequired:
        decision.EscalationRequired ??
        false,

      ShiftCoverageStatus:
        decision.ShiftCoverageStatus ??
        null,

      ExpectedL1Count:
        decision.ExpectedL1Count ??
        0,

      ActiveL1Count:
        decision.ActiveL1Count ??
        0,

      InactiveL1Count:
        decision.InactiveL1Count ??
        0,

      L1FirstAssignmentCompletedToday:
        decision.L1FirstAssignmentCompletedToday ??
        false,

      CoverageFirstAssignment:
        decision.CoverageFirstAssignment ??
        false,

      CoverageEscalation:
        decision.CoverageEscalation ??
        false,

      CoverageDecision:
        decision.CoverageDecision ??
        null,

      LastL1AssignmentDate:
        decision.LastL1AssignmentDate ??
        null,

      AssignmentMode:
        assignmentMode,

      AssignmentReady:
        true,

      FinalDecision:
        "ASSIGN",

      SelectedEngineer: {

        ...selectedWithOrder,

        CurrentTicketCount:
          selectedEngineer.CurrentTicketCount ??
          selectedEngineer.ActiveTicketCount ??
          0,

        ActiveTicketCount:
          selectedEngineer.ActiveTicketCount ??
          selectedEngineer.CurrentTicketCount ??
          0,

        MaxTickets:
          selectedEngineer.MaxTickets ??
          selectedEngineer.MaxAllowedTickets ??
          getMaxTickets(
            selectedEngineer.AssignmentLevel
          ),

        MaxAllowedTickets:
          selectedEngineer.MaxAllowedTickets ??
          selectedEngineer.MaxTickets ??
          getMaxTickets(
            selectedEngineer.AssignmentLevel
          ),

        AvailableCapacity:
          selectedEngineer.AvailableCapacity ??
          selectedEngineer.RemainingCapacity ??
          Math.max(
            0,
            getMaxTickets(
              selectedEngineer.AssignmentLevel
            ) -
            number(
              selectedEngineer.CurrentTicketCount ??
              selectedEngineer.ActiveTicketCount ??
              0
            )
          ),

        RemainingCapacity:
          selectedEngineer.RemainingCapacity ??
          selectedEngineer.AvailableCapacity ??
          Math.max(
            0,
            getMaxTickets(
              selectedEngineer.AssignmentLevel
            ) -
            number(
              selectedEngineer.CurrentTicketCount ??
              selectedEngineer.ActiveTicketCount ??
              0
            )
          ),

        AtCapacity:
          selectedEngineer.AtCapacity ??
          false,

        AtLimit:
          selectedEngineer.AtLimit ??
          false,

        WorkloadAvailable:
          selectedEngineer.WorkloadAvailable ??
          true

      },

      SelectionReason:
        normalize(
          assignmentMode
        ) === "roundrobin"
          ? "SELECTED_BY_ROUND_ROBIN"
          : "SELECTED_BY_ASSIGNMENT_MODE",

      CandidateCount:
        levelCandidates.length,

      EligibleCandidateCount:
        eligibleCandidates.length,

      EligibleCandidates:
        orderedCandidates,

      UnavailableCandidateCount:
        levelCandidates.length -
        eligibleCandidates.length,

      UnavailableCandidates:
        levelCandidates.filter(
          engineer =>
            !eligibleCandidates.includes(
              engineer
            )
        ),

      RequiredLevelCandidateCount:
        levelCandidates.length,

      SelectedLevelCandidateCount:
        eligibleCandidates.length,

      EligibleLevel1Count:
        decision.EligibleLevel1Count ??
        0,

      EligibleLevel2Count:
        decision.EligibleLevel2Count ??
        0,

      EligibleLevel3Count:
        decision.EligibleLevel3Count ??
        0,

      PreviousAssignmentState:
        previousState || {},

      StateUpdatePending:
        stateUpdate,

      ConnectWiseUpdate: {

        TicketID:
          decision.TicketID ??
          null,

        Resource: {

          MemberID:
            selectedEngineer.MemberID,

          ConnectWiseMemberID:
            selectedEngineer.ConnectWiseMemberID ??
            null,

          EngineerName:
            selectedEngineer.EngineerName

        },

        AssignmentLevel:
          selectedEngineer.AssignmentLevel ||
          requiredLevel

      },

      WorkloadSummary: {

        MaxLevel1Tickets:
          maxLevel1,

        MaxLevel2Tickets:
          maxLevel2,

        MaxLevel3Tickets:
          maxLevel3

      },

      SaturdayRule:
        null

    }
  }
];

// ============================================================
// CODE-007 – Build Assignment
// MODULE 07 – FINAL ASSIGNMENT PACKAGE
//
// PURPOSE:
//   1. Read MODULE-06 assignment decision
//   2. Read ConnectWise ticket from Merge2
//   3. Resolve ConnectWise numeric Member ID
//   4. Build final assignment package for CW-004
//
// IMPORTANT:
//   Merge2 MUST use:
//      Mode = Append
//
//   Merge2 expected items:
//      Item 1 = MODULE-06
//      Item 2 = ConnectWise ticket
//
//   This node DOES NOT update ConnectWise.
//   CW-004 performs the actual assignment.
//
// ============================================================


// ============================================================
// 1. READ MERGE2 INPUT
// ============================================================

const items = $input.all();

if (!items || items.length === 0) {
  throw new Error(
    "CODE-007: No input items received from Merge2."
  );
}


// ============================================================
// 2. CONNECTWISE MEMBER ID MAP
// ============================================================
//
// MemberID -> ConnectWise numeric member ID
//
// ============================================================

const CONNECTWISE_MEMBER_MAP = {

  // ----------------------------------------------------------
  // LEVEL 1
  // ----------------------------------------------------------

  "krunal.more": 200,
  "vishal.santoki": 202,


  // ----------------------------------------------------------
  // LEVEL 2
  // ----------------------------------------------------------

  "dhaval.shah": 175,
  "hardik.parekh": 219,
  "SCKothari": 199,
  "shreyans.kothari": 199,
  "nagendra.singh": 218,


  // ----------------------------------------------------------
  // LEVEL 3
  // ----------------------------------------------------------

  "gunesh.malviya": 185,
  "amrish.patel": 154,
  "parth.patel": 228,
  "heta.shah": 170,
  "hemang.vyas": 173

};


// ============================================================
// 3. HELPER FUNCTIONS
// ============================================================

function isObject(value) {

  return (
    value !== null &&
    typeof value === "object"
  );

}


// ------------------------------------------------------------
// FIRST DEFINED
// ------------------------------------------------------------

function firstDefined(...values) {

  for (const value of values) {

    if (
      value !== undefined &&
      value !== null &&
      value !== ""
    ) {

      return value;

    }

  }

  return undefined;

}


// ------------------------------------------------------------
// CLEAN STRING
// ------------------------------------------------------------

function clean(value) {

  if (
    value === undefined ||
    value === null
  ) {

    return "";

  }

  return String(value).trim();

}


// ------------------------------------------------------------
// PARSE JSON STRING IF NECESSARY
// ------------------------------------------------------------

function parsePossibleJSON(value) {

  if (typeof value !== "string") {
    return value;
  }

  const trimmed =
    value.trim();

  if (!trimmed) {
    return value;
  }

  if (
    !(
      trimmed.startsWith("{") ||
      trimmed.startsWith("[")
    )
  ) {

    return value;

  }

  try {

    return JSON.parse(trimmed);

  } catch {

    return value;

  }

}


// ============================================================
// 4. IDENTIFY MODULE-06
// ============================================================

function isModule06Object(data) {

  if (!isObject(data)) {
    return false;
  }

  if (
    data.Status === "MODULE-06 OK"
  ) {

    return true;

  }

  return Boolean(
    data.SelectedEngineer &&
    (
      data.AssignmentReady !== undefined ||
      data.RequiredLevel !== undefined ||
      data.SelectedLevel !== undefined
    )
  );

}


// ============================================================
// 5. EXTRACT MODULE-06
// ============================================================

let selection = null;

for (const item of items) {

  const data =
    item?.json || {};

  if (
    isModule06Object(data)
  ) {

    selection = data;

    break;

  }

}


if (!selection) {

  throw new Error(
    "CODE-007: MODULE-06 assignment result was not found in Merge2."
  );

}


// ============================================================
// 6. VALIDATE MODULE-06
// ============================================================

if (
  selection.Status !== "MODULE-06 OK"
) {

  throw new Error(
    "CODE-007: Expected MODULE-06 OK but received: " +
    String(
      selection.Status || "UNKNOWN"
    )
  );

}


const assignmentReady =
  selection.AssignmentReady === true;


// ============================================================
// 6A. NO ASSIGNMENT IS A VALID BUSINESS OUTCOME
// ============================================================
//
// Examples:
//
//   SATURDAY_L1_CAPACITY_EXHAUSTED
//   SUNDAY_NO_ASSIGNMENT
//   NO_ELIGIBLE_ENGINEER
//
// These are NOT technical errors.
//
// CODE-007 must return a controlled result so downstream
// logic can decide whether ConnectWise should be updated.
//
// ============================================================

if (!assignmentReady) {

  return [
    {
      json: {

        Status:
          "MODULE-07 OK",

        AssignmentReady:
          false,

        FinalDecision:
          selection.FinalDecision ??
          "NO_ASSIGNMENT",

        SelectionReason:
          selection.SelectionReason ??
          "MODULE_06_NO_ASSIGNMENT",

        RequiredLevel:
          selection.RequiredLevel ??
          null,

        SelectedLevel:
          selection.SelectedLevel ??
          null,

        EscalationRequired:
          selection.EscalationRequired ??
          false,

        AssignmentMode:
          selection.AssignmentMode ??
          null,

        ShiftCoverageStatus:
          selection.ShiftCoverageStatus ??
          null,

        ExpectedL1Count:
          selection.ExpectedL1Count ??
          0,

        ActiveL1Count:
          selection.ActiveL1Count ??
          0,

        InactiveL1Count:
          selection.InactiveL1Count ??
          0,

        CoverageFirstAssignment:
          selection.CoverageFirstAssignment ??
          false,

        CoverageEscalation:
          selection.CoverageEscalation ??
          false,

        CoverageDecision:
          selection.CoverageDecision ??
          null,

        SelectedEngineer:
          null,

        ConnectWiseUpdate: {

          TicketID:
            null,

          Resource:
            null,

          AssignmentLevel:
            null

        },

        Assignment:
          null,

        TicketFlags:
          null,

        Debug: {

          Reason:
            "MODULE-06 returned AssignmentReady=false",

          Module06FinalDecision:
            selection.FinalDecision ??
            null,

          Module06SelectionReason:
            selection.SelectionReason ??
            null,

          CandidateCount:
            selection.CandidateCount ??
            0,

          EligibleCandidateCount:
            selection.EligibleCandidateCount ??
            0,

          UnavailableCandidateCount:
            selection.UnavailableCandidateCount ??
            0,

          SelectedEngineer:
            null

        },

        ProcessedAt:
          new Date().toISOString()

      }
    }
  ];

}


// ============================================================
// 7. GET SELECTED ENGINEER
// ============================================================

const engineer =
  selection.SelectedEngineer;


if (
  !engineer ||
  !isObject(engineer)
) {

  throw new Error(
    "CODE-007: SelectedEngineer object is missing from MODULE-06."
  );

}


// ============================================================
// 8. ENGINEER INFORMATION
// ============================================================

const engineerName =
  clean(
    firstDefined(
      engineer.EngineerName,
      engineer.engineerName,
      engineer.Name,
      engineer.name
    )
  );


const memberID =
  clean(
    firstDefined(
      engineer.MemberID,
      engineer.memberID,
      engineer.MemberId,
      engineer.memberId
    )
  );


const assignmentLevel =
  firstDefined(
    engineer.AssignmentLevel,
    engineer.assignmentLevel,
    selection.SelectedLevel,
    selection.RequiredLevel,
    null
  );


const shiftID =
  firstDefined(
    engineer.ShiftID,
    engineer.shiftID,
    null
  );


const shiftName =
  firstDefined(
    engineer.ShiftName,
    engineer.shiftName,
    null
  );


const shiftDay =
  firstDefined(
    engineer.ShiftDay,
    engineer.shiftDay,
    null
  );


const shiftStart =
  firstDefined(
    engineer.ShiftStart,
    engineer.shiftStart,
    null
  );


const shiftEnd =
  firstDefined(
    engineer.ShiftEnd,
    engineer.shiftEnd,
    null
  );


const shiftCurrentlyActive =
  firstDefined(
    engineer.ShiftCurrentlyActive,
    engineer.shiftCurrentlyActive,
    null
  );


const activeTicketCount =
  Number(
    firstDefined(
      engineer.ActiveTicketCount,
      engineer.activeTicketCount,
      0
    )
  );


const maxAllowedTickets =
  firstDefined(
    engineer.MaxAllowedTickets,
    engineer.maxAllowedTickets,
    null
  );


const remainingCapacity =
  firstDefined(
    engineer.RemainingCapacity,
    engineer.remainingCapacity,
    null
  );


const workloadAvailable =
  firstDefined(
    engineer.WorkloadAvailable,
    engineer.workloadAvailable,
    false
  );


// ============================================================
// 9. VALIDATE ENGINEER
// ============================================================

if (!engineerName) {

  throw new Error(
    "CODE-007: Selected engineer name is missing."
  );

}


if (!memberID) {

  throw new Error(
    "CODE-007: Selected engineer MemberID is missing."
  );

}


// ============================================================
// 10. RESOLVE CONNECTWISE MEMBER ID
// ============================================================

let connectWiseMemberID =
  CONNECTWISE_MEMBER_MAP[memberID];


// Case-insensitive fallback

if (
  connectWiseMemberID === undefined
) {

  const normalizedMemberID =
    memberID.toLowerCase();

  const mapKey =
    Object.keys(
      CONNECTWISE_MEMBER_MAP
    ).find(
      key =>
        key.toLowerCase() ===
        normalizedMemberID
    );

  if (mapKey) {

    connectWiseMemberID =
      CONNECTWISE_MEMBER_MAP[mapKey];

  }

}


if (
  connectWiseMemberID === undefined ||
  connectWiseMemberID === null
) {

  throw new Error(
    "CODE-007: No ConnectWise numeric Member ID mapping exists " +
    `for "${memberID}" (${engineerName}).`
  );

}


// ============================================================
// 11. TICKET DETECTION
// ============================================================
//
// With Merge2 = Append:
//
//   Item 1 = MODULE-06
//   Item 2 = ConnectWise ticket
//
// We intentionally search every non-MODULE-06 item.
//
// ============================================================

function hasExplicitTicketID(data) {

  if (!isObject(data)) {
    return false;
  }

  const id =
    firstDefined(
      data.TicketID,
      data.ticketID,
      data.TicketId,
      data.ticketId,
      data.ticket_id
    );

  return (
    id !== undefined &&
    id !== null &&
    id !== ""
  );

}


// ============================================================
// 12. LOOKS LIKE CONNECTWISE TICKET
// ============================================================

function looksLikeTicketObject(data) {

  if (!isObject(data)) {
    return false;
  }


  // Never treat MODULE-06 as ticket

  if (
    isModule06Object(data)
  ) {

    return false;

  }


  // Explicit TicketID

  if (
    hasExplicitTicketID(data)
  ) {

    return true;

  }


  // ConnectWise standard ticket object

  const id =
    firstDefined(
      data.id,
      data.ID,
      data.Id
    );


  if (
    id !== undefined &&
    id !== null &&
    id !== ""
  ) {

    if (
      data.summary !== undefined ||
      data.subject !== undefined ||
      data.status !== undefined ||
      data.board !== undefined ||
      data.company !== undefined ||
      data.recordType !== undefined ||
      data.record_type !== undefined ||
      data.type !== undefined
    ) {

      return true;

    }

  }


  return false;

}


// ============================================================
// 13. RECURSIVELY FIND TICKET
// ============================================================

function findTicket(
  value,
  path = "root",
  visited = new Set()
) {

  if (
    value === null ||
    value === undefined
  ) {

    return null;

  }


  // Parse JSON string if possible

  value =
    parsePossibleJSON(value);


  if (
    value === null ||
    value === undefined
  ) {

    return null;

  }


  // Primitive

  if (
    typeof value !== "object"
  ) {

    return null;

  }


  // Prevent circular reference

  if (
    visited.has(value)
  ) {

    return null;

  }

  visited.add(value);


  // ----------------------------------------------------------
  // ARRAY
  // ----------------------------------------------------------

  if (
    Array.isArray(value)
  ) {

    for (
      let i = 0;
      i < value.length;
      i++
    ) {

      const result =
        findTicket(
          value[i],
          `${path}[${i}]`,
          visited
        );

      if (result) {

        return result;

      }

    }

    return null;

  }


  // ----------------------------------------------------------
  // CURRENT OBJECT
  // ----------------------------------------------------------

  if (
    looksLikeTicketObject(value)
  ) {

    return {

      ticket:
        value,

      path:
        path

    };

  }


  // ----------------------------------------------------------
  // SEARCH NESTED OBJECTS
  // ----------------------------------------------------------

  for (
    const key of Object.keys(value)
  ) {

    const child =
      value[key];


    if (
      child === null ||
      child === undefined
    ) {

      continue;

    }


    const parsedChild =
      parsePossibleJSON(child);


    if (
      parsedChild === null ||
      parsedChild === undefined
    ) {

      continue;

    }


    if (
      typeof parsedChild !== "object"
    ) {

      continue;

    }


    const result =
      findTicket(
        parsedChild,
        `${path}.${key}`,
        visited
      );


    if (result) {

      return result;

    }

  }


  return null;

}


// ============================================================
// 14. FIND CONNECTWISE TICKET
// ============================================================

let ticket = null;

let ticketPath = null;


// ------------------------------------------------------------
// FIRST PASS:
// Search every non-MODULE-06 item
// ------------------------------------------------------------

for (
  let i = 0;
  i < items.length;
  i++
) {

  const rawData =
    items[i]?.json;


  if (!rawData) {
    continue;
  }


  if (
    isModule06Object(rawData)
  ) {

    continue;

  }


  const result =
    findTicket(
      rawData,
      `Merge2 Item ${i + 1}`
    );


  if (result) {

    ticket =
      result.ticket;

    ticketPath =
      result.path;

    break;

  }

}


// ============================================================
// 15. FALLBACK:
// IF THERE IS EXACTLY ONE NON-MODULE-06 ITEM,
// TREAT IT AS THE TICKET SOURCE
//
// This is specifically for Merge2 = Append.
// ============================================================

if (!ticket) {

  const nonSelectionItems =
    items.filter(
      item =>
        !isModule06Object(
          item?.json || {}
        )
    );


  if (
    nonSelectionItems.length === 1
  ) {

    let fallbackData =
      nonSelectionItems[0].json;


    fallbackData =
      parsePossibleJSON(
        fallbackData
      );


    const fallbackResult =
      findTicket(
        fallbackData,
        "Merge2 Ticket Item"
      );


    if (fallbackResult) {

      ticket =
        fallbackResult.ticket;

      ticketPath =
        fallbackResult.path;

    }

  }

}


// ============================================================
// 16. TICKET NOT FOUND
// ============================================================

if (!ticket) {

  const diagnostic =
    items.map(
      (item, index) => {

        const data =
          item?.json || {};

        return {

          ItemNumber:
            index + 1,

          IsModule06:
            isModule06Object(data),

          TopLevelKeys:
            isObject(data)
              ? Object.keys(data)
              : [],

          TopLevelData:
            data

        };

      }
    );


  throw new Error(
    "CODE-007: No ConnectWise ticket could be identified " +
    "in Merge2 input.\n\n" +

    "IMPORTANT:\n" +
    "Merge2 must use Mode = Append and must contain:\n" +
    "1. MODULE-06 assignment result\n" +
    "2. ConnectWise ticket result\n\n" +

    "MERGE2 DIAGNOSTIC:\n" +

    JSON.stringify(
      diagnostic,
      null,
      2
    )
  );

}


// ============================================================
// 17. GET TICKET ID
// ============================================================

const ticketID =
  firstDefined(
    ticket.TicketID,
    ticket.ticketID,
    ticket.TicketId,
    ticket.ticketId,
    ticket.ticket_id,
    ticket.id,
    ticket.ID,
    ticket.Id
  );


if (
  ticketID === undefined ||
  ticketID === null ||
  ticketID === ""
) {

  throw new Error(
    "CODE-007: ConnectWise ticket was found at " +
    `${ticketPath}, but TicketID could not be determined.`
  );

}


// ============================================================
// 18. TICKET DETAILS
// ============================================================

const ticketSummary =
  firstDefined(
    ticket.TicketSummary,
    ticket.summary,
    ticket.Summary,
    ticket.subject,
    ticket.Subject,
    ""
  );


const recordType =
  firstDefined(
    ticket.RecordType,
    ticket.recordType,
    ticket.record_type,
    ""
  );


const board =
  firstDefined(
    ticket.Board,

    typeof ticket.board === "object"
      ? ticket.board?.name
      : ticket.board,

    ticket.boardName,

    ""
  );


const currentStatus =
  firstDefined(
    ticket.CurrentStatus,

    typeof ticket.status === "object"
      ? ticket.status?.name
      : ticket.status,

    ticket.StatusName,

    ""
  );


// ============================================================
// 19. COMPANY INFORMATION
// ============================================================

const companyName =
  firstDefined(
    ticket.Company,

    typeof ticket.company === "object"
      ? ticket.company?.name
      : ticket.company,

    ticket.CompanyName,

    ""
  );


const companyID =
  firstDefined(
    ticket.CompanyID,

    typeof ticket.company === "object"
      ? ticket.company?.id
      : undefined,

    ticket.companyId,

    null
  );


// ============================================================
// 20. CHILD TICKET FLAGS
// ============================================================

const hasChildTicket =
  Boolean(
    firstDefined(
      ticket.HasChildTicket,
      ticket.hasChildTicket,
      false
    )
  );


const hasMergedChildTicket =
  Boolean(
    firstDefined(
      ticket.HasMergedChildTicket,
      ticket.hasMergedChildTicketFlag,
      ticket.hasMergedChildTicket,
      false
    )
  );


const parentTicketID =
  firstDefined(
    ticket.parentTicketId,
    ticket.ParentTicketID,
    ticket.parentTicketID,
    null
  );


// ============================================================
// 21. BUILD SELECTED ENGINEER
// ============================================================

const selectedEngineer = {

  SelectionOrder:
    firstDefined(
      engineer.SelectionOrder,
      engineer.selectionOrder,
      null
    ),

  EngineerName:
    engineerName,

  MemberID:
    memberID,

  ConnectWiseMemberID:
    connectWiseMemberID,

  AssignmentLevel:
    assignmentLevel,

  ShiftID:
    shiftID,

  ShiftName:
    shiftName,

  ShiftDay:
    shiftDay,

  ShiftStart:
    shiftStart,

  ShiftEnd:
    shiftEnd,

  ShiftCurrentlyActive:
    shiftCurrentlyActive,

  RosterAvailable:
    firstDefined(
      engineer.RosterAvailable,
      true
    ),

  ConnectWiseRecordFound:
    firstDefined(
      engineer.ConnectWiseRecordFound,
      false
    ),

  CurrentlyOut:
    firstDefined(
      engineer.CurrentlyOut,
      false
    ),

  LiveAvailability:
    firstDefined(
      engineer.LiveAvailability,
      null
    ),

  ActiveTicketCount:
    activeTicketCount,

  MaxAllowedTickets:
    maxAllowedTickets,

  RemainingCapacity:
    remainingCapacity,

  WorkloadAvailable:
    workloadAvailable,

  Eligible:
    firstDefined(
      engineer.Eligible,
      true
    )

};


// ============================================================
// 22. BUILD CONNECTWISE UPDATE
// ============================================================

const connectWiseUpdate = {

  TicketID:
    ticketID,

  Resource: {

    MemberID:
      memberID,

    ConnectWiseMemberID:
      connectWiseMemberID,

    EngineerName:
      engineerName

  },

  AssignmentLevel:
    assignmentLevel

};


// ============================================================
// 23. BUILD FINAL ASSIGNMENT OBJECT
// ============================================================

const assignment = {

  TicketID:
    ticketID,

  TicketSummary:
    ticketSummary,

  RecordType:
    recordType,

  Board:
    board,

  CurrentStatus:
    currentStatus,

  Company:
    companyName,

  CompanyID:
    companyID,

  RequiredLevel:
    selection.RequiredLevel ??
    null,

  SelectedLevel:
    selection.SelectedLevel ??
    assignmentLevel,

  EscalationRequired:
    selection.EscalationRequired ??
    false,

  ShiftCoverageStatus:
    selection.ShiftCoverageStatus ??
    null,

  CoverageFirstAssignment:
    selection.CoverageFirstAssignment ??
    false,

  CoverageEscalation:
    selection.CoverageEscalation ??
    false,

  CoverageDecision:
    selection.CoverageDecision ??
    null,

  AssignmentMode:
    selection.AssignmentMode ??
    null,

  SelectedEngineer:
    selectedEngineer,

  TicketFlags: {

    HasChildTicket:
      hasChildTicket,

    HasMergedChildTicket:
      hasMergedChildTicket,

    ParentTicketID:
      parentTicketID

  }

};


// ============================================================
// 24. FINAL MODULE-07 OUTPUT
// ============================================================

return [

  {

    json: {

      Status:
        "MODULE-07 OK",

      AssignmentReady:
        true,


      // ------------------------------------------------------
      // TICKET
      // ------------------------------------------------------

      TicketID:
        ticketID,

      TicketSummary:
        ticketSummary,

      RecordType:
        recordType,

      Board:
        board,

      CurrentStatus:
        currentStatus,

      Company:
        companyName,

      CompanyID:
        companyID,


      // ------------------------------------------------------
      // ASSIGNMENT
      // ------------------------------------------------------

      RequiredLevel:
        selection.RequiredLevel ??
        null,

      SelectedLevel:
        selection.SelectedLevel ??
        assignmentLevel,

      EscalationRequired:
        selection.EscalationRequired ??
        false,

      ShiftCoverageStatus:
        selection.ShiftCoverageStatus ??
        null,

      ExpectedL1Count:
        selection.ExpectedL1Count ??
        null,

      ActiveL1Count:
        selection.ActiveL1Count ??
        null,

      InactiveL1Count:
        selection.InactiveL1Count ??
        null,

      CoverageFirstAssignment:
        selection.CoverageFirstAssignment ??
        false,

      CoverageEscalation:
        selection.CoverageEscalation ??
        false,

      CoverageDecision:
        selection.CoverageDecision ??
        null,

      AssignmentMode:
        selection.AssignmentMode ??
        null,


      // ------------------------------------------------------
      // ENGINEER
      // ------------------------------------------------------

      SelectedEngineer:
        selectedEngineer,


      // ------------------------------------------------------
      // TICKET FLAGS
      // ------------------------------------------------------

      TicketFlags: {

        HasChildTicket:
          hasChildTicket,

        HasMergedChildTicket:
          hasMergedChildTicket,

        ParentTicketID:
          parentTicketID

      },


      // ------------------------------------------------------
      // FINAL ASSIGNMENT OBJECT
      // ------------------------------------------------------

      Assignment:
        assignment,


      // ------------------------------------------------------
      // CONNECTWISE UPDATE
      // ------------------------------------------------------

      ConnectWiseUpdate:
        connectWiseUpdate,


      // ------------------------------------------------------
      // DEBUG
      // ------------------------------------------------------

      Debug: {

        TicketFoundAt:
          ticketPath,

        Merge2ItemCount:
          items.length,

        Merge2ModeExpected:
          "Append",

        SelectedEngineer:
          engineerName,

        SelectedMemberID:
          memberID,

        ConnectWiseMemberID:
          connectWiseMemberID,

        SelectedLevel:
          assignmentLevel,

        EscalationRequired:
          Boolean(
            selection.EscalationRequired
          )

      },


      ProcessedAt:
        new Date().toISOString()

    }

  }

];

