parameters.jsCode:
// ============================================================
// CODE-010 – Prepare Assignment State
// ============================================================
// Purpose:
// Prepare the state row for Google Sheets.
//
// IMPORTANT:
// Scheduling has been removed from this flow.
//
// CW-007 provides the engineer that was selected/assigned.
// CODE-002 provides the Assignment Level.
//
// This node does NOT:
// - Read schedules
// - Update schedules
// - Check overlaps
// - Depend on schedule IDs
// ============================================================


// ------------------------------------------------------------
// 1. Get engineer from current input
// ------------------------------------------------------------
//
// Current input:
// CW-007 – Get Engineer Member
//
// Example:
// {
//   "id": 219,
//   "identifier": "hardik.parekh",
//   "firstName": "Hardik",
//   "lastName": "Parekh"
// }
//
// ------------------------------------------------------------

const engineer = $input.first().json;


// ------------------------------------------------------------
// 2. Extract ConnectWise engineer information
// ------------------------------------------------------------

const memberID =
  engineer.identifier ??
  engineer.memberIdentifier ??
  null;

const connectWiseMemberNumericId =
  engineer.id ??
  null;

const engineerName =
  engineer.name ??
  [
    engineer.firstName,
    engineer.middleInitial,
    engineer.lastName
  ]
    .filter(Boolean)
    .join(' ');


// ------------------------------------------------------------
// 3. Validate engineer
// ------------------------------------------------------------

if (!memberID) {
  throw new Error(
    'CODE-010 ERROR: CW-007 output does not contain engineer identifier.'
  );
}


// ------------------------------------------------------------
// 4. Get Assignment Engine output
// ------------------------------------------------------------

const assignmentEngine =
  $('CODE-002A - Assignment Engine').first().json;


// ------------------------------------------------------------
// 5. Get planned engineers
// ------------------------------------------------------------

const plannedEngineers =
  Array.isArray(assignmentEngine.PlannedEngineers)
    ? assignmentEngine.PlannedEngineers
    : [];


// ------------------------------------------------------------
// 6. Find the assigned engineer in Assignment Engine
// ------------------------------------------------------------
//
// We do NOT look for Selected/Assigned flags.
//
// Instead, we match the engineer returned by CW-007
// against CODE-002 PlannedEngineers.
//
// ------------------------------------------------------------

const assignedEngineer =
  plannedEngineers.find(engineer =>
    String(engineer.MemberID ?? '')
      .trim()
      .toLowerCase() ===
    String(memberID)
      .trim()
      .toLowerCase()
  );


// ------------------------------------------------------------
// 7. Validate engineer exists in Assignment Engine
// ------------------------------------------------------------

if (!assignedEngineer) {

  throw new Error(
    `CODE-010 ERROR: Engineer "${memberID}" ` +
    `was not found in CODE-002 PlannedEngineers.`
  );
}


// ------------------------------------------------------------
// 8. Determine Assignment Level
// ------------------------------------------------------------

const assignmentLevel =
  assignedEngineer.AssignmentLevel ??
  null;


if (!assignmentLevel) {

  throw new Error(
    `CODE-010 ERROR: Assignment level not found for "${memberID}".`
  );
}


// ------------------------------------------------------------
// 9. Assignment timestamp
// ------------------------------------------------------------

const lastAssignedAt =
  new Date().toISOString();


// ------------------------------------------------------------
// 10. Prepare Google Sheets state row
// ------------------------------------------------------------

return [
  {
    json: {

      Status:
        'ASSIGNMENT-STATE UPDATE READY',

      Assignment_Level:
        assignmentLevel,

      Last_Member_ID:
        memberID,

      Last_Engineer_Name:
        engineerName || assignedEngineer.EngineerName || null,

      Last_Assigned_At:
        lastAssignedAt,

      Active:
        'Yes',

      ConnectWiseMemberID:
        connectWiseMemberNumericId
    }
  }
];

// ============================================================
// CFG-001 – Build Workflow Configuration
// ============================================================
// Source:
// Google Sheets → Get row(s) in sheet
//
// Purpose:
// Convert configuration rows into ONE normalized
// WorkflowConfig object for downstream workflow nodes.
// ============================================================

const rows = $input.all();

const config = {};

// ------------------------------------------------------------
// 1. READ CONFIGURATION ROWS
// ------------------------------------------------------------

for (const item of rows) {
  const key = String(item.json.Key ?? '').trim();

  if (!key) continue;

  config[key] = item.json.Value;
}

// ------------------------------------------------------------
// 2. NORMALIZE NUMERIC SETTINGS
// ------------------------------------------------------------

const maxLevel1Tickets = Number(config.MaxLevel1Tickets);
const maxLevel2Tickets = Number(config.MaxLevel2Tickets);
const maxLevel3Tickets = Number(config.MaxLevel3Tickets);

if (!Number.isFinite(maxLevel1Tickets)) {
  throw new Error(
    `MaxLevel1Tickets is missing or invalid. Received: ${config.MaxLevel1Tickets}`
  );
}

if (!Number.isFinite(maxLevel2Tickets)) {
  throw new Error(
    `MaxLevel2Tickets is missing or invalid. Received: ${config.MaxLevel2Tickets}`
  );
}

if (!Number.isFinite(maxLevel3Tickets)) {
  throw new Error(
    `MaxLevel3Tickets is missing or invalid. Received: ${config.MaxLevel3Tickets}`
  );
}

// ------------------------------------------------------------
// 3. NORMALIZE BOOLEAN SETTINGS
// ------------------------------------------------------------
// Supports:
// true / false
// "true" / "false"
// yes / no
// "yes" / "no"
// 1 / 0
// ------------------------------------------------------------

function toBoolean(value, defaultValue = false) {
  if (typeof value === 'boolean') {
    return value;
  }

  const normalized = String(value ?? '')
    .trim()
    .toLowerCase();

  if (['true', 'yes', '1'].includes(normalized)) {
    return true;
  }

  if (['false', 'no', '0'].includes(normalized)) {
    return false;
  }

  return defaultValue;
}

const enableLevel3 =
  toBoolean(config.EnableLevel3);

const checkInOutBoard =
  toBoolean(config.CheckInOutBoard);

const checkCurrentShift =
  toBoolean(config.CheckCurrentShift);

const useSkillRouting =
  toBoolean(config.UseSkillRouting);

// ------------------------------------------------------------
// 4. NORMALIZE WORKLOAD STATUSES
// ------------------------------------------------------------

const workloadStatusesRaw =
  String(config.WorkloadStatuses ?? '').trim();

const workloadStatuses = workloadStatusesRaw
  .split(',')
  .map(status => status.trim())
  .filter(Boolean);

// ------------------------------------------------------------
// 5. BUILD FINAL WORKFLOW CONFIG
// ------------------------------------------------------------

const WorkflowConfig = {
  Company: String(config.Company ?? '').trim(),

  Board: String(config.Board ?? '').trim(),

  TimeZone:
    String(config.TimeZone ?? 'Asia/Kolkata').trim(),

  MaxLevel1Tickets: maxLevel1Tickets,

  MaxLevel2Tickets: maxLevel2Tickets,

  MaxLevel3Tickets: maxLevel3Tickets,

  EnableLevel3: enableLevel3,

  CheckInOutBoard: checkInOutBoard,

  CheckCurrentShift: checkCurrentShift,

  UseSkillRouting: useSkillRouting,

  WorkloadStatusesRaw: workloadStatusesRaw,

  WorkloadStatuses: workloadStatuses
};

// ------------------------------------------------------------
// 6. VALIDATION
// ------------------------------------------------------------

if (!WorkflowConfig.Company) {
  throw new Error('Company is missing in configuration.');
}

if (!WorkflowConfig.Board) {
  throw new Error('Board is missing in configuration.');
}

if (!WorkflowConfig.WorkloadStatuses.length) {
  throw new Error(
    'WorkloadStatuses is missing or empty in configuration.'
  );
}

// ------------------------------------------------------------
// 7. OUTPUT
// ------------------------------------------------------------

return [
  {
    json: {
      Status: 'CFG-001 OK',

      WorkflowConfig
    }
  }
];

// ============================================================
// CODE-002 - ASSIGNMENT ENGINE
// MODULE 02 - PLANNED ENGINEER SELECTION
//
// Purpose:
//   Read CODE-001 context
//   Identify today's planned engineers
//   Apply SupportCalendar + WeeklyRoster rules
//
// CURRENT STAGE:
//   - Planned engineer selection
//
// NOT INCLUDED YET:
//   - ConnectWise In/Out
//   - Live availability
//   - Escalation
//   - Round Robin selection
//   - Ticket update
//
// IMPORTANT:
//   CODE-001 is the authoritative source for:
//     - CurrentDate
//     - CurrentDay
//     - CurrentTime
//     - Timezone
//
//   These values are read from:
//     ctx.WorkflowContext
//
//   Do NOT calculate the date/day independently here.
// ============================================================


// ------------------------------------------------------------
// 1. READ CODE-001 CONTEXT
// ------------------------------------------------------------

const ctx =
  $('CODE-001 - Build Context').first().json;


// ------------------------------------------------------------
// 2. BASIC CONTEXT VALIDATION
// ------------------------------------------------------------

if (!ctx || typeof ctx !== "object") {
  throw new Error(
    "CODE-002: CODE-001 context is missing or invalid."
  );
}


// ------------------------------------------------------------
// 3. READ WORKFLOW CONTEXT
//
// CODE-001 structure:
//
// WorkflowContext: {
//   Timezone,
//   CurrentDate,
//   CurrentDay,
//   CurrentTime
// }
//
// IMPORTANT:
// Do NOT use ctx.CurrentDate.
// Do NOT use ctx.CurrentDay.
// Do NOT use ctx.CurrentTime.
//
// They are inside ctx.WorkflowContext.
// ------------------------------------------------------------

const WorkflowContext =
  ctx.WorkflowContext;


if (
  !WorkflowContext ||
  typeof WorkflowContext !== "object"
) {
  throw new Error(
    "CODE-002: WorkflowContext is missing from CODE-001."
  );
}


// ------------------------------------------------------------
// 4. NORMALIZATION HELPERS
// ------------------------------------------------------------

function clean(value) {
  return String(value ?? "").trim();
}


function lower(value) {
  return clean(value).toLowerCase();
}


// ------------------------------------------------------------
// 5. READ AUTHORITATIVE DATE / TIME
//
// CODE-001 is responsible for determining the actual
// India date/time.
//
// Example:
//
// CurrentDate = 2026-08-11
// CurrentDay  = Tuesday
// CurrentTime = 13:15
// Timezone    = Asia/Kolkata
// ------------------------------------------------------------

const CurrentDate =
  clean(WorkflowContext.CurrentDate);

const CurrentDay =
  clean(WorkflowContext.CurrentDay);

const CurrentTime =
  clean(WorkflowContext.CurrentTime);

const TimeZone =
  clean(WorkflowContext.Timezone);


// ------------------------------------------------------------
// 6. VALIDATE DATE / TIME
// ------------------------------------------------------------

if (!CurrentDate) {
  throw new Error(
    "CODE-002: WorkflowContext.CurrentDate is missing from CODE-001."
  );
}


if (!CurrentDay) {
  throw new Error(
    "CODE-002: WorkflowContext.CurrentDay is missing from CODE-001."
  );
}


if (!CurrentTime) {
  throw new Error(
    "CODE-002: WorkflowContext.CurrentTime is missing from CODE-001."
  );
}


// ------------------------------------------------------------
// 7. TEST MODE
//
// CODE-001 may optionally provide TestMode.
//
// If it is not present, default to false.
//
// IMPORTANT:
// There is NO TEST_DATE in CODE-002.
//
// CODE-001 controls the date/time.
// ------------------------------------------------------------

const TestMode =
  WorkflowContext.TestMode === true;


// ------------------------------------------------------------
// 8. NORMALIZE INPUT DATA
//
// CODE-001 uses these exact property names:
//
//   EngineerMaster
//   WeeklyRoster
//   SupportCalendar
// ------------------------------------------------------------

const SupportCalendar =
  Array.isArray(ctx.SupportCalendar)
    ? ctx.SupportCalendar
    : [];


const Roster =
  Array.isArray(ctx.WeeklyRoster)
    ? ctx.WeeklyRoster
    : [];


const Engineers =
  Array.isArray(ctx.EngineerMaster)
    ? ctx.EngineerMaster
    : [];


// ------------------------------------------------------------
// 9. BASIC VALIDATION
// ------------------------------------------------------------

if (!SupportCalendar.length) {
  throw new Error(
    "CODE-002: SupportCalendar is empty or missing from CODE-001 context."
  );
}


if (!Roster.length) {
  throw new Error(
    "CODE-002: WeeklyRoster is empty or missing from CODE-001 context."
  );
}


if (!Engineers.length) {
  throw new Error(
    "CODE-002: EngineerMaster is empty or missing from CODE-001 context."
  );
}


// ------------------------------------------------------------
// 10. FIND TODAY'S SUPPORT CALENDAR
//
// CurrentDay comes directly from CODE-001.
//
// Example:
//
// CurrentDay = Tuesday
//
// Therefore only the Tuesday SupportCalendar row is used.
// ------------------------------------------------------------

const todayCalendar =
  SupportCalendar.find(row => {

    return (
      lower(row.Day) ===
      lower(CurrentDay)
    );

  });


// ------------------------------------------------------------
// 11. NO CALENDAR
// ------------------------------------------------------------

if (!todayCalendar) {

  return [{
    json: {

      Status:
        "MODULE-02 NO CALENDAR",

      TestMode,

      CurrentDate,

      CurrentDay,

      CurrentTime,

      Timezone:
        TimeZone,

      PlannedEngineerCount:
        0,

      PlannedEngineers:
        [],

      Reason:
        "No SupportCalendar configuration found for the selected day."

    }
  }];

}


// ------------------------------------------------------------
// 12. CHECK CALENDAR ACTIVE
// ------------------------------------------------------------

const CalendarActive =
  lower(todayCalendar.Active) === "yes";


if (!CalendarActive) {

  return [{
    json: {

      Status:
        "MODULE-02 CALENDAR INACTIVE",

      TestMode,

      CurrentDate,

      CurrentDay,

      CurrentTime,

      Timezone:
        TimeZone,

      Calendar: {

        Active:
          CalendarActive,

        ActiveShiftIDs:
          clean(todayCalendar.Active_Shifts)
            .split(",")
            .map(x => clean(x))
            .filter(Boolean),

        AllowedLevels:
          clean(todayCalendar.Allowed_Levels)
            .split(",")
            .map(x => clean(x))
            .filter(Boolean)

      },

      PlannedEngineerCount:
        0,

      PlannedEngineers:
        [],

      Reason:
        "Selected day's SupportCalendar is inactive. No engineer may be assigned."

    }
  }];

}


// ------------------------------------------------------------
// 13. READ SUPPORT CALENDAR SETTINGS
// ------------------------------------------------------------

const ActiveShiftIDs =
  clean(todayCalendar.Active_Shifts)
    .split(",")
    .map(x => clean(x))
    .filter(Boolean);


const AllowedLevels =
  clean(todayCalendar.Allowed_Levels)
    .split(",")
    .map(x => clean(x))
    .filter(Boolean);


const AssignmentMode =
  clean(todayCalendar.Assignment_Mode) ||
  "RoundRobin";


const Max_L1 =
  Number(todayCalendar.Max_L1 || 0);


const Max_L2 =
  Number(todayCalendar.Max_L2 || 0);


const Max_L3 =
  Number(todayCalendar.Max_L3 || 0);


// ------------------------------------------------------------
// 14. FILTER WEEKLY ROSTER FOR SELECTED DAY
//
// A roster row must satisfy:
//
//   A. Day matches CurrentDay
//   B. Effective_From <= CurrentDate
//   C. Effective_To >= CurrentDate
//
// CurrentDate comes from CODE-001.
// ------------------------------------------------------------

const TodayRoster =
  Roster.filter(row => {

    const rowDay =
      lower(row.Day);

    const effectiveFrom =
      clean(row.Effective_From);

    const effectiveTo =
      clean(row.Effective_To);


    // --------------------------------------------------------
    // A. DAY MUST MATCH
    // --------------------------------------------------------

    if (
      rowDay !==
      lower(CurrentDay)
    ) {

      return false;

    }


    // --------------------------------------------------------
    // B. EFFECTIVE START
    // --------------------------------------------------------

    if (
      effectiveFrom &&
      effectiveFrom > CurrentDate
    ) {

      return false;

    }


    // --------------------------------------------------------
    // C. EFFECTIVE END
    // --------------------------------------------------------

    if (
      effectiveTo &&
      effectiveTo < CurrentDate
    ) {

      return false;

    }


    return true;

  });


// ------------------------------------------------------------
// 15. FILTER BY ACTIVE SHIFT
//
// Only shifts configured as active for today's
// SupportCalendar are allowed.
//
// Example:
//
// Tuesday:
// Active_Shifts = S1,S2,S3,S4,S5
//
// ------------------------------------------------------------

const ShiftRoster =
  TodayRoster.filter(row => {

    const shiftID =
      clean(row.Shift_ID);

    return ActiveShiftIDs.some(
      id =>
        lower(id) ===
        lower(shiftID)
    );

  });


// ------------------------------------------------------------
// 16. FILTER BY ALLOWED ASSIGNMENT LEVEL
// ------------------------------------------------------------

const LevelRoster =
  ShiftRoster.filter(row => {

    const level =
      clean(row.Assignment_Level);

    return AllowedLevels.some(
      allowed =>
        lower(allowed) ===
        lower(level)
    );

  });


// ------------------------------------------------------------
// 17. BUILD ACTIVE ENGINEER MASTER LIST
//
// Only engineers with Active = Yes are allowed.
// ------------------------------------------------------------

const ActiveEngineerIDs =
  new Set(

    Engineers

      .filter(engineer =>
        lower(engineer.Active) === "yes"
      )

      .map(engineer =>
        lower(engineer.Member_ID)
      )

      .filter(Boolean)

  );


// ------------------------------------------------------------
// 18. MATCH ROSTER AGAINST ENGINEER MASTER
//
// The engineer must:
//
//   1. Exist in WeeklyRoster
//   2. Exist in EngineerMaster
//   3. Be Active in EngineerMaster
//   4. Be on an active shift
//   5. Have an allowed assignment level
// ------------------------------------------------------------

const PlannedEngineers =
  LevelRoster

    .filter(row => {

      const memberID =
        lower(row.Member_ID);

      return ActiveEngineerIDs.has(
        memberID
      );

    })

    .map(row => ({

      EngineerName:
        clean(row.Engineer_Name),

      MemberID:
        clean(row.Member_ID),

      AssignmentLevel:
        clean(row.Assignment_Level),

      ShiftID:
        clean(row.Shift_ID),

      ShiftDay:
        clean(row.Day),

      ShiftStart:
        clean(
          row.ShiftStart ??
          row.Shift_Start ??
          ""
        ),

      ShiftEnd:
        clean(
          row.ShiftEnd ??
          row.Shift_End ??
          ""
        ),

      RosterAvailable:
        lower(row.Available) === "yes"

    }));


// ------------------------------------------------------------
// 19. FILTER OUT ROSTER UNAVAILABLE ENGINEERS
// ------------------------------------------------------------

const AvailablePlannedEngineers =
  PlannedEngineers.filter(
    engineer =>
      engineer.RosterAvailable === true
  );


// ------------------------------------------------------------
// 20. COUNT ENGINEERS BY LEVEL
//
// These counts are informational at MODULE-02.
// Actual ticket capacity is handled later.
// ------------------------------------------------------------

const Level1Count =
  AvailablePlannedEngineers.filter(
    engineer =>
      lower(engineer.AssignmentLevel) === "level1"
  ).length;


const Level2Count =
  AvailablePlannedEngineers.filter(
    engineer =>
      lower(engineer.AssignmentLevel) === "level2"
  ).length;


const Level3Count =
  AvailablePlannedEngineers.filter(
    engineer =>
      lower(engineer.AssignmentLevel) === "level3"
  ).length;


// ------------------------------------------------------------
// 21. UNAVAILABLE / PLANNED ENGINEERS
//
// This is useful for diagnostics.
//
// Engineers who are in today's roster but unavailable
// according to WeeklyRoster are retained separately.
// ------------------------------------------------------------

const UnavailablePlannedEngineers =
  PlannedEngineers.filter(
    engineer =>
      engineer.RosterAvailable !== true
  );


// ------------------------------------------------------------
// 22. RETURN MODULE-02 RESULT
// ------------------------------------------------------------

return [{
  json: {

    Status:
      "MODULE-02 OK",

    TestMode,

    CurrentDate,

    CurrentDay,

    CurrentTime,

    Timezone:
      TimeZone,


    // --------------------------------------------------------
    // CALENDAR
    // --------------------------------------------------------

    Calendar: {

      Active:
        CalendarActive,

      ActiveShiftIDs,

      AllowedLevels,

      AssignmentMode,

      Max_L1,

      Max_L2,

      Max_L3

    },


    // --------------------------------------------------------
    // ROSTER STATISTICS
    // --------------------------------------------------------

    Roster: {

      TotalRosterRows:
        Roster.length,

      TodayRosterCount:
        TodayRoster.length,

      ShiftRosterCount:
        ShiftRoster.length,

      LevelRosterCount:
        LevelRoster.length

    },


    // --------------------------------------------------------
    // ENGINEER MASTER STATISTICS
    // --------------------------------------------------------

    EngineerMaster: {

      TotalEngineers:
        Engineers.length,

      ActiveEngineers:
        ActiveEngineerIDs.size

    },


    // --------------------------------------------------------
    // PLANNED ENGINEERS
    // --------------------------------------------------------

    PlannedEngineerCount:
      AvailablePlannedEngineers.length,

    PlannedEngineers:
      AvailablePlannedEngineers,


    // --------------------------------------------------------
    // LEVEL COUNTS
    // --------------------------------------------------------

    EligibleLevel1Count:
      Level1Count,

    EligibleLevel2Count:
      Level2Count,

    EligibleLevel3Count:
      Level3Count,


    // --------------------------------------------------------
    // UNAVAILABLE PLANNED ENGINEERS
    // --------------------------------------------------------

    UnavailableEngineerCount:
      UnavailablePlannedEngineers.length,

    UnavailableEngineers:
      UnavailablePlannedEngineers

  }
}];

// ============================================================
// CODE-002 – Calculate Workload
// ============================================================
// PURPOSE
// Calculate CURRENT ConnectWise workload by engineer.
//
// WORKLOAD RULE:
// ONLY these configured statuses count:
//   *Assigned to Level 1
//   *Assigned to Level 2
//   *Assigned to Level 3
//   *In Progress
//
// ALL OTHER STATUSES ARE EXCLUDED.
//
// CONFIGURATION:
// All workload limits come dynamically from CFG-001.
//
// NO HARD-CODED WORKLOAD LIMITS.
// ============================================================


// ============================================================
// 1. READ MERGE INPUT
// ============================================================

const items = $input.all();

if (!items || items.length === 0) {
  throw new Error(
    'CODE-002 received no ticket input from Merge.'
  );
}


// ============================================================
// 2. READ CFG-001
// ============================================================

let WorkflowConfig;

try {

  const cfgItem = $('CFG-001').first();

  WorkflowConfig =
    cfgItem?.json?.WorkflowConfig ?? null;

}
catch (error) {

  throw new Error(
    `Unable to read CFG-001 configuration. ` +
    `Make sure the configuration Code node is named exactly "CFG-001". ` +
    `Original error: ${error.message}`
  );

}


if (
  !WorkflowConfig ||
  typeof WorkflowConfig !== 'object'
) {

  throw new Error(
    'WorkflowConfig was not found in CFG-001 output.'
  );

}


// ============================================================
// 3. READ DYNAMIC WORKLOAD LIMITS
// ============================================================

const maxLevel1 =
  Number(WorkflowConfig.MaxLevel1Tickets);

const maxLevel2 =
  Number(WorkflowConfig.MaxLevel2Tickets);

const maxLevel3 =
  Number(WorkflowConfig.MaxLevel3Tickets);


if (!Number.isFinite(maxLevel1)) {

  throw new Error(
    `MaxLevel1Tickets is missing or invalid. ` +
    `Received: ${WorkflowConfig.MaxLevel1Tickets}`
  );

}


if (!Number.isFinite(maxLevel2)) {

  throw new Error(
    `MaxLevel2Tickets is missing or invalid. ` +
    `Received: ${WorkflowConfig.MaxLevel2Tickets}`
  );

}


if (!Number.isFinite(maxLevel3)) {

  throw new Error(
    `MaxLevel3Tickets is missing or invalid. ` +
    `Received: ${WorkflowConfig.MaxLevel3Tickets}`
  );

}


// ============================================================
// 4. BOOLEAN NORMALIZATION
// ============================================================

function toBoolean(
  value,
  defaultValue = false
) {

  if (typeof value === 'boolean') {
    return value;
  }

  const normalized =
    String(value ?? '')
      .trim()
      .toLowerCase();

  if (
    normalized === 'yes' ||
    normalized === 'true' ||
    normalized === '1'
  ) {
    return true;
  }

  if (
    normalized === 'no' ||
    normalized === 'false' ||
    normalized === '0'
  ) {
    return false;
  }

  return defaultValue;
}


const enableLevel3 =
  toBoolean(
    WorkflowConfig.EnableLevel3,
    true
  );


const checkInOutBoard =
  toBoolean(
    WorkflowConfig.CheckInOutBoard,
    true
  );


const checkCurrentShift =
  toBoolean(
    WorkflowConfig.CheckCurrentShift,
    true
  );


const useSkillRouting =
  toBoolean(
    WorkflowConfig.UseSkillRouting,
    false
  );


// ============================================================
// 5. READ WORKLOAD STATUSES FROM CFG-001
// ============================================================
//
// CFG-001 should normally provide:
//
// WorkloadStatusesRaw:
// "*Assigned to Level 1,*Assigned to Level 2,
//  *Assigned to Level 3,*In Progress"
//
// If Raw is unavailable, use WorkloadStatuses array.
//
// If BOTH are unavailable, use the required four-status
// safety default.
//
// ============================================================

let workloadStatuses = [];


// ------------------------------------------------------------
// First preference: WorkloadStatuses array
// ------------------------------------------------------------

if (
  Array.isArray(
    WorkflowConfig.WorkloadStatuses
  )
) {

  workloadStatuses =
    WorkflowConfig.WorkloadStatuses
      .map(
        status =>
          String(status ?? '').trim()
      )
      .filter(Boolean);

}


// ------------------------------------------------------------
// Second preference: WorkloadStatusesRaw
// ------------------------------------------------------------

if (
  workloadStatuses.length === 0 &&
  WorkflowConfig.WorkloadStatusesRaw
) {

  workloadStatuses =
    String(
      WorkflowConfig.WorkloadStatusesRaw
    )
      .split(',')
      .map(
        status =>
          status.trim()
      )
      .filter(Boolean);

}


// ------------------------------------------------------------
// Safety fallback
// ------------------------------------------------------------

if (
  workloadStatuses.length === 0
) {

  workloadStatuses = [
    '*Assigned to Level 1',
    '*Assigned to Level 2',
    '*Assigned to Level 3',
    '*In Progress'
  ];

}


// ============================================================
// 6. NORMALIZE STATUS
// ============================================================

function normalizeStatus(value) {

  return String(value ?? '')
    .trim()
    .toLowerCase();

}


// ============================================================
// 7. GET TICKET STATUS
// ============================================================

function getTicketStatus(ticket) {

  // ConnectWise:
  // status: { name: "..." }

  if (
    ticket &&
    typeof ticket.status === 'object' &&
    ticket.status !== null
  ) {

    return String(
      ticket.status.name ?? ''
    ).trim();

  }


  // Possible flat fields

  return String(
    ticket?.status ??
    ticket?.Status ??
    ticket?.StatusName ??
    ''
  ).trim();

}


// ============================================================
// 8. GET ENGINEER NAME
// ============================================================

function getEngineerName(ticket) {

  // ConnectWise:
  // owner: { name: "..." }

  if (
    ticket?.owner &&
    typeof ticket.owner === 'object'
  ) {

    return String(
      ticket.owner.name ?? ''
    ).trim();

  }


  if (
    ticket?.owner &&
    typeof ticket.owner === 'string'
  ) {

    return ticket.owner.trim();

  }


  return String(
    ticket?.EngineerName ??
    ticket?.engineerName ??
    ticket?.Engineer ??
    ticket?.assignedTo ??
    ticket?.AssignedTo ??
    ''
  ).trim();

}


// ============================================================
// 9. STATUS MATCHING
// ============================================================
//
// Configuration supports:
//   Exact:
//      "In Progress"
//
//   Wildcard:
//      "*Assigned to Level 1"
//
// Wildcard means:
//   ticket status contains the configured text.
//
// ============================================================

function statusMatches(
  ticketStatus,
  configuredStatus
) {

  const ticketValue =
    normalizeStatus(ticketStatus);

  const configValue =
    normalizeStatus(configuredStatus);


  if (
    !ticketValue ||
    !configValue
  ) {

    return false;

  }


  // Exact match

  if (
    ticketValue === configValue
  ) {

    return true;

  }


  // Wildcard/prefix "*"

  if (
    configValue.startsWith('*')
  ) {

    const searchText =
      configValue
        .substring(1)
        .trim();

    if (!searchText) {
      return false;
    }

    return ticketValue.includes(
      searchText
    );

  }


  return false;

}


// ============================================================
// 10. ENGINEER MASTER
// ============================================================
//
// Assignment levels are fixed organizational data.
// Workload limits remain dynamic from CFG-001.
//
// ============================================================

const engineers = [

  // LEVEL 3

  {
    EngineerName: 'Gunesh Malviya',
    Level: 3,
    MaxTickets: maxLevel3
  },

  {
    EngineerName: 'Amrish Patel',
    Level: 3,
    MaxTickets: maxLevel3
  },

  {
    EngineerName: 'Parth Patel',
    Level: 3,
    MaxTickets: maxLevel3
  },

  {
    EngineerName: 'Heta Shah',
    Level: 3,
    MaxTickets: maxLevel3
  },

  {
    EngineerName: 'Hemang Vyas',
    Level: 3,
    MaxTickets: maxLevel3
  },


  // LEVEL 2

  {
    EngineerName: 'Dhaval Shah',
    Level: 2,
    MaxTickets: maxLevel2
  },

  {
    EngineerName: 'Hardik Parekh',
    Level: 2,
    MaxTickets: maxLevel2
  },

  {
    EngineerName: 'Shreyans Kothari',
    Level: 2,
    MaxTickets: maxLevel2
  },

  {
    EngineerName: 'Nagendra Singh',
    Level: 2,
    MaxTickets: maxLevel2
  },


  // LEVEL 1

  {
    EngineerName: 'Krunal More',
    Level: 1,
    MaxTickets: maxLevel1
  },

  {
    EngineerName: 'Vishal Santoki',
    Level: 1,
    MaxTickets: maxLevel1
  }

];


// ============================================================
// 11. NORMALIZE ENGINEER NAME
// ============================================================

function normalizeName(value) {

  return String(value ?? '')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase();

}


// ============================================================
// 12. ENGINEER LOOKUP
// ============================================================

const engineerMap = new Map();

for (const engineer of engineers) {

  engineerMap.set(
    normalizeName(
      engineer.EngineerName
    ),
    engineer
  );

}


// ============================================================
// 13. CREATE WORKLOAD STRUCTURE
// ============================================================

const workloadMap = new Map();

for (const engineer of engineers) {

  workloadMap.set(
    normalizeName(
      engineer.EngineerName
    ),
    {
      EngineerName:
        engineer.EngineerName,

      Level:
        engineer.Level,

      TicketCount:
        0,

      MaxTickets:
        engineer.MaxTickets,

      AvailableCapacity:
        engineer.MaxTickets,

      AtCapacity:
        false,

      AssignedTickets:
        []
    }
  );

}


// ============================================================
// 14. PROCESS TICKETS
// ============================================================

const unassignedTickets = [];

const unknownEngineerTickets = [];

let workloadTicketCount = 0;

let excludedTicketCount = 0;


// ------------------------------------------------------------
// Process every input ticket
// ------------------------------------------------------------

for (const item of items) {

  const ticket =
    item?.json ?? {};


  // ----------------------------------------------------------
  // Ticket ID
  // ----------------------------------------------------------

  const ticketId =
    ticket.id ??
    ticket.ID ??
    ticket.ticketId ??
    ticket.TicketID ??
    null;


  // ----------------------------------------------------------
  // Status
  // ----------------------------------------------------------

  const ticketStatus =
    getTicketStatus(ticket);


  // ----------------------------------------------------------
  // Engineer
  // ----------------------------------------------------------

  const engineerName =
    getEngineerName(ticket);


  // ----------------------------------------------------------
  // WORKLOAD STATUS FILTER
  // ----------------------------------------------------------

  const isWorkloadTicket =
    workloadStatuses.some(
      configuredStatus =>
        statusMatches(
          ticketStatus,
          configuredStatus
        )
    );


  // ----------------------------------------------------------
  // EXCLUDE NON-WORKLOAD STATUS
  // ----------------------------------------------------------

  if (!isWorkloadTicket) {

    excludedTicketCount++;

    continue;

  }


  // ----------------------------------------------------------
  // COUNT WORKLOAD TICKET
  // ----------------------------------------------------------

  workloadTicketCount++;


  // ----------------------------------------------------------
  // NO ENGINEER
  // ----------------------------------------------------------

  if (!engineerName) {

    unassignedTickets.push({

      TicketID:
        ticketId,

      Status:
        ticketStatus,

      EngineerName:
        '',

      Summary:
        ticket.summary ??
        ticket.Summary ??
        ''

    });

    continue;

  }


  // ----------------------------------------------------------
  // FIND ENGINEER
  // ----------------------------------------------------------

  const normalizedEngineer =
    normalizeName(
      engineerName
    );


  const engineer =
    engineerMap.get(
      normalizedEngineer
    );


  // ----------------------------------------------------------
  // UNKNOWN ENGINEER
  // ----------------------------------------------------------

  if (!engineer) {

    unknownEngineerTickets.push({

      TicketID:
        ticketId,

      Status:
        ticketStatus,

      EngineerName:
        engineerName,

      Summary:
        ticket.summary ??
        ticket.Summary ??
        ''

    });

    continue;

  }


  // ----------------------------------------------------------
  // KNOWN ENGINEER
  // ----------------------------------------------------------

  const workload =
    workloadMap.get(
      normalizedEngineer
    );


  workload.TicketCount++;

  workload.AssignedTickets.push({

    TicketID:
      ticketId,

    Status:
      ticketStatus,

    Summary:
      ticket.summary ??
      ticket.Summary ??
      ''

  });

}


// ============================================================
// 15. CALCULATE ENGINEER CAPACITY
// ============================================================

const WorkloadByEngineer =
  Array.from(
    workloadMap.values()
  );


for (
  const engineer
  of WorkloadByEngineer
) {

  engineer.AvailableCapacity =
    Math.max(
      0,
      engineer.MaxTickets -
      engineer.TicketCount
    );


  engineer.AtCapacity =
    engineer.TicketCount >=
    engineer.MaxTickets;

}


// ============================================================
// 16. LEVEL SUMMARY
// ============================================================

function buildLevelSummary(level) {

  const levelEngineers =
    WorkloadByEngineer.filter(
      engineer =>
        engineer.Level === level
    );


  const totalTickets =
    levelEngineers.reduce(
      (sum, engineer) =>
        sum +
        engineer.TicketCount,
      0
    );


  const totalCapacity =
    levelEngineers.reduce(
      (sum, engineer) =>
        sum +
        engineer.MaxTickets,
      0
    );


  const availableCapacity =
    levelEngineers.reduce(
      (sum, engineer) =>
        sum +
        engineer.AvailableCapacity,
      0
    );


  const atCapacityCount =
    levelEngineers.filter(
      engineer =>
        engineer.AtCapacity
    ).length;


  return {

    EngineerCount:
      levelEngineers.length,

    TotalTickets:
      totalTickets,

    TotalCapacity:
      totalCapacity,

    AvailableCapacity:
      availableCapacity,

    AtCapacityCount:
      atCapacityCount

  };

}


const Level1Summary =
  buildLevelSummary(1);

const Level2Summary =
  buildLevelSummary(2);

const Level3Summary =
  buildLevelSummary(3);


// ============================================================
// 17. CURRENT DATE / TIME
// ============================================================

const now =
  new Date();


const timeZone =
  String(
    WorkflowConfig.TimeZone ??
    'Asia/Kolkata'
  );


const CurrentDate =
  now.toLocaleDateString(
    'en-CA',
    {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }
  );


const CurrentTime =
  now.toLocaleTimeString(
    'en-GB',
    {
      timeZone,
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    }
  );


// ============================================================
// 18. FINAL WORKFLOW CONFIG
// ============================================================

const FinalWorkflowConfig = {

  Company:
    String(
      WorkflowConfig.Company ?? ''
    ),

  Board:
    String(
      WorkflowConfig.Board ?? ''
    ),

  TimeZone:
    timeZone,

  MaxLevel1Tickets:
    maxLevel1,

  MaxLevel2Tickets:
    maxLevel2,

  MaxLevel3Tickets:
    maxLevel3,

  EnableLevel3:
    enableLevel3,

  CheckInOutBoard:
    checkInOutBoard,

  CheckCurrentShift:
    checkCurrentShift,

  UseSkillRouting:
    useSkillRouting,

  WorkloadStatuses:
    workloadStatuses

};


// ============================================================
// 19. FINAL OUTPUT
// ============================================================

return [

  {
    json: {

      Status:
        'CODE-002 OK',

      WorkflowConfig:
        FinalWorkflowConfig,

      WorkloadByEngineer:
        WorkloadByEngineer,

      Level1Summary:
        Level1Summary,

      Level2Summary:
        Level2Summary,

      Level3Summary:
        Level3Summary,

      UnassignedTickets:
        unassignedTickets,

      UnknownEngineerTickets:
        unknownEngineerTickets,

      TotalInputTickets:
        items.length,

      WorkloadTicketCount:
        workloadTicketCount,

      ExcludedTicketCount:
        excludedTicketCount,

      UnassignedTicketCount:
        unassignedTickets.length,

      UnknownEngineerTicketCount:
        unknownEngineerTickets.length,

      CurrentDate:
        CurrentDate,

      CurrentTime:
        CurrentTime

    }
  }

];
